NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Ezekiel'

CHAPTERS = {
    1: {
        1: 'Det hende i det trettiande året, den femte dagen i den fjorde månaden, då eg var millom dei bortførde attmed Kebarelvi, at himmelen opna seg og eg såg syner frå Gud.',
        2: 'Den femte dagen i månaden - det var endå det femte året etter kong Jojakin vart burtførd -',
        3: 'då kom Herrens ord til Ezekiel Buzison, presten, i Kaldæarlandet attmed Kebarelvi. Herrens hand kom der yver honom.',
        4: 'Og eg såg, og sjå, ei stormflaga kom nordanfrå, ei stor sky og eld som kvervla seg i hop, med eit skin rundt ikring, og ut or honom, midt utor elden, tedde det seg eitkvart nett som sylvblanda gull.',
        5: 'Og midt der-utor kom det noko som liktest på fire livende. Og soleis var dei på skap: Dei hadde manneskapnad.',
        6: 'Og fire andlit var det på kvart eitt av deim og fire vengjer på kvart eitt av deim.',
        7: 'Og føterne deira, dei var beine, og fotbladi deira var som kalveklauver, og dei glima som skinande kopar.',
        8: 'Og dei hadde mannehender under vengjerne på alle fire sidorne. Og med andliti deira og vengjerne deira var det soleis på alle fire:',
        9: 'Vengjerne deira nådde i hop, den eine med hin. Dei snudde seg ikkje når dei gjekk; kvart eitt gjekk beint fram.',
        10: 'Og deira andlit var som eit mannsandlit på skap, og alle fire hadde løve-andlit på høgresida, og alle fire hadde ukse-andlit på vinstresida, og alle fire hadde ørne-andlit.',
        11: 'Det var no andliti deira. Og vengjerne deira breidde seg ut ovantil. Med tvo av vengjerne sine nådde eitt livende i hop med hitt, og med tvo løynde det likamen sin.',
        12: 'Og kvart eitt av deim gjekk beint fram. Kvar åndi vilde ganga, dit gjekk dei; dei snudde seg ikkje når dei gjekk.',
        13: 'Og livendi såg ut som gløder i eld, brennende, som kyndlar å sjå til; elden for att og fram millom livendi, og det skein av honom, og ut or elden gjekk det ljon.',
        14: 'Og livendi for att og fram, nett som eldingar å sjå til.',
        15: 'Og eg såg livendi, og sjå, det var eit hjul på jordi innmed kvart eitt livende, og dei viste ut mot fire sidor.',
        16: 'Og hjuli såg ut nett som dei skulde vera gjorde av eitkvart som liktest på krysolit, og alle fire var eins på skapnad, og det såg ut som dei var gjorde so at eitt hjul var inni hitt.',
        17: 'Til alle fire sidorne kunde dei ganga; dei snudde seg ikkje når dei gjekk.',
        18: 'Og hjulfalli var høge og skræmelege, og so var dei fullsette med augo rundt ikring på alle fire.',
        19: 'Og når livendi gjekk, so gjekk hjuli attmed deim, og når livendi lyfte seg frå jordi, so lyfte hjuli seg med.',
        20: 'Kvar åndi vilde ganga, gjekk dei, nett dit som åndi vilde ganga. Og hjuli lyfte seg med deim, for åndi åt livendi var i hjuli.',
        21: 'Når livendi gjekk, so gjekk dei, og når dei stod, so stod dei, og når dei lyfte seg frå jordi, so lyfte hjuli seg med, for åndi åt livendi var i hjuli.',
        22: 'Og uppyver hovudi på livendi var det noko på skap som ein kvelv, som underfull krystall å sjå til, utspana uppyver hovudi deira.',
        23: 'Og uppunder kvelven rette vengjerne deira seg beint ut, kvar mot annan. Kvart einskilt av deim hadde tvo vengjer som dei løynde likamen sin med.',
        24: 'Og eg høyrde ljomen av vengjerne deira, som ljomen av store vatn, som røysti åt den Allmegtige, når dei gjekk, ein ljomande gny som gnyen frå eit herlæger. Når dei stod stilt, let dei vengjerne siga.',
        25: 'Og det ljoma ei røyst uppyver kvelven som var yver hovudi deira. Når dei då stod stilt, let dei vengjerne siga.',
        26: 'Og uppyver kvelven som var yver hovudi deira, var det noko som såg ut som safirstein, på skap som ein kongsstol. Og uppå kongsstol-skapnaden sat det ein som liktest på eit menneskje.',
        27: 'Og eg såg noko liksom sylvblanda gull, sjåande til liksom eld med ein ljosgard ikring, frå det som var sjåande til å vera lenderne hans og so uppetter. Og frå det som var sjåande til å vera lenderne hans og nedetter såg eg noko liksom eld å sjå til, med eit skin rundt ikring.',
        28: 'Liksom syni av bogen i skyi på ein regndag, soleis var syni av skinet rundt ikring. Soleis var openberringi av Herrens herlegdom å sjå til. Og då eg fekk sjå det, fall eg ned på mitt andlit, og eg høyrde røysti av ein som tala.',
    },
    2: {
        1: 'Og han sagde med meg: «Menneskjeson! Statt upp på føterne dine so eg kann få tala med deg!»',
        2: 'Og det kom ånd i meg med det same han tala med meg, og reiste meg upp på mine føter, og eg lydde på honom som tala til meg.',
        3: 'Og han sagde til meg: «Menneskjeson! Eg sender deg til Israels-borni, dei upprørske heidningar som hev gjort upprør imot meg. Dei sjølve og deira feder hev forbrote seg mot meg alt til den dag i dag.',
        4: 'Og til borni med dei harde andliti og stive hjarto - eg sender deg til deim. Og du skal segja med deim: «So segjer Herren, Herren.»',
        5: 'Og dei, anten dei lyder på eller ikkje - for ei tråssug ætt er dei - so skal dei få vita at ein profet hev vore midt imillom deim.',
        6: 'Og du, menneskjeson! Ikkje ottast deim! og ordi deira ottast du ikkje! For tistlar og klunger er hjå deg, og med skorpionar bur du. For ordi deira ottast du ikkje, og for deira åsyn vere du ikkje forfærd! For ei tråssug ætt er dei.',
        7: 'Og du skal tala ordi mine til deim, anten dei lyder på eller ikkje, for tråssuge, det er dei.',
        8: 'Men du, menneskjeson, lyd på det som eg vil tala til deg! Ver ikkje tråssug som den tråssuge ætti! Lat upp munnen din og et det som eg gjev deg!»',
        9: 'Og som eg såg, og sjå, ei hand var rett ut til meg. Og sjå, i den var ein bokrull.',
        10: 'Og han rulla honom upp framfor mi åsyn, og han var fullskriven inni og utanpå. Og skrive var det på honom syrgjesongar, sukkar og verop.',
    },
    3: {
        1: 'Og han sagde med meg: «Menneskjeson! Et det du finn! Et denne bokrullen, og gakk, tala til Israels-lyden!»',
        2: 'Og eg let upp min munn, og han gav meg denne bokrullen å eta.',
        3: 'Og han sagde med meg: «Menneskjeson! Din buk skal du metta, og dine innvolar skal du fylla med denne bokrullen som eg gjev deg.» Og eg åt, og han var i munnen min søt som honning.',
        4: 'Og han sagde med meg: «Menneskjeson! Gakk av stad til Israels hus og tala til deim med mine ord!',
        5: 'For du vert ikkje send til eit folk med ugreidt mål og tungmælt tunga, men til Israels-lyden.',
        6: 'Ikkje til mange folkeslag med ugreidt mål og tungmælt tunga, so du ikkje skynar ordi deira, i sanning, um eg sende deg til deim, so skulde dei høyra på deg.',
        7: 'Men Israels-lyden skal ikkje vilja lyda på deg, for dei vil ikkje lyda på meg. For all Israels-lyden - harde skallar og stinne hjarto hev dei.',
        8: 'Sjå, eg gjer di åsyn hard mot deira åsyn og di panna hard mot deira pannor.',
        9: 'Som demant, hardare enn stein, gjer eg di panna. Du skal ikkje ottast deim og ikkje vera forfærd framfor deira åsyn, for ei tråssug ætt er dei.»',
        10: 'Og han sagde med meg: «Menneskjeson! Alle mine ord som eg talar til deg, tak deim inn i ditt hjarta og høyr deim med dine øyro!',
        11: 'Og gakk av stad til dei burtførde, til ditt folks born, og tala til deim og seg med deim: So segjer Herren, Herren - anten dei vil lyda på eller ei.»',
        12: 'Då lyfte åndi meg upp, og eg høyrde attanfor meg ein dynjande sterk ljom: «Lova vere Herrens herlegdom frå den staden der han er!»',
        13: 'likeins ljomen av dei fire livende, når vengjerne deira møttest, og ljomen av hjuli attmed deim, ein dynjande sterk ljom.',
        14: 'Åndi lyfte meg då upp og tok meg med, og eg for av stad, hugsår og uppøst i mi ånd, og Herrens hand var sterk yver meg.',
        15: 'Og eg kom til dei burtførde i Tel-Abib som budde attmed Kebarelvi, til den staden der dei budde, og der sat eg hjå deim i tri dagar, hugstolen og reint ifrå meg.',
        16: 'So hende det etter sju dagar at Herrens ord kom til meg; han sagde:',
        17: '«Menneskjeson! Til vaktar hev eg sett deg for Israels-lyden; når du då høyrer eit ord frå min munn, skal du vara deim åt frå meg.',
        18: 'Når eg segjer til den ugudlege: «Du skal døy,» og du ikkje varar honom åt, og ikkje talar og varar den ugudlege åt for hans ugudlege veg, til frelsa for hans liv, då skal han, den ugudlege, døy for si misgjerning, men hans blod vil eg krevja av di hand.',
        19: 'Og når du varar den ugudlege, men han vender ikkje um frå si gudløysa og frå sin ugudlege veg, då skal han døy for si misgjerning, men du hev berga di sjæl.',
        20: 'Og når ein rettferdig vender seg frå si rettferd og gjer urett, so vil eg leggja støyt framfor hans åsyn; - han skal døy. Um du ikkje hev vara honom åt, skal han døy i si synd, og den rettferdi som han gjorde, skal ikkje verta ansa, men hans blod vil eg krevja av di hand.',
        21: 'Men um du hev vara den rettferdige, at rettferdig mann skal ikkje synda, og han då ikkje syndar, då skal han liva, sidan han let seg vara, og du hev berga di sjæl.»',
        22: 'Og Herrens hand kom der yver meg, og han sagde med meg: «Statt upp og gakk ut i dalen, der vil eg tala med deg.»',
        23: 'Og eg stod upp og gjekk ut i dalen. Og sjå, der stod Herrens herlegdom lik den herlegdomen eg såg attmed elvi Kebar. Og eg fall ned på mitt andlit.',
        24: 'Men åndi kom i meg og reiste meg upp på føterne. Og han tala med meg og sagde til meg: «Gakk og steng deg inne i huset ditt!',
        25: 'Og du, menneskjeson. Sjå, dei skal binda deg med tog og setja deg fast med deim, so du ikkje kjem deg ut til å vera i lag med deim.',
        26: 'Og tunga di let eg hanga fast ved gomerne dine, so du vert mållaus og ikkje vert deim ein refsingsmann. For ei tråssug ætt er dei.',
        27: 'Men når eg talar med deg, vil eg opna munnen din; då skal du segja til deim: So segjer Herren, Herren: Den som vil lyda på, han lyde, og den som ikkje vil gjeva gaum, han late vera! For ei tråssug ætt er dei.»',
    },
    4: {
        1: 'Og du, menneskjeson! Tak deg ein tiglstein og rita av på honom ein by, Jerusalem!',
        2: 'Og laga til umlægringsverk mot byen, og bygg åtaksmurar mot honom, og kasta upp ein voll mot honom, og slå læger mot honom, og set upp murstangarar mot honom rundt ikring.',
        3: 'Og du, tak deg so ei jarnpanna og set henne til ein jarnvegg millom deg og byen; snu deg med andlitet mot honom, so han vert kringsett, og du skal kringsetja honom: eit teikn er det åt Israels-lyden.',
        4: 'Og du, legg deg på vinstre sida og legg på henne syndeskuldi åt Israels-lyden; like mange dagar som du ligg på henne, skal du bera deira syndeskuld.',
        5: 'Og eg let syndeskulds-åri deira vera som talet på dagarne for deg, tri hundrad og nitti dagar, so lenge skal du bera syndeskuldi åt Israels-lyden.',
        6: 'Og når du hev gjort dette frå deg, skal du andre gongen leggja deg på høgre sida og bera syndeskuldi åt Juda-lyden; i fyrti dagar - ein dag for kvart år - let eg deg bera henne.',
        7: 'Og mot Jerusalem, til å kringsetja det, skal du snu deg med andlitet og med berr arm, og du skal spå imot det.',
        8: 'Og sjå, eg bind deg med tog, so du ikkje skal snu deg frå den eine sida til hi fyrr du hev gjort frå deg kringsetjingsdagarne dine.',
        9: 'Og du, tak deg kveite og bygg og baunor og linsor og hirsa og spelt, og hav det i eit trog, og laga det til brød åt deg! I like mange dagar som du ligg på sida, i tri hundrad og nitti dagar, skal du eta det.',
        10: 'Og maten din skal eta etter vegt, tjuge lodd um dag. Frå tid til tid skal du eta det.',
        11: 'Og vatn skal du drikka etter mål, ein pott. Frå tid til tid skal du drikka det.',
        12: 'Og som ei byggkake skal du eta det, og med mannsskarn til brennefang skal du steikja det for deira åsyn.',
        13: 'Og Herren sagde: «Soleis skal Israels-borni eta sitt brød ureint hjå dei folki som eg vil driva deim burt til.»',
        14: 'Og eg sagde: «Ai, ei! Herre, Herre! Sjå, aldri vart sjæli mi sulka, og noko sjølvdaudt og ihelrive hev eg aldri ete frå min ungdom alt til no, og det hev ikkje kome ureint kjøt i min munn.»',
        15: 'Og han sagde med meg: «Sjå, eg gjev deg kumøk i staden for mannsskarn, so du kann steikja brødet ditt yver den.»',
        16: 'Og han sagde med meg: «Du menneskjeson! Sjå, eg bryt sund brødstaven for Jerusalem, og dei skal eta brød etter vegt og med otte og drikka vatn etter mål og med fælske,',
        17: 'so dei skal vanta brød og vatn og verta forstøkte både ein og hin, og vanmegtast for si misgjerning.»',
    },
    5: {
        1: 'Og du, menneskjeson! Tak deg eit kvast sverd! Til rakekniv skal du bruka det, og du skal føra det yver ditt hovud og skjegg; tak deg so ei skålvegt og skift det du hev raka av!',
        2: 'Ein tridjepart skal du brenna upp i eld midt i byen når kringsetjingsdagarne er lidne, og ein tridjepart skal du taka og slå med sverdet vida ikring, og ein tridjepart skal du spreida ut i vinden, og sverd vil draga ut etter deim.',
        3: 'Men du skal taka undan nokre få av deim og binda deim i kjolesnipparne dine.',
        4: 'Og av deim att skal du enn taka nokre og kasta deim midt inn i elden og brenna deim upp i eld. Derifrå skal koma eld yver all Israels-lyden.',
        5: 'So segjer Herren, Herren: Dette Jerusalem, midt imillom folki sette eg det, og land var det rundt ikring.',
        6: 'Men det hev sett seg upp mot mine lover, so det vart ugudlegare enn folki, og mot mine bodord, so dei vart verre enn landi rundt ikring; for mine lover vanvyrde dei, og i mine bodord ferdast dei ikkje.',
        7: 'Difor, so segjer Herren, Herren: Av di at de hev rasa verre enn heidningfolki rundt ikring dykk, ikkje ferdast i mine bodord og ikkje gjort etter mine lover, og jamvel ikkje gjort etter loverne åt heidningfolki som er rundt ikring dykk,',
        8: 'difor, so segjer Herren, Herren: Sjå, eg vil koma yver deg, eg og, og eg vil halda dom hjå deg midt framfor augo på heidningfolki.',
        9: 'Og eg skal gjera med deg det som eg ikkje fyrr hev gjort og aldri meir vil gjera, for all styggedomen din.',
        10: 'Difor skal foreldre eta borni sine hjå deg, og born eta foreldri sine. Og eg vil halda dom hjå deg, og strå alt som vert att av deg for alle vindar.',
        11: 'Difor, so sant som eg liver, segjer Herren, Herren, sanneleg, etter di du hev sulka min heilagdom med all din styggjedom og alle dine styggjor, so vil eg og snu meg frå, og mitt auga skal ikkje ynkast, og ikkje eg heller vil spara deg.',
        12: 'Tridjeparten av deg skal døy av sott og verta tynt av svolt midt i deg, og tridjeparten skal falla for sverd rundt kringum deg, og tridjeparten vil eg spreida for alle vindar, og sverd vil eg draga ut etter deim.',
        13: 'Og all min vreide skal verta uthelt, og eg vil svala min harm på deim og hemna meg. Då skal dei sanna at eg, Herren, hev tala i min brennhug når eg heller ut all min harm på deim.',
        14: 'Og eg vil gjera deg til audn og til spott millom folki som er rundt kringum deg, framfor augo på kvar ein som fer framum.',
        15: 'Du skal verta til spott og håd, ei åtvaring og ei skræma for folki som er rundt kringum deg, når eg held dom yver deg med vreide og med harm og med harmfulle refsingar - eg, Herren hev tala -',
        16: 'når eg sender ibland deim dei vonde hunger-pilerne som er etla til tynarverk, deim eg sender til å tyna dykk med, når eg let svolten herja dykk og bryt sund brødstaven for dykk.',
        17: 'Eg vil senda yver dykk hunger og udyr, og dei skal gjera deg barnlaus, og sott og blod skal ganga yver deg, og sverd vil eg lata koma yver deg. Eg Herren, hev tala.',
    },
    6: {
        1: 'Og Herrens ord kom til meg; han sagde;',
        2: 'Menneskjeson! Vend di åsyn mot Israelsfjelli og spå mot deim.',
        3: 'Og du skal segja: De Israelsfjell, høyr ordi frå Herren, Herren! So segjer Herren, Herren til fjelli og til haugarne, til gili og til dalarne: Sjå, eg let sverd koma yver dykk og øyder dykkar offerhaugar.',
        4: 'Og dykkar altar skal verta lagde i øyde og dykkar solstolpar sundkrasa, og eg vil lata dykkar gjennomstungne falla framfor augo på dykkar ufysne avgudar.',
        5: 'Og eg vil leggja liki av Israels-borni framfor augo på dykkar ufysne avgudar og strå beini dykkar rundt kringum dykkar altar.',
        6: 'På kvar einaste stad der de bur, skal byarne verta lagde i øyde og offerhaugarne verta aude, so altari dykkar kann verta øydelagde og aude og dykkar ufysne avgudar sundkrasa og upp i inkje og solstolparne dykkar nedhogne og dykkar verk utstrokne;',
        7: 'og gjennomstungne skal falla midt ibland dykk. Og de skal sanna at eg er Herren.',
        8: 'Men nokre vil eg leiva, med di sume av dykk slepp undan sverdet millom folkeslagi, når de vert spreidde kringum i landi.',
        9: 'Og dei av dykk som slepp undan, skal minnast meg millom folki som dei er burtførde til, når eg hev knasa deira utrue hjarta som veik ifrå meg, og deira augo som i utruskap søkte etter deira ufysne avgudar. Og dei skal styggjast ved seg sjølve for det vonde dei hev gjort, med alle sine styggjor.',
        10: 'Og dei skal sanna at eg er Herren. Ikkje fåfengt hev eg tala um å senda denne ulukka på deim.',
        11: 'So segjer Herren, Herren: Slå i hop handlovarne dine og trappa med foten og ropa: «Ai, ei!» yver alle dei vonde styggjorne i Israels-lyden; for dei skal falla for sverd, svolt og sott.',
        12: 'Den som er langt burte, skal døy av sotti, og den som er nær, skal falla for sverdet, og den som er leivd og berga, skal døy av svolten, og eg vil tøma min harm yver deim.',
        13: 'Og de skal sanna et eg er Herren, når deira gjenomstungne ligg midt imillom deira ufysne avgudar, rundt kringum altari deira, på kvar ein høg haug, på alle fjelltoppar og under kvart eit grønt tre og under kvar ei lauvrik eik, på den staden der dei ofra godange åt dei ufysne avgudarne sine.',
        14: 'Og eg vil retta ut handi mi mot deim og gjera landet til audn og øyda - verre enn Dibla-øydemarki - kvar dei so bur, og dei skal sanna at eg er Herren.',
    },
    7: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Og du, menneskjeson! So segjer Herren, Herren med Israels land: Ende! Komen er enden yver landsens fire hyrno.',
        3: 'No er enden komen yver deg, og eg vil senda vreiden min mot deg og døma deg etter åtferdi di, og eg vil leggja på deg alle dine styggjor.',
        4: 'Og mitt auga skal ikkje spara deg, og miskunn gjer eg ikkje; men åtferdi di vil eg leggja på deg, og dine styggjor skal vera midt i deg, og de skal sanna at eg er Herren.',
        5: 'So segjer Herren, Herren: Ulukka, ei ulukka ein gong for alle, sjå, ho kjem.',
        6: 'Ein ende kjem, ja, enden kjem, han vaknar imot deg, sjå, ho kjem.',
        7: 'No er det din tur, du som i landet bur. Tidi er komi, nær er dagen med ståkande rådløysa og ikkje med fagnadrop på fjelli.',
        8: 'No, um eit lite bil, vil eg renna ut min harm yver deg og tøma ut all min vreide på deg og døma deg etter åtferdi di, og eg vil leggja på deg alle dine styggjor.',
        9: 'Og mitt auga skal ikkje spara deg, og miskunn gjer eg ikkje; som di åtferd hev vore, let eg deg få det, og dine styggjor skal midt i deg vera. Og de skal sanna at eg, Herren, slær.',
        10: 'Sjå, dagen! sjå, det kjem! Lagnadsstundi tek til; riset blømer, ovmodet grønkar.',
        11: 'Valdsgiren reiser seg til eit ris yver gudløysa. Ikkje noko av deim, inkje av deira ståkande hop, inkje av deira bråk, inkje av deira herlegdom vert att hjå deim.',
        12: 'Tidi er komi, dagen er nær. Kjøparen fagne seg ikkje, og seljaren syrgje ikkje! For vreide logar mot heile deira hop.',
        13: 'For seljaren skal ikkje få att det han selde, um han enn er i live, for syni mot heile hopen skal ikkje snu attende, og i si misgjerning skal ingen kunna verja sitt liv.',
        14: 'Dei blæs i stridslur og bur seg vel i alt, men ingen fer ut til striden; for min harm er imot heile deira hop.',
        15: 'Sverdet ute, sotti og svolten inne; den som er på marki, skal døy for sverd, og den som er i byen, honom skal svolt og sott tyna.',
        16: 'Og slepp det undan einkvar utav deim, skal dei vera på fjelli som duvor i dalarne, alle med klagelæte, kvar og ein for si misgjerning.',
        17: 'Alle hender skal siga, og alle kne skal verta veike som vatn.',
        18: 'Og dei skal gyrda seg med sekk, og skjelving skal hylja deim, og kvart eit andlit skal blygjast av skam, og kvart hovud skal vera fleinskalla.',
        19: 'Sylvet sitt skal dei kasta på gatorne, og gullet sitt skal dei vyrda som saur. Deira sylv og gull skal ikkje kunna berga deim på Herrens vreide-dag; dei skal ikkje kunna metta si sjæl eller fylla sin mage med det, for det hev vorte ein støytestein til misgjerning;',
        20: 'og den glimande prydnadsting av det hev dei bruka til storlæte, og dei hev gjort sine styggjelege bilæte av det, sine ufyselege avgudar; difor gjer eg det til saur for deim.',
        21: 'Og eg vil lata framande hender rana det og gudlause på jordi gjera det til herfang, og dei skal vanhelga det.',
        22: 'Og eg vil snu mi åsyn frå deim. Og ransmenner skal vanhelga min skatt; dei skal brjota seg inn åt honom og vanhelga honom.',
        23: 'Gjer lekkja i stand! for landet er fullt av blod-domar, og byen er full av valdsverk.',
        24: 'Og eg vil lata dei verste av heidningarne koma, og dei skal eigna til seg husi deira. Og eg vil gjera ende på ovmodet hjå dei hardsette, og heilagdomarne deira skal verta vanhelga.',
        25: 'Rædsla kjem, og dei skal søkja fred, men ingen finna.',
        26: 'Ulukka på ulukka skal koma, fretnad på fretnad fær ein høyra; og dei skal søkja etter syn hjå profeten, lov skal kverva for presten, og råder for dei gamle.',
        27: 'Kongen skal syrgja, og fyrsten skal klæda seg i fælske, og henderne på landslyden skal skjelva. Etter åtferdi deira vil eg gjera med deim, og med deira domar vil eg døma deim, og dei skal sanna at eg er Herren.',
    },
    8: {
        1: 'Og det hende i det sette året, den femte dagen i sette månaden, medan eg sat i huset mitt, og styresmennerne i Juda sat framfor mi åsyn, at Herrens, Herrens hand fall på meg der.',
        2: 'Og eg såg, og sjå, ein skapnad, sjåande til som eld; frå det som var sjåande av lenderne hans og nedetter som eld, og frå hans lender og uppetter var det som ei glima, som sylvblanda gull.',
        3: 'Og han rette ut eitkvart som liktest på ei hand, og tok meg i ein lokk av hovudhåret, og åndi lyfte meg upp millom jord og himmel og førde meg til Jerusalem i syner frå Gud, dit der ein gjeng inn til den indre fyregarden gjenom den porten som snur mot nord, der som harmings-bilætet stod, det som valda harm.',
        4: 'Og sjå, der var herlegdomen åt Israels Gud, liksom den syni eg hadde set i dalen.',
        5: 'Og han sagde med meg: «Menneskjeson! Lyft augo dine nordetter!» Og eg lyfte augo nordetter, og sjå, nordanfor altarporten var dette harmings-bilætet attmed inngangen.',
        6: 'Og han sagde med meg: «Menneskjeson! Ser du kva dei gjer? Store styggjor er det som Israels-lyden gjer her, so eg lyt fara langt burt ifrå heilagdomen min. Men du skal få sjå store styggjor.»',
        7: 'Og han let meg koma til inngangen åt fyregarden. Og eg såg, å sjå, det var eit hol i veggen.',
        8: 'Og han sagde med meg: «Menneskjeson! Brjot igjenom veggen!» Og eg braut meg igjenom veggen, og sjå, der var ei dør.',
        9: 'Og han sagde med meg: «Gakk inn og sjå dei vonde styggjor som dei gjer der!»',
        10: 'Og eg gjekk inn og såg, og sjå, der var alle slag bilæte av krek og firføtingar, styggedom, og alle dei ufysne avgudarne åt Israels-lyden, innrita på veggjerne rundt ikring.',
        11: 'Og framfyre deim stod sytti mann, styresmennerne i Israels-lyden, og Ja’azanja Safansson stod midt imillom deim, og kvar og ein hadde eit røykjelseskjerald i handi, og det steig upp ange av røykjelseskyi.',
        12: 'Og han sagde med meg: «Hev du set, menneskjeson, kva styresmennerne i Israels-lyden fer med i myrkret, kvar i sitt bilæt-rom? For dei segjer: «Herren ser oss ikkje; Herren hev vendt seg burt frå landet.»»',
        13: 'Og han sagde med meg: «Du skal enn få sjå store styggjor som dei fer med.»',
        14: 'Og han let meg koma åt inngangen til porten på Herrens hus, den som snur mot nord. Og sjå, der sat kvinnorne og gret for Tammus.',
        15: 'Og han sagde med meg: «Hev du set, menneskjeson? Du skal enn få sjå styggjor, større enn desse.»',
        16: 'Og han let meg koma i den indre fyregarden til Herrens hus. Og sjå, attmed inngangen til Herrens tempel, millom forhalli og altaret, var det ikring fem og tjuge menner; dei snudde ryggen til Herrens tempel og andliti i aust, og dei lutte seg austetter og bad til soli.',
        17: 'Og han sagde med meg: «Hev du set det, menneskjeson? Kunde ikkje Juda-lyden nøgja seg med å gjera dei styggjor dei her hev gjort, men måtte fylla landet med vald og atter harma meg upp? Og sjå kor dei no held kvisten upp for nosi!',
        18: 'So vil då eg og fara fram i vreide; mitt auga skal ikkje spara, og miskunn gjer eg ikkje. Og um dei ropar for mine øyro med sterkt mål, so vil eg ikkje høyra deim.»',
    },
    9: {
        1: 'Og han ropa med sterk røyst og sagde: «Kom hit med heimsøkjingar yver byen, kvar med si tynar-ambod i hand!»',
        2: 'Og sjå, seks menner på vegen gjenom Øvreporten, som snur mot nord, kvar med si krasar-ambod i handi, og ein av deim hadde ein linklædnad på og eit skrivestell ved lendi. Og dei kom inn og vart standande attmed koparaltaret.',
        3: 'Og herlegdomen åt Israels Gud lyfte seg upp frå keruben som han var yver, og flutte seg til dørstokken på huset. Og han ropa åt mannen i linklædnaden, som hadde skrivestellet ved lendi.',
        4: 'Og Herren sagde med han: «Gakk midt igjenom byen, midt igjenom Jerusalem, og set eit merke i panna på dei menner som sukkar og styn yver alle dei styggjor som vert gjorde der inne!»',
        5: 'Og han sagde med hine, so eg høyrde på: «Gakk igjenom byen etter honom og slå ned! Lat ikkje dykkar augo spara, og gjer ikkje miskunn!',
        6: 'Gamle og sveinar og møyar og småborn og kvinnor skal de drepa og tyna; men rør ikkje nokon av deim som hev merke på, og frå min heilagdom skal de taka til.» Og dei tok til med dei gamle menner som var framfor huset.',
        7: 'Og han sagde med deim: «Gjer huset ureint og fyll fyregarden med drepne menner! Far ut!» Og dei for ut og slo ned i byen.',
        8: 'Og då dei slo ned, og eg vart verande der, fall eg å gruve på mitt andlit og ropa og sagde: «Å, å! Herre, Herre! Vil du tyna alt som er leivt i Israel, når du renner ut din harm yver Jerusalem?»',
        9: 'Då sagde han med meg: «Misgjerningi åt Israels-lyden og Juda er stor, ovstor, og landet er fullt av blod, og byen er full av rengjing av retten. For dei segjer: «Herren hev vendt seg ifrå landet, og Herren ser det ikkje.»',
        10: 'So vil då ikkje heller eg lata mitt auga spara, og miskunn gjer eg ikkje; deira åtferd vil eg leggja på deira hovud.»',
        11: 'Og sjå, mannen i linklædnaden som hadde skrivestellet ved lendi, kom tilbake med svar og sagde: «Eg hev gjort som du baud meg.»',
    },
    10: {
        1: 'Og eg såg, og sjå, på den kvelven som var yver hovudi på kerubarne, var det som ein safirstein, sjåande til på skapnad som ein kongsstol. Ein kunde sjå honom yver deim.',
        2: 'Og han sagde med mannen i linklædnaden: «Gakk inn millom hjuli, inn under keruben, og tak nevarne dine fulle med gløder av deim som er millom kerubarne, og strå deim yver byen!» Og han gjekk medan eg såg på.',
        3: 'Og kerubarne stod på høgre sida åt huset då mannen gjekk inn, og skyi fyllte den indre fyregarden.',
        4: 'Og Herrens herlegdom lyfte seg frå keruben og burt til dørstokken i huset. Og skyi fyllte huset, og glansen av Herrens herlegdom fyllte fyregarden.',
        5: 'Og ljomen av kerubvengjerne høyrdest alt til den ytre fyregarden, som røysti åt Gud den allmegtige, når han talar.',
        6: 'Og det hende, då han baud mannen i linklædnaden og sagde: «Tak eld av den som er millom hjuli, millom kerubarne,» at han gjekk og stana attmed hjulet.',
        7: 'Og keruben rette ut handi si, millom kerubarne, burtåt elden som var millom kerubarne, og tok og lagde i nevarne på honom i linklædnaden. Og han tok imot og gjekk ut.',
        8: 'Og under vengjerne på kerubarne kunde ein sjå eitkvart på skap som ei mannshand.',
        9: 'Og eg såg, og sjå, det var fire hjul på kerubarne, eitt hjul hjå kvar kerub. Og hjuli var sjåande til som krysolit-stein.',
        10: 'Alle fire såg likeins ut, og det var nett som eitt hjul skulde vera inni hitt.',
        11: 'Når dei gjekk, gjekk dei til alle fire sidorne; dei snudde seg ikkje når dei gjekk, for til den staden som hovudet snudde, dit gjekk dei; dei snudde seg ikkje når dei gjekk.',
        12: 'Og heile deira likam og deira rygg og deira hender og deira vengjer og hjuli var fullsette med augo rundt ikring - dei fire hadde kvar sitt hjul.',
        13: 'Hjuli, dei vart kalla «kvervel» so eg høyrde på.',
        14: 'Og det var fire andlit på kvar; det fyrste hadde kerub-andlit, og det andre eit mannsandlit, og det tridje eit løve-andlit, og det fjorde eit ørne-andlit.',
        15: 'Og kerubarne lyfte seg; det var dei livendi som eg hadde set attmed elvi Kebar.',
        16: 'Og når kerubarne gjekk, so gjekk hjuli innmed deim, og når kerubarne lyfte vengjerne sine til å hevja seg upp frå jordi, skilde heller ikkje hjuli seg frå deim.',
        17: 'Når livendi stod, so stod dei, og når dei lyfte seg, so lyfte dei seg med deim, for åndi åt livendi var i deim.',
        18: 'Og Herrens herlegdom gjekk ut frå dørstokken på huset og stod yver kerubarne.',
        19: 'Og kerubarne lyfte vengjerne sine og steig upp frå jordi medan eg såg på, då dei gjekk ut, og hjuli innmed deim. Og dei stana attmed inngangen åt Øystreporten på Herrens hus. Og herlegdomen åt Israels Gud var uppe yver deim.',
        20: 'Det var dei same livendi som eg hadde set under Israels Gud burtmed elvi Kebar, og eg skyna at det var kerubar.',
        21: 'Og det var fire andlit på kvart eitt av dei fire, og fire vengjer på kvart eit, og eitkvart på skap som mannehender under vengjerne deira.',
        22: 'Og skapnaden på andliti deira det var dei andliti som eg hadde set attmed elvi Kebar; soleis såg dei ut, og dei var det. Og kvart eitt av deim gjekk beint fram.',
    },
    11: {
        1: 'Og åndi lyfte meg og flutte meg åt Øystreporten på Herrens hus, den som snur mot aust. Og sjå, frammed inngangen åt porten var det fem og tjuge mann. Og eg såg midt ibland deim Ja’azanja Azzursson og Pelatja Benajason, hovdingarne for folket.',
        2: 'Og han sagde til meg: «Menneskjeson! Det er desse menner som tenkjer upp urett og legg meinråder i denne byen.',
        3: 'Det er dei som segjer: Det ber ikkje snart til med husbyggjing; dette er gryta, og me er kjøtet.»',
        4: 'Difor, spå imot deim! spå, du menneskjeson!',
        5: 'Og Herrens ande fall på meg, og han sagde med meg: «Seg: So segjer Herren: Soleis hev de sagt, Israels-menner, og kva som leikar dykk i hugen, veit eg vel.',
        6: 'Mykje folk hev de drepe i denne byen, og de hev fyllt gatorne med drepne.',
        7: 'Difor, so segjer Herren, Herren: Dei de hev drepe og lagt ned der, dei er kjøtet, og byen er gryta, men dykk skal dei føra ut or honom.',
        8: 'Sverd ottast de, og sverd vil eg lata koma yver dykk, segjer Herren, Herren.',
        9: 'Og eg vil føra dykk ut derifrå og gjeva dykk i henderne på framande, og eg vil halda dom yver dykk.',
        10: 'For sverd skal de falla; burtmed Israels landskil vil eg døma dykk. Og de skal sanna at eg er Herren.',
        11: 'Han skal ikkje vera gryta åt dykk, og de skal ikkje vera kjøtet i den; burtmed Israels landskil vil eg døma dykk.',
        12: 'Og de skal sanna at eg er Herren, de som ikkje hev ferdast i mine bod og ikkje gjort etter mine lover; men etter loverne åt heidningfolki som bur rundt ikring dykk, hev de gjort.',
        13: 'Og det hende medan eg heldt på å spå, at Pelatja Benajason døydde. Då fall eg å gruve på mitt andlit og ropa med sterk røyst: «Å, å! Herre, Herre! Vil du tyna alt som er leivt i Israel?»',
        14: 'Og Herrens ord kom til meg; han sagde:',
        15: 'Menneskjeson! Dine brør, dine brør, dine frendar og all Israels-lyden, alle saman, til deim er det Jerusalems-buarne segjer: «Haldt dykk langt burte frå Herren! Me hev fenge landet til eiga.»',
        16: 'Difor, seg: So segjer Herren, Herren: Då eg førde deim langt burt imillom heidningarne og spreidde deim i landi, då vart eg eit lite bil ein heilagdom åt deim i dei landi der dei kom.',
        17: 'Difor, seg: So segjer Herren, Herren: Eg vil samla dykk frå folki og henta dykk utor landi som de er kringspreidde i, og eg vil gjeva dykk Israels land.',
        18: 'Ja, dit skal dei koma, og dei skal hava burt utor det all ufysna og all styggedomen.',
        19: 'Og eg vil gjeva deim eitt hjarta, og ei ny ånd vil eg gjeva inn i deim. Og eg vil taka burt steinhjarta or deira kjøt, og eg vil gjeva deim eit kjøthjarta,',
        20: 'so dei skal ferdast i mine bod og halda mine lover og gjera etter deim. So skal dei vera mitt folk, og eg skal vera deira Gud.',
        21: 'Men dei som let hjarta sitt ferdast etter hjarta åt dei ufyselege og styggjelege avgudarne sine, deira åtferd vil eg leggja på deira hovud, segjer Herren, Herren.»',
        22: 'Då lyfte kerubarne vengjerne sine, og hjuli fylgde med deim. Og herlegdomen åt Israels Gud var uppe yver deim.',
        23: 'Og Herrens herlegdom steig upp midt utor byen og stana yver fjellet som er austanfor byen.',
        24: 'Og åndi lyfte meg og førde meg til Kaldæa, til dei burtførde - i syni, ved Guds Ande, hende det. Og upp ifrå meg for syni som eg hadde set.',
        25: 'Og eg tala til dei burtførde alle dei Herrens ord som han hadde synt meg.',
    },
    12: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Midt ibland den tråssuge ætti bur du, millom slike som hev augo å sjå med, men ikkje ser, og øyro å høyra med, men ikkje høyrer; for ei tråssug ætt er dei.',
        3: 'Og du, menneskjeson! Bu deg til som du skal fara i utlægd, og far burt um dagen framfor augo på deim, og du skal fara frå der du bur til ein annan stad framfor augo på deim. Kann henda dei kunde koma til å sjå; for ei tråssug ætt er dei.',
        4: 'Og du skal føra ut bunaden din som ferdabunad høgstedags framfor deira augo, og sjølv skal du fara ut um kvelden framfor deira augo, sameleis som når dei fer i utlægd.',
        5: 'Brjot deg eit hol i veggen framfor deira augo, og før bunaden din ut gjenom det!',
        6: 'Framfor augo på deim skal du lyfta honom upp på herdi; når det er stumende myrkt, skal du føra honom ut, og du skal sveipa inn andlitet ditt, so du ikkje ser landet. For eg hev gjort deg til eit teikn for Israels-lyden.',
        7: 'Og eg gjorde so som han baud meg; eg budde meg som til å fara i utlægd ved høgste-dagsleite, og um kvelden braut eg meg ut gjenom veggen med handi. Og då det var stumende myrkt vorte, førde eg bunaden min ut; på herdi bar eg honom framfor deira augo.',
        8: 'Og Herrens ord kom til meg um morgonen; han sagde:',
        9: 'Menneskjeson! Hev ikkje Israels-lyden, den tråssuge ætti, sagt med deg: «Kva gjer du?»',
        10: 'Seg med deim: So segjer Herren, Herren: Denne beringi gjeld fyrsten i Jerusalem og all Israels-lyden som derinne er.',
        11: 'Seg: Eg er eit teikn åt dykk; likeins som eg hev gjort, so skal det gjerast med deim; dei skal verta fangar og fara i utlægd.',
        12: 'Og fyrsten som er hjå deim skal taka si byrd på herdi og fara ut med det er stumende myrkt. Dei skal brjota hol i muren og føra ut gjenom det. Sitt andlit skal han sveipa inn, so han ikkje skal sjå landet med sine augo.',
        13: 'Og eg vil breida ut garnet mitt yver honom, og han skal verta fanga i mitt veide-net. So vil eg føra honom til Babel, til Kaldæarlandet - men det skal han ikkje sjå - og der skal han døy.',
        14: 'Og alt som ikring honom er til hjelp og alle hans herflokkar vil eg spreida for alle vindar. Og sverd vil eg draga ut etter deim.',
        15: 'Og dei skal sanna at eg er Herren, når eg spreider deim millom folki og strår deim ut i landi.',
        16: 'Men nokre få av deim vil eg leiva etter sverd og svolt og sott, so dei kann fortelja um alle sine styggjor millom folki som dei kjem til, og dei skal sanna at eg er Herren.',
        17: 'Og Herrens ord kom til meg; han sagde:',
        18: 'Menneskjeson! Et brødet ditt bivrande, og drikk vatnet ditt skjelvande og med hugsott!',
        19: 'Og du skal segja til landslyden: So segjer Herren, Herren um deim som bur i Jerusalem, um Israels land: Brødet sitt skal dei eta med hugsott, og vatnet sitt skal dei drikka med fælske, for di deira land skal verta audt og snaudt, av di alle ibuarane for med valdsverk.',
        20: 'Og folkerike byar skal verta lagde i øyde, og landet skal verta ei øydemark, og de skal sanna at eg er Herren.',
        21: 'Og Herrens ord kom til meg; han sagde:',
        22: 'Menneskjeson! Kva er det for eit ordtøke de hev i Israels land, at de segjer: «Dagarne gjeng, og kvar ei syn vert upp i inkje?»',
        23: 'Seg difor med deim: So segjer Herren, Herren: Eg vil få burt dette ordtøket, og dei skal aldri meir taka det på si tunga i Israel, men seg med deim: Nær er dagarne komne og sannsegni i kvar ei syn.',
        24: 'For no heretter skal det ikkje finnast fåfengd syn og falsk spådom hjå Israels-lyden.',
        25: 'For eg, Herren, talar det ord eg talar, og det skal setjast i verk, det skal ikkje drygjast lenger ut. For i dykkar dagar, du tråssuge ætt, talar eg eit ord og set det i verk, segjer Herren, Herren.',
        26: 'Og Herrens ord kom til meg; han sagde:',
        27: 'Menneskjeson! Sjå, Israels-lyden segjer: «Syni han ser, gjeld dagar langt undan, og um ukomne tider spår han.»',
        28: 'Seg difor med deim: So segjer Herren, Herren: No heretter skal ikkje noko av mine ord drygjast ut lenger, det ord som eg talar, skal setjast i verk, segjer Herren, Herren.',
    },
    13: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Spå mot profetarne i Israel, som spår, og seg med deim som spår utav eige hjarta: Høyr Herrens ord!',
        3: 'So segjer Herren, Herren: Usæla yver profetarne, dei dårar, som gjeng etter si eiga ånd og etter det dei ikkje hev set!',
        4: 'Som revar i røysar er dine profetar, Israel.',
        5: 'De er ikkje stigne upp i murrivorne og hev ikkje mura upp verjemur kring Israels-lyden, so han kunde standa seg i striden på Herrens dag.',
        6: 'Deira syner var fåfengd og deira spådomar lygn, dei som segjer: So segjer Herren, endå Herren ikkje hev sendt deim. Like vel vonar dei å vera sannspådde.',
        7: 'Er det ikkje fåfengd syn de hev set, og ljugar-spåing de hev fare med, når de segjer: «So segjer Herren,» enda eg ikkje hadde tala?',
        8: 'Difor, so segjer Herren, Herren: Med di at de talar fåfengd og ser lygn, difor, sjå, so vil eg finna dykk, segjer Herren, Herren.',
        9: 'Og mi hand skal vera mot dei profetarne som ser fåfengd og fer med ljugar-spåing; i mitt folks råd skal dei ikkje vera, og i boki åt Israels-lyden skal dei ikkje verta skrivne, og til Israels land skal dei ikkje koma; og de skal sanna at eg er Herren, Herren,',
        10: 'for di, ja, for di de hev villa mitt folk og sagt: «Fred,» og der er ikkje fred - og når det byggjer ein murvegg, sjå, so stryk dei berre kalkrøra på.',
        11: 'Seg til kalk-strjukarane, at han vil ramla ned, det kjem eit skvalande støyteregn, og de, haglsteinar, skal falla, og ei stormflaga skal koma kastande.',
        12: 'Og sjå, når veggen er nedramla, vil det då ikkje verta sagt med dykk: «Kvar vart det av kalken som de strauk på?»',
        13: 'Difor, so segjer Herren, Herren: I min harm let eg ei stormflaga koma kastande, og i min vreide let eg eit skvalande støytregn koma, og i min harm haglsteinar til å øydeleggja alt i hop.',
        14: 'Og eg vil riva ned veggen som de strauk med kalk, og velta honom til jordi, og hans grunnvollar skal verta berrlagde. Når det då ramlar i røys, skal de verta tynte i fallet, og de skal sanna at eg er Herren.',
        15: 'Og eg vil tøma ut all mi vreide yver veggen, og yver deim som strauk honom med kalk. Då vil eg segja med dykk: Burte er både veggen og dei som strauk på honom,',
        16: 'profetarne i Israel som spådde um Jerusalem og såg fredssyner åt det, endå det ikkje var fred, segjer Herren, Herren.',
        17: 'Og du, menneskjeson! Vend di åsyn mot ditt folks døtter, som spår ut av sitt eige hjarta, og spå imot deim!',
        18: 'Og du skal segja: So segjer Herren, Herren: Usæla yver dei kvende som saumar bindsl åt alle handleder og lagar hovudsveip åt alle, både store og små, so dei kann fanga sjæler! De fangar sjæler for folket mitt, og andre sjæler held de i live, dykk til vinning.',
        19: 'Og de vanhelgar meg for mitt folk for nokre korn-nevar og brødmolar - til å drepa sjæler som ikkje skulde døy, og til å halda liv i sjæler som ikkje skulde liva, med di de lyg for lyden min som lyder på lygn.',
        20: 'Difor, so segjer Herren, Herren: Sjå, eg vil få tak i bindsli dykkar, som de fangar sjælerne med likeins som fuglar, og vil riva deim av armarne dykkar. Og eg vil fria sjælerne som de hev fanga, sjæler likeins som fuglar.',
        21: 'Og eg vil riva sund dykkar hovudsveip og berga mitt folk utor dykkar hender, so dei aldri meir skal vera veidefang i dykkar hender, og de skal sanna at eg er Herren.',
        22: 'For di de ved lygn fær rettferdig manns hjarta til å vanmodast, endå eg ikkje hev gjort honom vanmoda, og de hev gjort gudlaus manns hender sterke, for at han ikkje skulde venda um frå sin vonde veg so eg kunde få halda honom i live,',
        23: 'difor skal de ikkje hava fåfengde syner, og rune-kunster fær det ikkje fara med lenger; og eg vil berga mitt folk ut or dykkar hender, og de skal sanna at eg er Herren.',
    },
    14: {
        1: 'Og det kom til meg nokre av styresmennerne i Israel og sette seg for mi åsyn.',
        2: 'Og Herrens ord til meg; han sagde:',
        3: 'Menneskjeson! Desse mennerne hev teke dei ufysne avgudarne sine upp i sitt hjarta, og det som er støytestein og fører deim til misgjerning, hev dei sett framfor si åsyn: skulde eg lata deim spyrja meg?',
        4: 'Difor, tala til deim og seg med deim: So segjer Herren, Herren: Ein og kvar av Israels-lyden som tek dei ufysne avgudarne sine upp i sitt hjarta, og set framfor si åsyn det som er støytestein til misgjerning, og so kjem til profeten, honom vil eg, Herren, gjeva svar som høver honom med dei mange ufysne avgudarne hans,',
        5: 'so eg kann gripa Israels-lyden i deira hjarta, for di dei alle saman hev vendt seg frå meg med dei ufysne avgudarne sine.',
        6: 'Difor, seg med Israels-lyden: So segjer Herren, Herren: Vend um og vend dykk burt frå dei ufysne avgudarne dykkar, og vend dykkar åsyn burt frå alle styggjorne dykkar!',
        7: 'For kvar og ein av Israels-lyden - eller av framande som bur i Israel - som skil seg frå meg og tek dei ufysne avgudarne sine upp i sitt hjarta, og set framfor si åsyn det som er støytestein til misgjerning, og so kjem til profeten og ved honom vil spyrja meg, honom vil eg, Herren, sjølv svara;',
        8: 'og eg vil setja mi åsyn mot den mannen og tyna honom og gjera honom til eit teikn og eit ordtøke og rydja honom ut or mitt folk. Og de skal sanna at eg er Herren.',
        9: 'Og når profeten let seg lokka og talar eit ord, so hev eg, Herren, lokka den profeten, og eg vil retta ut handi mi mot honom og øyda honom ut or mitt folk Israel.',
        10: 'Og dei skal bera si misgjerning; likeins som med misgjerningi åt spyrjaren skal det vera med misgjerningi åt profeten,',
        11: 'so Israels-lyden ikkje meir skal villast burt frå meg og ikkje meir sulka seg med alle sine misgjerningar. Men dei skal vera mitt folk, og eg skal vera deira Gud, segjer Herren, Herren.',
        12: 'Og Herrens ord kom til meg; han sagde:',
        13: 'Menneskjeson! Når eit land syndar mot meg og fer med svik, og eg retter ut mi hand imot det og bryt sund brødstaven for det og sender svolt i det og ryd ut or det folk og fe,',
        14: 'og desse tri menner vøre der: Noah og Daniel og Job, då skulde dei med si rettferd berre berga si eigi sjæl, segjer Herren, Herren.',
        15: 'Og um eg let udyr fara gjenom landet og gjera det folketomt, so det vart likt ei øydemark, at ingen kunde ferdast der berre for udyri,',
        16: 'då skulde, so sant som eg liver, segjer Herren, Herren, desse tri mennerne, um dei vøre der, korkje berga søner eller døtter; dei åleine skulde verta berga, men landet verta ei øydemark.',
        17: 'Eller um eg let sverd koma yver det landet og sagde: «Sverd skal fara gjenom landet,» og eg rudde ut or det folk og fe,',
        18: 'og desse tri mennerne vøre der - so sant som eg liver, segjer Herren, Herren - dei skulde ikkje berga søner og døtter, berre dei åleine skulde verta berga.',
        19: 'Eller um eg sende sott i det landet og rende ut harmen min yver det med blod til å rydja ut or det folk og fe,',
        20: 'og Noah og Daniel og Job vøre der - so sant som eg liver, segjer Herren, Herren - dei skulde ikkje berga son eller dotter; dei skulde, ved si rettferd, berga berre si eigi sjæl.',
        21: 'For so segjer Herren, Herren: Enn når eg då sender dei fire øgjelege straffedomarne mine: sverd og svolt og udyr og sott yver Jerusalem til å rydja ut or det både folk og fe!',
        22: 'Men sjå, det vert leivt nokre undankomne, som vert burtførde, søner og døtter - sjå, dei skal fara til dykk, og de skal sjå deira åtferd og gjerningar; då skal de trøysta dykk etter ulukka som eg førde yver Jerusalem, alt som eg let koma yver det.',
        23: 'Og dei skal trøysta dykk, når de ser deira åtferd og gjerningar. Då skal de skyna at eg ikkje utan grunn hev gjort alt det eg hev gjort imot det, segjer Herren, Herren.',
    },
    15: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Kva fyremun hev vintreet framfor alle andre tre, den vintre-renningen som er millom trei i skogen?',
        3: 'Brukar ein det til noko slag gagnved? eller lagar ein av det ein nabb til å hengja noko slag bunad på?',
        4: 'Sjå, ein nører elden med det, og elden brenner båe endarne, og midluten vert sviden. Kann det då duga til noko yrke?',
        5: 'Sjå, medan det var heilt, var det ikkje brukande til noko yrke: kor mykje minder når elden hev brent på det, og det er svide! Skulde det då vera brukande til yrke?',
        6: 'Difor, so segjer Herren, Herren: Likeins som med veden av vintreet millom trei i skogen, som eg nører elden med, soleis gjer eg og med Jerusalems-buarne.',
        7: 'Og eg vil setja mi åsyn mot deim; utor elden gjekk dei, men elden skal endå øyda deim ut. Og de skal sanna at eg er Herren, når eg set mi åsyn mot deim.',
        8: 'Og eg vil gjera landet til ei øydemark, for di dei hev svike meg, segjer Herren, Herren.',
    },
    16: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Lat Jerusalem få vita um sin styggedom.',
        3: 'Og du skal segja: So segjer Herren, Herren til Jerusalem: Ditt upphav og di ætt er frå Kananitarlandet; far din var ein amorit og mor di ei hetitkvinna.',
        4: 'Då du kom til, den dagen du vart fødd, skar dei ikkje navlestrengen din, og ikkje vart du reintvegi med vatn og ikkje gnidi inn med salt og ikkje reiva med reivar.',
        5: 'Ikkje eit auga ynka deg, so dei gjorde noko av dette med deg av miskunn imot deg, men du vart kasta på berre marki, av di dei fekk stygg til deg den dagen du vart fødd.',
        6: 'Då gjekk eg framum deg og såg deg, der du låg og sprala i ditt blod. Og eg sagde med deg: «Du som ligg der i blodet ditt, liv!» Ja, eg sagde med deg: «Du som ligg der i blodet ditt, liv!»',
        7: 'Til mange tusund, som blomar i eng, gjer eg deg. Og du voks og vart stor og nådde den høgste vænleik. Brjosti vart faste, og håret ditt voks. Men du var berr og naki.',
        8: 'Då gjekk eg framum deg og såg deg, og sjå, di tid var komi, elskhugstidi. Og eg breidde eg kappa mi yver deg og løynde blygsli di. Og eg svor deg truskapseid og gjorde pakt med deg, segjer Herren, Herren, og du vart mi.',
        9: 'Og eg tvo deg i vatn og skylde blodet av deg, og salva deg med olje.',
        10: 'Og eg klædde deg i rosesauma ty og hadde på deg skor av markuskinn og batt på deg eit fint hovudlin og sveipte deg i silke.',
        11: 'Og eg prydde deg med prydnadsting, og gav deg armband på henderne og kjeda um halsen.',
        12: 'Og eg sette ein ring i nosi di og øyreringar i øyro dine og ei fager kruna på hovudet ditt.',
        13: 'Og du prydde deg med gull og sylv, og klædnaden din var fint linty og silke og rosesauma ty. Fint mjøl og honning og olje fekk du til mat. Du vart ovende fager, so du vart ei høveleg dronning.',
        14: 'Og du vart namngjeti millom folki for din vænleik, for han var fullkomen ved mi pryda som eg hadde butt deg til med, segjer Herren, Herren.',
        15: 'Men du leit på din vænleik og dreiv hor i kraft av di namnfrægd, og du auste ut din hordom yver kvar og ein som gjekk framum - han skal få det!',
        16: 'Og av klædi dine tok du og gjorde deg spreklute offerhaugar og dreiv hor på deim - slikt må ikkje koma på, ikkje henda.',
        17: 'Og du tok dine prydnadsting av gullet mitt og sylvet mitt som eg hadde gjeve deg, og gjorde deg mannsbilæte, og du dreiv hor med deim.',
        18: 'Og du tok dine rosesauma klæde og hadde på deim, og min olje og min røykjelse sette du fram åt deim.',
        19: 'Og brødet mitt som eg gav deg, finmjølet og oljen og honningen som eg hadde gjeve deg til mat, det sette du fram åt deim til godange; soleis gjekk det, segjer Herren, Herren.',
        20: 'Og du tok dine søner og døtter, som du hadde født åt meg, og ofra deim til mat åt deim. Var det då ikkje nok at du dreiv hor,',
        21: 'sidan du jamvel slagta borni mine og gav deim burt, med di du let deim ganga gjenom elden for deim?',
        22: 'Og i alle dine styggjor og din hordom kom du ikkje i hug dine ungdomsdagar, då du var berr og naki og låg og sprala i ditt blod.',
        23: 'So hende etter all din vondskap - usæl, usæl vere du! segjer Herren, Herren -',
        24: 'at du bygde deg ein kvelving og gjorde deg ein offerhaug på alle torg.',
        25: 'Attmed kvart eit vegemot bygde du din haug og skjemde din vænleik og breidde føterne ut for kvar og ein som gjekk framum, ja, du dreiv mykjen hordom.',
        26: 'Og du dreiv hor med Egyptarlands-sønerne, grannarne dine, som hev stort kjøt, og du dreiv mykjen hordom til å harma meg med.',
        27: 'Og sjå, eg rette ut mi hand og minka på det eg hadde etla åt deg, og eg let deim som hata deg fara åt med deg som dei vilde, filistardøtterne, som blygdest yver di skjemdaråtferd.',
        28: 'Og du dreiv hor med Assurs-sønerne, av di du ikkje hadde fenge ditt nøgje, og du dreiv hor med deim, men endå fekk du ikkje ditt nøgje.',
        29: 'Og du for verre fram med din hordom, alt til kræmarlandet Kaldæa, men endå fekk du ikkje ditt nøgje.',
        30: 'Å, kor hjarta ditt brann av gir! - segjer Herren, Herren - at du kunde gjera alt dette, og fara åt som den skamlausaste skjøkja',
        31: 'og byggja din kvelving attmed kvart eit vegemot og gjera dine haugar på kvart eit torg! Men du var ikkje som ei onnor skjøkja, med di du vanvyrde skjøkjeløn.',
        32: 'Du horkona! I staden for med mannen din held du deg med framande!',
        33: 'Alle skjøkjor gjev dei gåvor; men du gav alle dine elskarar gåvorne dine og kjøpte deim til å koma til deg frå alle leider og driva hor med deg.',
        34: 'Og du vart reint umsnudd imot andre kvende, i din ukjurskap; etter deg laup ingen, men du gav horeløn, du fekk ikkje, so rangsnudd var du.',
        35: 'Difor, du skjøkja, høyr Herrens ord!',
        36: 'So segjer Herren, Herren: For di du auste ut dine pengar og nækte di skam i din ulivnad med dine elskarar og med alle dine ufysne avgudar, og du spillte blod av dine born, som du gav deim,',
        37: 'difor, sjå, so samlar eg alle dine elskarar, som du tektest, og alle som du elska med alle som du hata, og eg vil samla deim imot deg frå alle leider og nækja di skam framfyre deim, og dei skal få sjå all di skam.',
        38: 'Og eg vil lata same domen ganga yver deg som yver horkonor og slike som spiller blod, og eg vil gjera deg til eit blodigt offer for brennande harm og åbry.',
        39: 'Og eg vil gjeva deg i deira hand, og dei skal riva ned din kvelving, og brjota ned dine haugar, og hava av deg klædi dine, og taka dine dyrverdige prydnadsting, og lata deg liggja der naki og berr.',
        40: 'Og dei skal gjera manngard um deg og steina deg i hel og hogga deg sund med sverdi sine.',
        41: 'Og dei skal brenna upp dine hus med eld og halda dom yver deg framfor augo på mange kvinnor. Og eg vil gjera ende på din hordom, og heller ikkje skjøkjeløn skal du heretter gjeva.',
        42: 'Og eg vil svala min heite harm på deg, og mitt åbry mot deg skal kverva. So vil eg halda meg i ro og ikkje lenger vera vreid.',
        43: 'Av di at du ikkje mintest ungdomsdagarne dine, men harma meg med alt dette, sjå, so vil eg og lata di åtferd koma på ditt hovud, segjer Herren, Herren; for hev du ikkje lagt skamløysa attåt alle styggjorne dine?',
        44: 'Sjå, alle som brukar ordtøke, skal hava dette til ordtak um deg: «Som mori, so dotteri.»',
        45: 'Du er dotter åt mor di, som stygdest ved mannen sin og borni sine, og du er syster åt systerne dine, som stygdest ved mennerne og borni sine: ei hetitkvinna er mor dykkar og ein amorit far dykkar.',
        46: 'Og den store syster di er Samaria, og hennar døtter, som bur på vinstre handi åt deg, og den litle syster di, som bur på høgre handi, er Sodoma og hennar døtter.',
        47: 'Fulla gjekk du ikkje på deira vegar og gjorde ikkje styggjor som dei; men berre eit lite bil - so for du verre åt enn dei på alle dine vegar.',
        48: 'So sant som eg liver, segjer Herren, Herren: Sodoma, syster di, ho og hennar døtter, hev ikkje gjort som du, og dine døtter.',
        49: 'Sjå, dette er misgjerningi åt Sodoma, syster di: ovmod; nøgdi med brød og sutlaus ro hadde ho og døtterne hennar; men handi åt armingen og fatigmannen styrkte ho ikkje.',
        50: 'Og med storlæte for dei, og dei gjorde skjemdarverk framfor mi åsyn; då rudde eg deim burt, fyrst eg såg det.',
        51: 'Og Samaria hev ikkje synda halvt so mykje som du, og du hev gjort dine styggjor fleire enn deira, so du gjorde systerne dine rettferdige med alle styggjor som du for med.',
        52: 'Ber då du og di skam, du som hev dømt dine syster orsakande; i dine synder hev du vore skamlausare enn dei, og soleis vart dei rettferdigare enn du. So skulde du blygjast, du og, og bera di skam, med di du gjer systerne dine rettferdige.',
        53: 'Men eg vil enda deira utlægd, utlægdi for Sodoma og hennar døtter og utlægdi for Samaria og hennar døtter og utlægdi for dine eigne utlæge midt imillom deim,',
        54: 'for at du skal bera di skam og skjemmast av alt det du hev gjort med di du trøystar deim.',
        55: 'Og systerne dine, Sodoma og hennar døtter, skal atter verta det dei fordom var, og Samaria og hennar døtter skal atter verta det dei fordom var, og du og dine døtterne skal atter verta det dei fordom var.',
        56: 'Var ikkje syster di, Sodoma, eit uord i munnen din i ovmods-dagarne dine,',
        57: 'fyrr vondskapen din vart synberr - liksom i den tidi då dei hædde deg, Arams-døtterne og alle der kringum, og filistardøtterne som svivyrde deg rundt ikring?',
        58: 'Di skjemd og dine styggjor skal du bera, segjer Herren.',
        59: 'For so segjer Herren, Herren: Eg vil fara åt med deg etter di eigi åtferd, du som vanvyrde eiden med di du braut pakti.',
        60: 'Men eg vil minnast mi pakt med deg i ungdomsdagarne dine, og eg vil gjera ei ævepakt med deg.',
        61: 'Og du skal minnast dine vegar og blygjast, når du tek imot systerne dine, dei som er større enn du, og dei som er mindre enn du, og eg gjev deg deim til døtter, endå at dei ikkje var med i di pakt.',
        62: 'Og eg vil gjera mi pakt med deg, og du skal sanna at eg er Herren,',
        63: 'for at du skal minnast og blygjast og ikkje lata upp munnen din berre for blygsl, når eg tilgjev deg alt det du hev gjort, segjer Herren, Herren.',
    },
    17: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Legg upp ei gåta og set fram ein liknad åt Israels-lyden.',
        3: 'Og du skal segja: So segjer Herren, Herren: Den store ørnen med dei store vengjerne, dei lange slagfjørerne, og fjørhamen fullsett med spriklute fjører, kom til Libanon og tok toppen av cedertreet.',
        4: 'Øvste kvisten braut han av og førde honom til eit kræmarland og sette honom ned i ein kjøpmannsby.',
        5: 'Sidan tok han ein renning der i landet og sette honom i dyrka jord; han tok og sette honom som ein seljetein der det var nøgdi med vatn.',
        6: 'Og han voks og vart til eit vintre, vidt og lågvakse, so hans rankar skulde venda seg til ørnen og røterne hans skulde vera under honom. Han vart soleis til eit vintre som fekk greiner og skaut renningar.',
        7: 'So var det ein annan stor ørn med store vengjer og yven fjørham. Og sjå, dette vintreet krøkte røterne sine burtåt honom, og frå den sengi der det var planta, tøygde det rankorne sine mot honom for at han skulde vatna det,',
        8: 'endå at det var planta i god jord og attmed mykje vatn, so det kunde skjota greiner og bera frukt og verta eit gildt vintre.',
        9: 'Seg: So segjer Herren, Herren: Skal det trivast? Vil ikkje hin ørnen slita upp røterne og riva frukti av det so det tornar? Kvart eit sprettande blad skal torna, so ein tarv ikkje stor magt og mykje folk til å riva det upp mot rotom.',
        10: 'Sjå, det er planta; skal det trivast? Vil det ikkje torna, verta knas-turt, når austanvinden kjem burti det? I sengi der det veks, skal det torna.',
        11: 'Og Herrens ord kom til meg; han sagde:',
        12: 'Seg til den tråssuge lyden: Skynar de ikkje kva dette er? Seg: Sjå, Babel-kongen kom til Jerusalem, og han tok kongen og hovdingarne og førde deim med seg til Babel.',
        13: 'Og han tok ein utav kongsætti og gjorde pakt med honom og let honom gjera eiden, og dei megtige i landet tok han burt,',
        14: 'for at det skulde vera eit litevore kongerike og ikkje hevja seg upp, so det skulde halda pakti med honom og standa seg.',
        15: 'Men han sette seg upp imot honom, med di han let sine sendemenner fara til Egyptarland, for at dei skulde gjeva honom hestar og mykje folk. Skal det ganga honom vel? Skal han sleppa undan, den som gjer slikt? Skal han få brjota pakt og sleppa frå det?',
        16: 'So sant som eg liver, segjer Herren, Herren, sanneleg, på den staden der han er, den kongen som gjorde honom til konge - eiden hans svivyrde han, og pakti med honom braut han - hjå honom, midt i Babel, skal han døy.',
        17: 'Og Farao skal ikkje hjelpa honom i striden med stor her og mykje folk, når dei kastar upp ein voll og byggjer åtaksmurar til å tyna mange liv.',
        18: 'Han svivyrde eiden då han braut pakti, og sjå, han hadde gjeve handtak på det, og alt dette hev han gjort; sleppa undan skal han ikkje.',
        19: 'Difor, so segjer Herren, Herren: So sant som eg liver, sanneleg, eiden min som han svivyrde, og pakti mi som han braut, vil eg leggja på hans hovud.',
        20: 'Og eg vil breida ut garnet mitt yver honom, og han skal verta fanga i mitt net. Og eg vil føra honom til Babel og ganga til doms med honom der for sviket han sette upp imot meg.',
        21: 'Og alle som vil røma undan ut or alle hans fylkingar, for sverd skal dei falla, og dei som vert leivde, skal verta spreidde for alle vindar, og de skal sanna at eg, Herren, hev tala.',
        22: 'So segjer Herren, Herren: Då vil eg taka av toppen på det høge cedertreet og setja; av dei øvste kvisterne vil eg brjota ein grann teinung, og eg vil planta honom på eit høgt og rise fjell.',
        23: 'På Israels høge fjell vil eg planta honom, og han skal få greiner og bera frukt og verta eit gildt cedertre. Og alle fuglar, alt fljugande, skal bu under det, i skuggen av greinerne på det skal dei bu.',
        24: 'Og alle trei på marki skal skyna at eg, Herren, hev gjort eit høgt tre lågt og eit lågt tre høgt, hev late eit grønt tre torna og eit turt tre grønka. Eg, Herren, hev tala, og eg set det i verk.',
    },
    18: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Korleis kann de bruka dette ordtøket i Israels land og segja: «Federne åt sure druvor, og borni vart sårtennte.»',
        3: 'So sant som eg liver, segjer Herren, Herren, de skal ikkje få bruka dette ordtøket meir i Israel.',
        4: 'Sjå, alle sjælerne er mine, både sjæli åt faren og sjæli åt sonen; mine er dei; den sjæl som syndar, ho skal døy.',
        5: 'Og når ein mann er rettferdig og gjer rett og rettferd:',
        6: 'ikkje et offermat på fjelli og ikkje kaster augo sine på dei ufysne avgudarne åt Israels-lyden og ikkje skjemmer kona åt grannen sin og ikkje kjem nær ei kvinna medan ho er urein,',
        7: 'og ikkje er hard imot nokon, let skuldmannen få pantet sitt att, ikkje fer med ransverk, gjev den hungrige sitt brød og klæder den nakne,',
        8: 'ikkje låner ut for renta og ikkje tek yvermål, held si hand burte frå det som rangt er, dømer rett dom mann og mann imillom,',
        9: 'ferdast i mine bod og held mine lover, so han gjer det som rett er - han er rettferdig, liva skal han, segjer Herren, Herren.',
        10: 'Men han fær kann henda ein son som tek til med valdsverk, renner ut blod eller gjer eitkvart sovore',
        11: '- endå han ikkje gjorde noko slikt - for han et ogso offermat på fjelli, skjemmer kona åt grannen sin,',
        12: 'er hard imot armingen og fatigmannen, fer med ransverk, gjev ikkje pant tilbake, kaster augo sine på dei ufysne avgudar, fer med styggedom,',
        13: 'låner ut for rente og tek yvermål - og so skulde han liva! Han skal ikkje liva. Alle desse styggjor gjorde han; banen hans skal det verta, blodet hans skal koma yver honom.',
        14: 'Men sjå, so fær han ein son, og han ser alle synderne åt far sin som han gjorde, han ottast og gjer ikkje etter deim;',
        15: 'han et ikkje offermat på fjelli og kastar ikkje augo sine dei ufysne avgudarne åt Israels-lyden, skjemmer ikkje kona åt grannen sin',
        16: 'og er ikkje hard mot nokon, tek ikkje pant og fer ikkje med ransverk, gjev den hungrige sitt brød og klæder den nakne,',
        17: 'held handi si tilbake frå armingen, tek ikkje renta og yvermål, gjer etter mine lover og ferdast i mine bod. Han skal ikkje døy for misgjerningi åt far sin, liva skal han.',
        18: 'Far hans som for med valdsverk og rana frå bror og gjorde det som ikkje er godt midt i lyden sin, sjå han laut døy for si misgjerning.',
        19: 'Men de segjer: «Kvi skal ikkje sonen bera syndeskuldi åt far sin?» Sonen hev då gjort rett og rettferd alle mine bod hev han halde og gjort etter deim; liva skal han.',
        20: 'Den sjæli som syndar, ho skal døy. Son skal ikkje bera syndeskuldi åt far sin, og far skal ikkje bera syndeskuldi åt son sin. Yver den rettferdige skal hans rettferd vera, og yver den gudlause skal hans gudløysa vera.',
        21: 'Men når den ugudlege vender um frå alle sine synder som han hev gjort, og held alle mine bod og gjer rett og rettferd, då skal han liva og ikkje døy.',
        22: 'Alle hans misgjerningar som han hev gjort, skal vera gløymde; ved si rettferd som han gjorde, skal han liva.',
        23: 'Skulde eg hava hugnad i det, at den ugudlege døyr? segjer Herren, Herren. Måtte ikkje det fegna meg, at han vendar um frå sin veg og liver?',
        24: 'Men når ein rettferdig vender um frå si rettferd og gjer urett, alle slike styggjor som den ugudlege gjer, skulde han gjera det og liva? All hans rettferd som han gjorde, skal verta gløymd. For den truløysa han for med, for det skal han døy.',
        25: 'Og de segjer: «Herrens åtferd er ikkje rett.» Høyr då, du Israels-lyd! Er ikkje mi åtferd rett? Er det ikkje dykkar åtferd som ikkje er rett?',
        26: 'Når ein rettferdig vender um frå si rettferd og gjer urett, so skal han difor døy; for sin urett som han gjorde, skal han døy.',
        27: 'Og når ein ugudleg vender um frå si gudløysa, som han hev gjort, og gjer rett og rettferd, so skal han halda si sjæl i live.',
        28: 'For han såg alle sine misgjerningar som han hadde gjort, og vende um frå deim; liva skal han, han skal ikkje døy.',
        29: 'Men Israels-lyden segjer: «Herrens åtferd er ikkje rett.» Er ikkje mi åtferd rett, du Israels lyd? Er det ikkje dykkar åtferd som ikkje er rett?',
        30: 'Difor vil eg døma dykk, du Israels lyd, ein og kvar etter hans åtferd, segjer Herren, Herren. Vend um og vend dykk burt frå alle dykkar misgjerningar, so ikkje skuld skal føra dykk til fall!',
        31: 'Kasta frå dykk alle dykkar misgjerningar som de hev misfare dykk med, og få dykk eit nytt hjarta og ei ny ånd! For kvi vil de døy, du Israels lyd?',
        32: 'For eg hev ikkje hugnad i dauden åt den som døyr, segjer Herren, Herren. So vend då um, so skal de liva!',
    },
    19: {
        1: 'Og du, set i med ein syrgjesong um Israels fyrstar',
        2: 'og seg: «Kvar er mor di? Ei løvemor. Millom løvor ho låg, i ungløve-lag sine ungar ho ol.',
        3: 'Og ho tamde upp ungen den eine, han vart ungløva, han, og han lærde å riva til seg ran; menner han åt.',
        4: 'Og folkeslag høyrde um honom; han vart fanga i deira grav, og med naseringar på vart han førd til Egypt.',
        5: 'Og ho såg det - for ho stunda -: Hennar von var spilt. So tok ho ein til av sine ungar, honom sette ho til løva å vera.',
        6: 'Og han sveiv ikring millom løvor, ei ungløva sjølv. Og han lærde å røva til seg ran; menner åt han.',
        7: 'Og han skjemde enkjorne deira, og han lagde deira byar øyde. Og landet med alt som var i det tok fæla av buringi hans.',
        8: 'Då gjekk dei imot honom, folki frå fylki rundt ikring, og breidde sitt garn yver honom. Han vart fanga i deira grav.',
        9: 'Og dei sette honom i bur, med naseringar på, og førde honom til kongen i Babel. So sette dei honom i tjukkmura borger, for at ein aldri meir skulde høyra hans røyst burtpå Israelsfjelli.',
        10: 'Medan du fekk vera i ro, var di mor som eit vintre, planta attmed vatn, rikt på frukt og på greiner av alt det vatnet det hadde.',
        11: 'Og det fekk sterke greiner til hovdingestavar, og høgt voks det upp millom skyer, og det var audsynt for si høgd og for rankorne mange.',
        12: 'Då vart det rive upp i harm og kasta på jordi, og austanvinden forturka frukti. Greinerne dei sterke vart rivne av og torna, elden øydde deim ut.',
        13: 'Og no er det planta i audni, i eit land so turt og tyrst.',
        14: 'Og eld gjekk ut frå den kvistute grein, han øydde frukti. Og det hev ikkje meir nokor sterk grein til hovdingstav.» - Ein syrgjesong er det, og til ein syrgjesong vart det.',
    },
    20: {
        1: 'Og det hende i det sjuande året, den tiande dagen i den femte månaden, at det kom nokre av Israels styresmenner og vilde spyrja Herren. Og dei sette seg framfor mi åsyn.',
        2: 'Og Herrens ord kom til meg; han sagde:',
        3: 'Menneskjeson! Tala til Israels styresmenner og seg med deim: So segjer Herren, Herren: Er det komne og vil spyrja meg? So sant som eg liver, so let eg ikkje dykk få spyrja meg, segjer Herren, Herren.',
        4: 'Vil du døma deim, vil du døma, menneskjeson? Lat deim få vita styggedomen åt sine feder!',
        5: 'Og du skal segja med deim: So segjer Herren, Herren: Den dagen eg valde ut Israel, og rette handi mi i veret for avkjømet i Jakobs hus og let deim verta kjende med meg i Egyptarlandet, då eg rette upp handi mi for deim og sagde: «Eg er Herren, dykkar Gud» -',
        6: 'den dagen rette eg upp handi på det, at eg vilde føra deim ut or Egyptarlandet og til eit land som eg hadde set ut åt deim, som fløymer med mjølk og honning; det er det fagraste av alle land.',
        7: 'Og eg sagde med deim: «Kvar og ein av dykk kaste burt dei styggetingi han hev framfor augo, og gjer dykk ikkje ureine med Egyptarlands ufysne avgudar! Eg er Herren, dykkar Gud.»',
        8: 'Men dei var tråssuge mot meg og vilde ikkje høyra på meg; styggetingi dei hadde framfor augo, kasta dei ikkje burt, og Egyptarlands ufysne avgudar vende dei seg ikkje ifrå. Då sagde eg at eg vilde renna ut yver deim min harm og tøma ut min vreide på deim midt i Egyptarlandet.',
        9: 'Og eg gjorde det for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som dei budde ibland, og som såg på at eg let deim verta kjende med meg og vilde føra deim ut or Egyptarland.',
        10: 'Og eg førde deim ut or Egyptarland og let deim koma inn i øydemarki.',
        11: 'Og eg gav deim bodi mine og kunngjorde deim mine lover, som menneskja skal helda og so liva ved deim.',
        12: 'Og eg gav deim og kviledagarne mine, so dei skulde vera til eit teikn millom meg og deim, so dei skulde vita at eg er Herren som helgar deim.',
        13: 'Men Israels-lyden var tråssug imot meg i øydemarki; i mine bod ferdast dei ikkje, og dei svivyrde loverne mine, som menneskja skal halda og so liva ved deim, og kviledagarne mine vanhelga dei ovleg. Då sagde eg at eg vilde renna utyver deim min harm og tyna deim i øydemarki.',
        14: 'Men det vilde eg gjera for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som såg på at eg førde deim ut.',
        15: 'So rette eg og upp handi i øydemarki på det, at eg ikkje vilde lata deim koma inn i det landet som eg hadde gjeve, som fløymer med mjølk og honning, det som er det fagraste av alle land,',
        16: 'for di dei svivyrde loverne mine og ikkje ferdast i bodi mine og vanhelga kviledagarne mine. For etter deira ufysne avgudar for deira hjarto.',
        17: 'Men mitt auga sparde deim, so eg ikkje tynte deim, og eg gjorde ikkje reint ende på deim i øydemarki.',
        18: 'Og eg sagde til borni deira i øydemarki: «I bodi åt federne dykkar må de ikkje ferdast, og loverne deira må det ikkje halda, og med deira ufysne avgudar må de ikkje gjera dykk ureine.',
        19: 'Eg er Herren, dykkar Gud; i bodi mine skal det ferdast, og loverne mine skal det halda, og etter deim skal det gjera.',
        20: 'Og kviledagarne mine skal de helga, og dei skal vera eit teikn millom meg og dykk, so de skal vita at eg, Herren, er dykkar Gud.»',
        21: 'Men dei var tråssuge mot meg, borni; i bodi mine ferdast dei ikkje, og loverne mine heldt dei ikkje, so dei gjorde etter deim, dei som menneskja skal gjera etter og so liva ved deim; kviledagerne mine vanhelga dei. Då sagde eg at eg vilde renna utyver deim min harm og tøma ut min vreide på deim i øydemarki.',
        22: 'Men eg tok handi mi tilbake og gjorde det for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som hadde set på at eg førde deim ut.',
        23: 'So rette eg og upp handi i øydemarki på det, at eg vilde spreida deim millom heidningfolki og strå deim i landi,',
        24: 'for di dei ikkje heldt loverne mine, men svivyrde bodi mine og vanhelga kviledagarne mine, og deira augo for etter dei ufysne avgudarne åt federne deira.',
        25: 'So gav eg deim og bod som ikkje var gode, og lover som dei ikkje kunde liva ved.',
        26: 'Og eg let deim verta ureine med offergåvorne sine, med di dei let ganga gjenom elden alt som opnar morsliv, so eg kunde tyna deim, for at dei skulde skyna at eg er Herren.',
        27: 'Difor, tala til Israels-lyden, du menneskjeson! og du skal segja med deim: So segjer Herren, Herren: Med det og hædde dykkar feder meg, at dei for med svik imot meg.',
        28: 'For eg førde deim inn i landet som eg med upprett hand hadde lova deim; men fyrst dei såg ein høg haug eller eit lauva tre, so ofra dei der sine slagtoffer, og der bar dei fram gåvor til å harmast av, og dit kom dei med godangen sin, og der rende dei ut sine drykkoffer.',
        29: 'Då sagde eg med deim: «Kva er det med haugen, sidan de kjem dit?» Og han fekk namnet «haug» alt til denne dag.',
        30: 'Difor, seg med Israels-lyden: so segjer Herren, Herren: Vil de sulka dykk likeins som federne dykkar og i hordom renna etter deira styggedom?',
        31: 'Ved gåvorne det kjem med og ved borni dykkar, som det let ganga gjenom elden, sulkar de dykk med alle dykkar ufysne avgudar alt til denne dag - og so skulde eg lata dykk spyrja meg, du Israels-lyd! So visst som eg liver, segjer Herren, Herren, dykk let eg ikkje spyrja meg.',
        32: 'Og det som leikar dykk i hugen, skal ikkje henda - når de segjer: «Me vil vera som heidningfolki, som hitt folket i landi; me vil tena tre og stein.»',
        33: 'So sant som eg liver, segjer Herren, Herren: med sterk hand og med strak arm og med utrend harm vil eg rikja yver dykk.',
        34: 'Og eg vil føra dykk ut frå folki og samla dykk ut or landi, der som de var spreidde, med sterk hand og med strak arm og med utrend harm.',
        35: 'Og eg vil føra dykk til folkeheidi, og der vil eg ganga til doms med dykk, andlit til andlit.',
        36: 'Likeins som eg gjekk til doms med federne dykkar i øydemarki attmed Egyptarlandet, so vil eg ganga til doms med dykk, segjer Herren, Herren.',
        37: 'Og eg vil lata dykk ganga framum under hyrdingstaven, og eg vil leida dykk inn i pakt-bandet.',
        38: 'Og eg vil skilja ut ifrå dykk deim som sette seg upp imot meg og fall frå meg. Ut or landi der dei bur i utlægd, vil eg føra deim, men inn i Israels land skal dei ikkje koma. Og de skal sanna at eg er Herren.',
        39: 'Og du, Israels-lyd! So segjer Herren, Herren: Berre gakk, kvar ein av dykk, og ten dykkar ufysne avgudar! Men sidan skal de, sant og visst, høyra på meg og aldri meir vanhelga mitt heilage namn med gåvorne dykkar og med dei ufysne avgudarne dykkar.',
        40: 'For på mitt heilage fjell, på Israels høge fjell, segjer Herren, Herren, der skal de tena meg, all Israels lyd, alle som i landet er. Der vil eg hava hugnad i deim, og der vil eg spyrja etter offergåvorne dykkar og etter fyrstegrøda som de kjem med av alt det de helgar.',
        41: 'For den gode angen skuld vil eg hava hugnad i dykk, når eg fører dykk ut frå folki og samlar dykk ut or landi der som de var spreidde, og helgar dykk framfor augo på folkeslagi.',
        42: 'Og de skal sanna at eg er Herren, når eg fører dykk til Israels land, det landet som eg med upprett hand hadde lova federne dykkar.',
        43: 'Der skal de minnast dykkar vegar og alle dei gjerningar som de hev sulka dykk med, og de skal styggjast ved dykk sjølve for alt det vonde som de hev gjort.',
        44: 'Og de skal sanna at eg er Herren, når eg fer so åt med dykk for mitt namn skuld, ikkje etter dykkar vonde vegar og dykkar illgjerningar, du Israels-lyd, segjer Herren, Herren.',
        45: 'Herrens ord kom til meg; han sagde:',
        46: 'Menneskjeson! Snu di åsyn mot sud og preika mot sud og spå imot skogen på marki i sud!',
        47: 'Og du skal segja til skogen i sud: Høyr Herrens ord! so segjer Herren, Herren: Sjå, eg set eld på deg, og han skal svida av kvart eit grønt tre og kvart eit turt tre i deg. Den logande elden skal ikkje slokna, men han skal skambrenna kvart eit andlit frå sud til nord.',
        48: 'Og alt kjøt skal sjå at eg, Herren, hev kveikt honom; slokna skal han ikkje.',
        49: 'Då sagde eg: «Å, Herre, Herre! Dei segjer um meg: «Er det ikkje berre i likningar han talar?»»',
    },
    21: {
        1: 'Då kom Herrens ord til meg; han sagde:',
        2: 'Menneskjeson! Snu di åsyn mot Jerusalem og preika mot heilagdomarne og spå mot Israelslandet!',
        3: 'Og du skal segja til Israelslandet: So segjer Herren: Sjå, eg skal finna deg og draga sverdet utor slira og rydja ut or deg rettferdige og ugudleg.',
        4: 'Sidan eg vil rydja ut or deg rettferdig og ugudleg, so skal sverdet mitt fara utor slira mot alt kjøt frå sud til nord.',
        5: 'Og alt kjøt skal sanna at eg, Herren, hev drege sverdet mitt or slira, det vert innatt-stunge.',
        6: 'Og du, menneskjeson, sukka! Du skal sukka framfor augo deira so det knakar i dine lender - i såran sut.',
        7: 'Og når dei då segjer med deg: «Kvifor sukkar du?» då skal du segja: «For ei fretnad; for han kjem. Då vil kvart eit hjarta bråna og alle hender siga, og kvar ei ånd dovna og alle kne verta som vatn. Sjå, det kjem, og det hender, segjer Herren, Herren.»',
        8: 'Og Herrens ord kom til meg; han sagde:',
        9: 'Menneskjeson! Spå og seg: So segjer Herren: Seg: Eit sverd, eit sverd, kvest, ja, blenkt og.',
        10: 'Til å halda slagting med er det kvest, og til å blikta som eldingen er det blenkt. Eller skulde me fegnast, du min sons ætt, som vanvyrder alt tre?',
        11: 'Og han let det blenkjast til eit handyvle; dette sverdet er kvest og blenkt, med det er etla åt dråpsmanns hand.',
        12: 'Ropa og barma deg, menneskjeson! For det er åt mitt folk, det er åt alle fyrstar i Israel; etla åt sverdet er dei med mitt folk. Difor, slå deg på lendi!',
        13: 'For prøva er komi, og kven skulde ho råka, um ikkje den ætti som vanvyrder tukt? segjer Herren, Herren.',
        14: 'Og du, menneskjeson! Spå og slå i hop henderne! Tvifelt, ja trifelt kjem sverdet: sverdet til å stinga menner, sverd til å stinga den store, det møter deim alle stader.',
        15: 'Til eit bliktande sverd sette eg det imot alle portarne deira, so hjarto skal bråna og støytesteinarne verta mange. Å, det er gjort til å ljona, kvest til å slagta med.',
        16: 'Tak deg på tak, sverd, hogg til høgre! Snu deg, hogg til vinstre! Kvar so eggi di snur!',
        17: 'Då skal eg og slå i hop henderne mine og svala min harm. Eg, Herren, hev tala.',
        18: 'Og Herrens ord kom til meg; han sagde:',
        19: 'Og du, menneskjeson! Gjer deg tvo vegar som sverdet åt Babel-kongen kann fara fram på! Frå eitt land skal dei ganga ut båe. Laga so til ein vegvisar, laga honom til der vegarne tek av til kvar ein by!',
        20: 'Du skal gjera ein veg som sverdet kann fara fram på til Rabba åt Ammons-sønerne, og ein til Juda, inn i Jerusalem, borgbyen.',
        21: 'For Babel-kongen stend attmed vegemotet, der som båe vegarne tek til, og driv på med spaning; han rister pilerne, spør husgudarne, skodar på livri.',
        22: 'I høgre handi fær han luten «Jerusalem», at han skal setja upp murstangarar, lata upp munnen med tynar-rop, lata herrop ljoma, setja upp murstangarar mot portarne, kasta upp umlægringsvoll, byggja åtaksmurar.',
        23: 'Men dei tykkjer det er berre fåfengd spådom; dei hev då lovnadseidar i mengd. Men han minner um misgjerning, so dei skal verta tekne.',
        24: 'Difor, so segjer Herren, Herren: Etter di de hev drege dykkar misgjerning fram or gløymsla, med di dykkar brot vert openberra, so dykkar syndar vert synberre i alle dykkar verk - etter di de kjem fram or gløymsla, skal de verta tekne med handi.',
        25: 'Og du vanheilage gudløysing, Israels fyrste, din dag er komen når misgjerningi ein gong lyt enda.',
        26: 'So segjer Herren, Herren: Tak huva av, lyft kruna ned! Det som er, skal ikkje vera; det låge skal upp, det høge skal ned.',
        27: 'I koll, i koll, i koll vil eg støyta det; det skal ikkje vera gjort med det heller - til dess han kjem som retten hev, han som eg vil gjeva det.',
        28: 'Og, du menneskjeson, spå og seg: So segjer Herren, Herren um Ammons-sønerne og um deira svivyrding: Og du skal segja: Eit sverd, eit sverd er drege, blenkt til å slagta med, til å tyna, til å ljona,',
        29: 'medan dei ser fåfengde syner og spår deg lygn, so du kann verta lagd attmed halsarne åt daudedømde gudløysingar som dagen er komen åt, når misgjerningi ein gong lyt enda.',
        30: 'Stikk i slira ditt sverd! På den staden der du er skapt, i det landet du er ætta ifrå, vil eg døma deg.',
        31: 'Eg vil renna utyver deg min harm, min vreideloge vil eg blåsa imot deg og gjeva deg i henderne på villmenner, meistrar i tynarverk.',
        32: 'Elden skal øyda deg, ditt blod skal verta utrent midt i landet, ingen skal koma deg i meir hug; for eg, Herren, hev tala.',
    },
    22: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Og du, menneskjeson! Vil du døma, vil du døma blodbyen? So lat honom få vita um all sin styggedom!',
        3: 'Og du skal segja: So segjer Herren, Herren: Å, for ein by! som renner ut blod midt inni seg, so tidi hans må koma, og som gjer seg ufysne avgudar til å sulka seg med!',
        4: 'Med blodet som du hev rent ut, hev du ført skuld yver deg, og med dei ufysne avgudarne dine som du gjorde, hev du sulka deg, og du hev fenge dagarne dine til å nærma seg, og åri hev du nått. Difor gjer eg deg til spe åt folki og til spott for alle land.',
        5: 'Dei som er nær og dei som er langt ifrå deg, skal hæda deg, du med ditt utskjemde namn og di vimande villa.',
        6: 'Sjå, Israels fyrstar hjå deg leit kvar på sin arm - til å renna ut blod.',
        7: 'Far og mor vanvyrde dei hjå deg, mot den framande for dei fram med vald hjå deg, den farlause og enkja var dei harde med hjå deg.',
        8: 'Heilagdomarne mine svivyrde du, og kviledagarne mine vanhelga du.',
        9: 'Baktalarar var det hjå deg til å renna ut blod, på fjelli åt dei offermat hjå deg, skjemdarverk for dei med hjå deg.',
        10: 'Hjå deg nækte dei fars blygsl, hjå deg skjemde dei kvende som var ureine i sine månadstider.',
        11: 'Ein for med skjæmdarverk med grannekona si, ein annan skjemde ut sonekona si i skamlaus ulivnad, og endå ein annan skjemde syster si, dotter åt far sin, hjå deg.',
        12: 'Mutor tok dei hjå deg for å renna ut blod. Renta og yvermål tok du, og mot grannen din gjorde du uskil med vald, og meg gløymde du, segjer Herren, Herren.',
        13: 'Og sjå, eg hev slege henderne mine i hop yver syndepengarne du hev samla, og yver blodspillet som var hjå deg.',
        14: 'Kann hjarta ditt standa seg eller henderne dine vera fullsterke i dei dagarne då du fær med meg å gjera? Eg, Herren, hev tala og vil setja det i verk.',
        15: 'Og eg vil spreida deg millom folki og strå deg i landi, og eg skal få ureinska di av deg.',
        16: 'Og du skal varta vanhelga ved deg sjølv framfor augo på folki. Då skal du sanna at eg er Herren.',
        17: 'Og Herrens ord kom til meg; han sagde:',
        18: 'Menneskjeson! Israels-lyden vart berre til slagg for meg; alle i hop er dei kopar og tin og jarn og bly inni ein omn, dei er sylvslagg vortne.',
        19: 'Difor, so segjer Herren, Herren: Etter di de er vortne til slagg alle saman, sjå, so vil eg samla dykk i hop midt i Jerusalem.',
        20: 'Likeins som ein samlar i hop sylv og kopar og jarn og bly og tin midt i ein omn og blæs upp eld på det og smelter det, soleis vil eg samla dykk i hop - i min vreide og harm - og eg vil hava dykk nedi og smelta dykk.',
        21: 'Ja, eg vil sanka dykk saman og blåsa min vreide-eld på dykk, og der skal de smelta.',
        22: 'Likeins som sylv smelter i ein omn, soleis skal de smelta der. Og de skal sanna at eg, Herren, hev rent ut min harm yver dykk.',
        23: 'Og Herrens ord kom til meg; han sagde:',
        24: 'Menneskjeson! seg til det: Du er eit land som ikkje er reinsa, som ikkje hev fenge regn på ein vreide-dag.',
        25: 'Eit samansvore lag er deira profetar der, dei er som ei burande løva, ranande ran; sjæler et dei upp, eignaluter og dyrverdige ting tek dei, mange gjer dei der til enkjor.',
        26: 'Prestane deira gjer vald på mi lov og vanhelgar heilagdomarne mine. Heilagt frå vanheilagt skil dei ikkje, millom ureint og reint lærer dei ikkje nokon å skilja, og for kviledagarne mine let dei att sine augo, og eg vert vanhelga midt ibland deim.',
        27: 'Fyrstarne deira er som vargar, ranande ran - med å renna ut blod, med å tyna sjæler, so dei kann auka syndepengarne sine.',
        28: 'Profetarne stryk på kalk åt deim, med di dei skodar fåfengd og spår lygn åt deim; dei segjer: «So segjer Herren, Herren,» endå Herren ikkje hev tala.',
        29: 'Landslyden fer med valdsverk, med flåing og ran, og med arming og fatigmann er dei harde, og mot den framande gjer dei vald og urett.',
        30: 'Og eg leita etter ein mann millom deim som vilde mura mur og standa i gapet framfor mi åsyn til vern for landet, so eg ikkje skulde leggja det i øyde, men eg fann ingen.',
        31: 'So vil eg då renna ut min vreide, i min brennande harm gjer eg ende på deim. Åtferdi deira legg eg på deira eige hovud, segjer Herren, Herren.',
    },
    23: {
        1: 'Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Det var tvo kvinnor, døtter åt ei mor.',
        3: 'Og dei dreiv hor i Egyptarland, i sin ungdom dreiv dei hor; der tukla dei med brjosti deira og klemde på deira møyarbarm.',
        4: 'Og namni deira var: Åhåla, den største, og Åhåliba, syster hennar. Og dei vart mine og fødde søner og døtter. Og um namni deira er å segja: Samaria er Åhåla, og Jerusalem Åhåliba.',
        5: 'Men Åhåla gav seg frå meg og dreiv hor, og ho tok til å lysta etter elskarane sine, etter assyrarane, dei våpndjerve,',
        6: 'som var klædde i blått purpur, jarlar og landshovdingar, fagre sveinar alle saman, ridarar, ridande på hestar.',
        7: 'Og med deim heldt ho seg i hordom, med alle dei gildaste av Assurs-sønerne. Og ho sulka seg med alle ho lyste etter, og med alle deira ufysne avgudar.',
        8: 'Og ho heldt seg ikkje frå sin hordom frå Egyptarland. For dei hadde lege med henne i hennar ungdom, og dei hadde klemt på hennar møyarbarm og helt ut yver henne sin hordom.',
        9: 'Difor gav eg henne i henderne på hennar elskarar, i henderne på Assurs-sønerne, som ho hadde lysta etter.',
        10: 'Dei nækte blygsli hennar. Hennar søner og døtter tok dei, og henne sjølv drap dei med sverd. Og ho vart namnspurd ibland kvinnor, og dom heldt dei yver henne.',
        11: 'Og endå hennar syster Åhåliba såg det, vart ho skamlausare i sine lyster enn ho, og verre i sin hordom enn syster si.',
        12: 'Ho lysta etter Assurs-sønerne, jarlar og landshovdingar, våpndjerve karar, gildt klædde, ridarar, ridande på sine hestar, fagre sveinar alle saman.',
        13: 'Og eg såg at ho vart sulka; ein og same veg gjekk dei båe.',
        14: 'Og ho for endå lenger med sin hordom; då ho såg menner rita på veggen, bilæte av kaldæarar, måla med raude liter,',
        15: 'gyrde med belte um lenderne, med breide huvor på hovudet, sjåande til som vognkjempor alle saman, på skap Babels-sønerne som hev Kaldæa til heimland',
        16: '- då lysta ho etter deim fyrst ho såg deim for sine augo, og ho sende bod til deim i Kaldæa.',
        17: 'Og Babels-sønerne kom til henne og låg med henne i elskhug og sulka henne med sin hordom. Men då ho var utsulka med deim, vende hennar sjæl seg frå deim.',
        18: 'Og ho for berrsynt fram med sin hordom og nækte blygsli. Då vende mi sjæl seg ifrå henne likeins som mi sjæl hadde vendt seg frå syster hennar.',
        19: 'Men ho gjekk endå lenger i sin hordom, med di ho kom i hug ungdomsdagarne sine, då ho dreiv hor i Egyptarland.',
        20: 'So tok ho til å lysta etter horkallarne deira, som hadde kjøt nett som asen og fløde som hestar.',
        21: 'Og du trådde etter ulivnaden i din ungdom, då egyptarane klemde på barmen din medan du hadde møyarbrjost.',
        22: 'Difor, Åhåliba, so segjer Herren, Herren: Sjå, eg vekkjer upp elskarane dine imot deg, deim som sjæli di hev vendt seg frå, og let deim koma yver deg frå alle stader.',
        23: 'Babels-sønerne og alle kaldæarar, Pekod og Sjoa og Koa, og alle Assurs-sønerne med deim, fagre sveinar, jarlar og hovdingar alle saman, vognkjempor, namnfræge menner, ridande på hestar alle saman.',
        24: 'Og dei skal koma yver deg med stridsmagt, vogner og hjul, og med ein flokk med folkeslag. Store skjoldar og små-skjoldar og hjelmar skal dei setja upp imot deg rundt ikring. Og eg vil setja deim til domarar, og dei skal døma deg med domarne sine.',
        25: 'Og min brennhug skal finna deg, og dei skal fara ått med deg i vreide; nosi di og øyro dine skal dei skjera av, og det som endå er att av deg, skal falla for sverd. Dei skal taka dine søner og døtter, og dei som endå vert att av deg, skal øydast i eld.',
        26: 'Og dei skal draga av deg klædi dine, og dei skal taka dine prydeting.',
        27: 'So vil eg gjera ende på di skjemdarferd og på din hordom frå Egyptarland, og du skal ikkje lyfta augo dine til deim, og Egyptarland skal du ikkje minnast meir.',
        28: 'For so segjer Herren, Herren: Sjå, eg gjev deg i henderne på deim som du hatar, og i henderne på deim som di sjæl hev vendt seg frå.',
        29: 'Og dei skal fara åt med deg i hat og taka alt det du hev stræva i hop og lata deg etter seg naki og berr, horeblygsli di skal verta nækt, og di skjemdarferd og din hordom skal verta synberr.',
        30: 'Dette skal dei gjera med deg, av di du for etter heidningfolk i hordom, for di du sulka deg med deira ufysne avgudar.',
        31: 'På vegen åt syster di hev du gjenge; so gjev eg deg hennar staup i di hand.',
        32: 'So segjer Herren, Herren: Staupet åt syster di skal du drikka, det djupe og vide - til lått og til spott skal du verta - det tek mykje.',
        33: 'Av rus og sorg skal du verta full, eit øgjelegt tynar-staup er staupet åt di syster Samaria.',
        34: 'Og du skal drikka det ut og suga utor det, og på broti av det skal du gnaga, og flengje brjosti dine sund, for eg hev tala, segjer Herren, Herren.',
        35: 'Difor, so segjer Herren, Herren: Etter di du gløymde meg og kasta meg attum din rygg, so ber då du med di skjemd og din hordom.',
        36: 'Og Herren sagde med meg: Menneskjeson! Vil du døma Åhåla og Åhåliba? Lat deim få vita sin styggedomen!',
        37: 'For dei hev drive hor, og det er blod på henderne deira og med sine ufysne avgudar hev dei drive hor, ja, jamvel borni sine, som dei hadde født åt meg, hev dei lata ganga gjenom elden, so dei skulde eta deim.',
        38: 'Dessforutan gjorde dei dette mot meg: Dei sulka min heilagdomen same dagen og vanhelga mine kviledagar.',
        39: 'Når dei hadde slagta borni sine åt sine ufysne avgudar, so kom dei inn i min heilagdom, den same dagen, og vanhelga honom; og sjå, soleis for dei åt midt i mitt hus!',
        40: 'Ja, dei sende jamvel bod etter menner som skulde koma langt burtanfrå, ein sendemann gjekk til deim, og sjå, dei kom: for deim hadde du lauga deg, sminka deg i augo og prydt deg med prydeting.',
        41: 'Og du sat på ein røseleg legebenk, og framanfor honom var duka eit bord, og min røykjelse og min olje hadde du sett uppå det.',
        42: 'Og ståket av ein velnøgd folkehop kunde ein høyra der inne, og attåt menner som var med utav ålmugen, fekk dei seg drykkjebrør frå øydemarki. So gav dei kvendi armband på henderne og ei prydeleg kruna på hovudet.',
        43: 'Då sagde eg um den utlivde skjøkja: «No fyrst driv dei ukjurskapen i det store med henne - ja, rett med henne.»',
        44: 'Dei gjekk inn til henne nett som dei gjeng inn til ei skjøkja; soleis gjekk dei inn til Åhåla og Åhåliba, horkonorne.',
        45: 'So skal då rettferdige menner døma deim etter lovi um horkonor, og um kvende som renner ut blod; for horkonor er dei, og det er blod på henderne deira.',
        46: 'For so segjer Herren, Herren: Eg vil føra fram ein mannefjølde mot deim, og eg vil gjera deim til ei skræma og eit ran.',
        47: 'Mannfjølden skal steina deim i hel og hogga deim sund med sverdi sine. Deira søner og døtter skal dei drepa, og husi deira skal dei brenna upp med eld.',
        48: 'Soleis vil eg gjera ende på skjemdarferdi i landet, og alle kvinnor skal læra å vara seg, so dei ikkje fer med slik ei skjemdarferd som dei.',
        49: 'Og dei skal leggja dykkar skjemdarferd på dykk, og dykkar synder med dei ufysne avgudarne dykkar skal de bera, og de skal sanna at eg er Herren, Herren.',
    },
    24: {
        1: 'Og Herrens ord kom til meg i det niande året, den tiande dagen i tiande månaden; han sagde:',
        2: 'Menneskjeson! Skriv deg upp namnet på dagen - nett denne dagen! Babel-kongen er nådd til Jerusalem nett i denne dag.',
        3: 'Og tala i ein liknad til den tråssuge lyden og seg med deim: So segjer Herren, Herren: Set på gryta, set henne på, og slå vatn uppi henne!',
        4: 'Hav kjøtstykki nedi henne, gode stykke alle, lår og bog! Fyll henne med dei likaste mergbein!',
        5: 'Tak av det likaste av småfenaden! Gjer so eit eldsmål uppunder henne for beini skuld! Lat det fosskoka! Beini nedi henne kokar alt.',
        6: 'Difor, so segjer Herren, Herren: Usæl vere blodbyen: ei gryta med gravrust i, og hennar gravrust gjekk ikkje av henne! Tak utor henne stykke for stykke! det vert ikkje lutkasting um radi.',
        7: 'For blodet ho hev rent ut, er der endå; på eit bert svadberg hev ho helt det ut, ho hev ikkje rent det ut på jordi, so moldi kunde løyna det.',
        8: 'For at harm kunde hevjast og hemnen nå, hev eg late blodet koma på berre svadet, so det ikkje skulde verta løynt.',
        9: 'Difor, so segjer Herren, Herren: Usæl vere blodbyen! Eg og vil gjera eldsmålet stort.',
        10: 'Legg på dugeleg med ved, kveik upp elden! Koka krafti or kjøtet, og lat sodet verta innkoka, so beini vert brende!',
        11: 'Og lat henne standa tom på gløderne, so ho vert heit og koparen glodheit, so ureinska kann smelta utor henne og gravrusti tærast burt.',
        12: 'Eg møddest so sårt med henne, men av gjekk ho ikkje, denne tjukke rusti. I elden då med henne!',
        13: 'Di ureinska er vorti ei skjemd; etter di eg freista å reinsa deg, men du ikkje vart rein, so skal du ikkje verta rein heretter, fyrr eg fær døyva min harm på deg.',
        14: 'Eg, Herren, hev tala; det kjem, og eg vil setja det i verk. Eg let det ikkje ugjort, og ikkje vil eg spara og ikkje angra. Etter dine vegar og dine gjerningar skal dei døma deg, segjer Herren, Herren.',
        15: 'Og Herren ord kom til meg; han sagde:',
        16: 'Menneskjeson! Sjå, eg tek frå deg den dine augo hev hugnad i, ved eit slag. Men du skal ikkje barma deg og ikkje gråta, og ikkje ei tåra må renna.',
        17: 'Sukka i løynd! men syrgjelag yver den daude må du ikkje gjera. Bitt huva di på deg, og tak skorne på føterne dine, og breid ikkje noko utyver skjegget, og et ikkje folks brød!',
        18: 'Og eg tala til folket um morgonen, og kona mi døydde um kvelden. Og morgonen etter gjorde eg som eg var fyresagd.',
        19: 'Då sagde folket med meg: «Vil du ikkje segja oss kva det skal tyda åt oss, det du gjer?»',
        20: 'Og eg sagde med deim: Herrens ord kom til meg; han sagde:',
        21: 'Seg med Israels-lyden: So segjer Herren, Herren: Sjå, eg vanhelgar min heilagdom, som de lit på i ovmod, som dykkar augo hev hugnad i, og dykkar sjæl trår etter. Og dykkar søner og døtter, som de hev leivt etter dykk, skal falla for sverd.',
        22: 'Då skal de gjera likeins som eg hev gjort; de skal ikkje breida noko yver skjegget og ikkje eta folks brød.',
        23: 'Og huvorne dykkar skal de hava på hovudi og skorne dykkar på føterne, og de skal ikkje barma dykk og ikkje gråta. Og de skal talmast av i dykkar misgjerningar og stynja kvar med annan.',
        24: 'Og Ezekiel skal vera eit teikn åt dykk; heiltupp som han hev gjort, skal de gjera. Når det kjem, då skal de sanna at eg er Herren, Herren.',
        25: 'Og du, menneskjeson! Skal det ikkje henda den dagen når eg tek frå deim deira trygd, deira herlege frygd, det som deira augo hadde hugnad i og deira sjæl trådde etter, deira søner og døtter,',
        26: 'at den dagen skal dei som slepp undan koma til deg og gjera det kunnigt, so folk høyrer på?',
        27: 'Den same dagen skal du få lata upp munnen, når dei undansloppne er komne, og du skal tala og ikkje lenger vera mållaus, og du skal vera eit teikn åt deim, og dei skal sanna at eg er Herren.',
    },
    25: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Vend di åsyn mot Ammons-sønerne og spå imot deim!',
        3: 'Og du skal segja med Ammons-sønerne: Høyr Herrens, Herrens ord! So segjer Herren, Herren: Etter di du sagde: «Hå, hå!» yver heilagdomen min, for di han vart vanhelga, og yver Israels land, for di det er i øyde lagt, og yver Juda-lyden, for di han laut fara i utlægd,',
        4: 'difor, sjå, so skal austmennerne få deg til eiga, og dei skal slå sine tjeldlæger i deg og finna seg bustader i deg. Dei skal eta frukti di, og dei skal drikka mjølki di.',
        5: 'Og eg vil gjera Rabba til beitemark åt kamelar og Ammonlandet til felæger. Og de skal sanna at eg er Herren.',
        6: 'For so segjer Herren, Herren: Av di du klappa med henderne og trappa med føterne og med all vanvyrdnaden i di sjæl fagna deg yver Israels land,',
        7: 'difor, sjå, so retter eg handi mi imot deg og gjev deg til herfang åt folki og ryd deg ut or folkeslagi og let deg tynast ut or landi. Eg vil øyda deg ut, so du skal sanna at eg er Herren.',
        8: 'So segjer Herren, Herren: Av di Moab og Se’ir segjer: «Sjå, det gjekk med Juda-lyden likeins som med alle hine folki,',
        9: 'difor, sjå, so vil eg gjera eit op i sida åt Moab frå der byarne ligg, frå byarne hans alle stader, landepryda Bet-Jesjimot, Ba’al-Meon og alt til Kirjatajim,',
        10: 'so Austheims-sønerne kann koma seg inn, likeins som eg vil gjera med Ammons-sønerne, som eg gjev deim til eiga, so ein ikkje meir skal minnast Ammons-sønerne millom folki.',
        11: 'Og yver Moab vil eg halda dom, so dei skal sanna at eg er Herren.',
        12: 'So segjer Herren, Herren: Av di Edom var so hemnfus mot Juda-lyden og førde skuld yver seg, med di dei hemnde seg på deim,',
        13: 'difor - segjer Herren, Herren - so vil eg retta ut handi mi mot Edom og øyda for honom folk og fe, og eg vil gjera det til ei audn frå Teman, og heilt burt til Dedan skal dei falla for sverd.',
        14: 'Og min hemn mot Edom vil eg leggja i henderne på mitt folk Israel, og dei skal fara åt med Edom etter min vreide og harm, og dei skal få kjenna min hemn, segjer Herren, Herren.»',
        15: 'So segjer Herren, Herren: Av di filistarane for hemnfuse fram, av di dei med all vanvyrdnaden i si sjæl hemnde seg med tynarverk, av eit ævelegt hat,',
        16: 'difor, so segjer Herren, Herren: Sjå, eg rettar ut handi mi mot filistarane og ryd ut kretarane og tyner det som vert leivt attmed havstrandi.',
        17: 'Og eg vil lata stor hemn råma deim vreide-refsingar, og dei skal sanna at eg er Herren, når eg let hemnen min nå deim.',
    },
    26: {
        1: 'So hende det i det ellevte året, den fyrste dagen i månaden, at Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Av di Tyrus segjer um Jerusalem: «Hå, hå! I sund er folkeporten broten, til meg er han no flutt; eg vert fyllt sidan han er øydelagd,»',
        3: 'difor, so segjer Herren, Herren: Sjå, eg skal finna deg, Tyrus, og let mange folkeslag koma veltande upp yver deg, likeins som havet kjem veltande med bårorne sine.',
        4: 'Og dei skal brjota ned murarne kring Tyrus og riva ned tårni, og eg vil sopa dusti av tufterne, og gjera byen til eit snaudt svadberg.',
        5: 'Ein stad til å greida garn på skal det verta der uti havet, for eg hev tala, segjer Herren, Herren. Og det skal verta til herfang åt folki.',
        6: 'Og døtterne som er på innlandet, skal verta drepne med sverd. Og dei skal sanna at eg er Herren.',
        7: 'For so segjer Herren, Herren: Sjå, eg sender mot Tyrus Nebukadressar, Babel-kongen, frå Norderlandi, kongen yver kongarne, med hestar og med vogner og med hestfolk og med ein her og mykje folk.',
        8: 'Døtterne dine på innlandet skal han drepa med sverd. Og han skal gjera ein åtaksmur deg og kasta upp ein voll imot deg og reisa upp eit skjoldtak imot deg.',
        9: 'Og murstangaren sin skal han setja mot murarne dine, og tårni dine skal han brotja ned med jarni sine.',
        10: 'Hans hestar i mengd skal hylja deg i dumba. Gnyen av hestfolk og hjul og vogner fær murarne dine til å dirra, når han fer inn gjenom portarne dine, sameleis som når ein fer inn i herteken by.',
        11: 'Med hovarne sine skal hestarne hans trakka ned alle gatorne dine. Lyden din skal han slå i hel med sverd, og dei sterke stolparne dine skal stupa til jordi.',
        12: 'Og dei skal rana din rikdom og gjera dine varor til herfang og brjota ned dine murar, og dine hugnadlege hus skal dei riva ned. Og steinarne dine og treverket ditt og dusti etter deg skal dei kasta beint på sjøen.',
        13: 'Og ljoden av songarane dine let eg tagna, og ljomen av cithrarne dine skal ein aldri meir høyra.',
        14: 'Og eg vil gjera deg til ei bert svadberg, ein stad til å greida garni på skal du verta; du skal aldri verta uppatt-bygd. For eg, Herren, hev tala, segjer Herren, Herren.',
        15: 'So segjer Herren, Herren med Tyrus: Skal ikkje havstrenderne bivra for omen av ditt fall, når gjenomstungne styn, når dei drep og myrder midt inni deg?',
        16: 'Då skal dei stiga ned av sine høgsæte alle fyrstarne på havet, og dei skal leggja av seg kåporne sine og taka av seg sine rosesauma klæde. I skjelte skal dei klæda seg, på jordi skal dei sitja og skjelva kvar augneblink og ræddast yver lagnaden deg.',
        17: 'Og dei skal setja i med ein syrgjesong og segja til deg: «Korleis er du lagd i øyde, du som sjømanna bustad, byen den fræge, som hadde magti på havet, både du og dine ibuarar, som skaut skjelk i bringa på alle som budde der?',
        18: 'No skjelv dei, øyarne, den dagen du fell, og utøyarne i havet tek fæla av di endelykt.»',
        19: 'For so segjer Herren, Herren: Når eg gjer deg til ein øydestad, lik byar der ingen bur, når eg sender dragsudi uppetter deg og let storhavet gøyma deg,',
        20: 'då støyper eg deg ned med deim som i gravi fer ned, til folket frå fordom, og let deg bu i nedheimen, i audner frå æva, med deim som fer ned i gravi, so ingen skal bu i deg; men eg vil gjeva pryda i landet åt dei livande.',
        21: 'Til ei skræma vil eg gjera deg, og so er du upp i inkje, og ein skal leita etter deg, men ikkje finna deg i all æva, segjer Herren, Herren.',
    },
    27: {
        1: 'Herrens ord kom til meg; han sagde:',
        2: 'Og du, menneskjeson! Set i med ein syrgjesong yver Tyrus!',
        3: 'Og du skal segja til Tyrus som bur attmed innlaupet frå havet, som handlar med folkeslagi på mange havstrender: So segjer Herren, Herren: Tyrus, du segjer: «Storfager er eg og frid.»',
        4: 'I havsens hjarta er dine landskil, dei som bygde deg, gjorde deg storfager.',
        5: 'Av cypresstre frå Senir bygde dei alt plankeverket på deg. Cedertre frå Libanon tok dei og gjorde til mastr på deg.',
        6: 'Av eik frå Basan gjorde dei årarne dine. Dekket ditt gjorde dei av filsbein, innlagt i buskbom frå Kittim-øyarne.',
        7: 'Manglita linty frå Egyptarland hadde du til segl, til å vera ditt merke, blått og purpurraudt ty frå Elisa-øyarne var ditt soltjeld.',
        8: 'Folk frå Sidon og Arvad var roarar åt deg, dei kunnige av dine eigne, Tyrus, dei vart hovudsmennerne dine.',
        9: 'Dei øvste og visaste frå Gebal hadde du til å bøta lekarne dine. Alle havskip og deira sjømenner var i deg og handla med deg.',
        10: 'Menner frå Persia, Lud og Put var i din her, dine stridsmenner. Skjoldar og hjelmar hengde dei upp i deg, dei gav deg pryda.',
        11: 'Arvads søner og din eigen her var på dine murar rundt ikring, og gammaditar var i dine tårn. Sine skjoldar hengde dei på murarne dine rundt ikring; dei gjorde deg fulleleg fager.',
        12: 'Tarsis handla med deg, av di du hadde so mykje gods. Sylv, jarn, tin og bly gav dei deg for varorne dine.',
        13: 'Javan, Tubal og Mesek, deim hadde du til kræmarar; menneskje og koparkjerald gav dei deg i varebyte.',
        14: 'Frå Togarma-lyden fekk du vognhestar og ridehestar og muldyr for varorne dine.',
        15: 'Dedans søner var kræmarane dine. Mange havstrender kjøpte av di hand; filsbein og ibenholt gav dei deg i skatt.',
        16: 'Syria handla med deg, av di du hadde mang ein eignalut; karfunkelstein, purpur og manglita ty og fint linty og korallar og rubinar gav dei deg i varebyte.',
        17: 'Juda og Israelslandet, dei var kræmarane dine; kveite frå Minnit og søt-kakor og honning og olje og balsam gav dei deg i varebyte.',
        18: 'Damaskus handla med deg, av di du hadde mang ein eignalut, ein ovmengd med allslags gods. Dei gav deg vin frå Hebron og kvit ull.',
        19: 'Vedan og Javan frå Uzal gav att for varorne dine; jarnsmide, kassia og kalmus fekk du i varebyte.',
        20: 'Dedan handla med deg med salklæde til å rida på.',
        21: 'Arabia og alle fyrstarne i Kedar kjøpte av di hand; lamb og verar og bukkar selde dei deg.',
        22: 'Kræmarane i Sjeba og Rama, dei var dine kræmarar; krydda av aller gjævaste slag og allslags dyreverdige steinar og gull gav dei for varorne dine.',
        23: 'Kharan og Kanne og Eden, kræmarane i Sjeba, Assur, Kilmad handla med deg.',
        24: 'Dei var dine kræmarar med prydelege eignating, med kåpor av purpurblått og manglita ty og med spriklute tæpe med tvinna sterke snøre på din marknad.',
        25: 'Med Tarsis-skip gjorde du kjøpstemnorne dine. Du vart fyllt og ovende rik - midt i havet.',
        26: 'Utpå storhavet førde dine roarar deg - austanvinden bryt deg sund midt i havet.',
        27: 'Ditt gods, dine salsvaror og bytevaror, dine sjøfolk, dine skiprar, dei som bøter lekarne dine, og dei som driv din handel, og kvar ein stridsmann som i deg er, med heile ditt mannskap som er um bord, skal stupa midt i havet den dagen du fell.',
        28: 'For naudropi frå skiprarne dine skal markerne bivra.',
        29: 'Og dei skal stiga utor sine skip alle som med årarne sit, mannskapet og kvar skiper på havet, til land skal dei søkja.',
        30: 'Dei skal barma seg yver deg og anka seg sårt. Og dei skal kasta mold på sine hovud, i oska skal dei velta seg.',
        31: 'Og dei skal raka seg snaude i kruna for di skuld og gyrda seg med sekk. Og dei skal gråta yver deg med sjælekvida og øya seg sårt.',
        32: 'Og med dei barmar seg, skal dei setja i med ein syrgjesong yver deg og syrgjande kveda um deg: «Kven er lik Tyrus, som no er tagna midt uti havet?»',
        33: 'Medan varorne dine kom frå havet, metta du mange folkeslag. Med ovmengdi av ditt gods og med dine bytevaror gjorde du kongarne på jordi rike.',
        34: 'No då du er skipbroten og burtkomen på sjøen og ligg på havsens botn, no er dine bytevaror og alt ditt mannskap søkkt i kav med deg.',
        35: 'Alle som bur på havstrenderne, tek fæla av din lagnad; det rys deira kongar i holdet, deira andlit bivra.',
        36: 'Kjøpmennerne ibland folkeslagi hæder deg; Ei skræma er du vorten, du er ikkje til - i all æva.',
    },
    28: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Seg med fyrsten i Tyrus: So segjer Herren, Herren: Av di at ditt hjarta ovmodar seg, og du segjer: «Eg er ein gud, i Guds høgsæte sit eg midt i havet,» og du er menneskje og ingen gud, endå du set ditt hjarta jamgodt med Guds hjarta',
        3: '- sjå, visare enn Daniel er du; ingen løyndom kann dei dylja for deg;',
        4: 'med din visdom og ditt vit hev du vunne deg rikdom og samla gull og sylv i dine skattkammer;',
        5: 'med din store klokskap i handel hev du auka rikdomen din, og ditt hjarta ovmoda seg av din rikdom -',
        6: 'difor, so segjer Herren, Herren: Av di du sette ditt hjarta jamgodt med Guds hjarta,',
        7: 'sjå, difor let eg framande koma yver deg, valdsmennerne millom folki, og dei skal draga ut sverdi sine mot din høgprude visdom og vanhelga di pryd.',
        8: 'I gravi skal dei støypa deg ned, og du skal døy ihelslegen manns daude midt uti havet.',
        9: 'Skal tru du då vil segja: «Eg er ein gud,» beint uppi syni på din banemann, endå du er eit menneskje og ingen gud i handi på din dråpsmann?',
        10: 'Som u-umskorne døyr, so skal du døy for framandmanns hand; for eg hev tala, segjer Herren, Herren.',
        11: 'Og Herrens ord kom til meg; han sagde:',
        12: 'Menneskjeson! Set i med ein syrgjesong yver Tyrus-kongen! Og du skal segja med honom; so segjer Herren, Herren: Du som var innsigle på den vel tilmåta bygnaden, full av visdom og fullkomen vænleik:',
        13: 'I Eden, Guds hage, var, yverstrådd med dyre steinar av alle slag: Karneol, topas og demant, krysolit, onyks og jaspis, safir, karfunkel, smaragd og gull. Arbeid i drive metall og utskurd prydde deg. Det var laga den dagen du vart skapt.',
        14: 'Du var ein veldug kerub som gav livd, og eg sette deg til å vera på Guds heilage fjell, millom logande steinar ferdast du.',
        15: 'Ulastande var du på dine vegar frå den dagen du vart skapt, til dess urettvisa fanst hjå deg.',
        16: 'Den store handelen din valda at du vart full av urett og tok til å synda. Då vanhelga eg deg, so du laut burt frå Guds fjell, og eg tynte deg, du livd-gjevande kerub, so du ikkje lenger fekk vera millom dei logande steinar.',
        17: 'Ditt hjarta ovmoda seg av din vænleik, og du spillte din visdom for ditt glim. Til jordi kasta eg deg, framfor augo på kongar lagde eg deg, so dei kunde skoda deg.',
        18: 'Med dine mange misgjerningar, med din urettferdige handel vanhelga du heilagdomarne dine. So let eg eld loga midt utor deg, han skal øyda deg, og eg gjer deg til oska på jordi framfor augo på alle som ser deg.',
        19: 'Alle som kjende deg millom folkeslagi, er forfærde yver deg; ei skræma er du vorten, og du er ikkje til - i all æva.',
        20: 'Og Herrens ord kom til meg; han sagde:',
        21: 'Menneskjeson! Vend di åsyn mot Sidon og spå imot det!',
        22: 'Og du skal segja: So segjer Herren, Herren: Sjå, eg finna deg, Sidon, og eg vil syna meg herleg i deg. Og dei skal sanna at eg er Herren, når eg held dom yver det og helgar meg på det.',
        23: 'Og eg vil senda inn i det sott og blod på gatorne. Og iheldslegne skal falla midt i det for sverd som kjem yver deim rundt ikring, og dei skal sanna at eg er Herren.',
        24: 'Og det skal aldri meir vera for Israels-lyden ein stingande klunger eller svidande tistel av alle deira grannar som svivyrder deim. Og dei skal sanna at eg er Herren, Herren.',
        25: 'So segjer Herren, Herren: Når eg samlar Israels-lyden ifrå folki der som dei er spreidde, då vil eg helga meg på deim framfor augo på folkeslag, og dei skal bu i sitt land som eg gav min tenar Jakob.',
        26: 'Og dei skal bu der i trygd og byggja hus og planta vinhagar, ja, dei skal bu i trygd, medan eg held dom yver alle deira grannar som vanvyrde deim. Og dei skal sanna at eg, Herren, er deira Gud.',
    },
    29: {
        1: 'I det tiande året, den tolvte dagen i tiande månaden, kom Herrens ord til meg; han sagde:',
        2: 'Menneskjeson! Vend di åsyn mot Farao, kongen i Egyptarland, og spå mot honom og imot alt Egyptarland!',
        3: 'Tala og seg: So segjer Herren, Herren: Sjå, eg skal finna deg, Farao, egyptarkonge, du, den store draken som ligg midt uti elvarne sine, og som segjer: «Eg eig mi elv, og sjølv hev eg gjort henne.»',
        4: 'Og eg vil setja krokar i kjakarne dine, og fiskarne i elvarne dine vil eg festa i reisti dine, so dreg eg deg upp utor elvarne dine med alle fiskarne i elvarne dine, dei som er feste i reisti dine.',
        5: 'Og eg skal kasta deg ut i øydemarki, deg og kvar ein fisk i elvarne dine. På berre marki skal du falla; du skal ikkje verta uppteken, ikkje uppsamla, dyri på jordi og fuglarne under himmelen skal få deg til mat.',
        6: 'Og alle som bur i Egyptarland, skal sanna at eg er Herren, for di at dei vart ein røyrstav åt Israels-lyden;',
        7: 'når dei grip um deg med handi, brotnar du og flengjer deim alle i herdi, og når dei styd seg på deg, ryk du i sund og fær deim alle til å sviga i lenderne.',
        8: 'Difor, so segjer Herren, Herren: Sjå, eg let sverd koma yver deg, og eg vil rydja ut or deg folk og fe.',
        9: 'Og Egyptarlandet skal verta til audn og øyda - og dei skal sanna at eg er Herren - for di han sagde: «Elvi er mi, og eg sjølv hev gjort henne.»',
        10: 'Difor, sjå, eg vil finna deg og elvarne dine, og eg vil gjera Egyptarlandet til øydemarker, ei audn lagd i øyde, frå Midgol til Syene og alt til landskilet mot Ætiopia.',
        11: 'Igjenom det skal ikkje mannefot ganga, og fefot skal ikkje ganga gjenom det, og det skal vera ubygt i fyrti år.',
        12: 'Og eg vil leggja Egyptarlandet i øyde midt ibland øydeland, og i byarne - midt ibland øydestader - skal det vera audt i fyrti år. Og eg vil spreida egyptarane millom folki og strå deim kringum i landi.',
        13: 'For so segjer Herren, Herren: Når fyrti år er lidne, vil eg samla egyptarane frå dei folkeslag som dei var spreidde.',
        14: 'Og eg vil venda Egyptarlands lagnad og føra deim attende til Patroslandet, til det landet som dei er ætta ifrå, og der skal dei vera eit vesalt kongerike.',
        15: 'Det skal vera lægre enn andre kongerike og aldri meir hevja seg yver folki, og eg vil lata deim smogna i hop, so dei ikkje skal rikja yver folki.',
        16: 'Og aldri meir skal Israels-lyden der søkja seg livd og soleis minna meg um deira misgjerning, med di dei snur seg etter deim. Og dei skal sanna at eg er Herren, Herren.',
        17: 'So hende det i det sju og tjugande året, den fyrste dagen i fyrste månaden, at Herrens ord kom til meg; han sagde:',
        18: 'Menneskjeson! Nebukadressar, Babel-kongen, hev late heren sin stræva hardt mot Tyrus; kvart eit hovud er fleinskalla, og kvar ei herd avgnura. Men løn hev han og heren hans ikkje fenge av Tyrus for alt sitt stræv imot det.',
        19: 'Difor, so segjer Herren, Herren: Sjå, eg gjev Nebukadressar, Babel-kongen, Egyptarland, og han skal taka rikdomen der og rana ranet og hertaka herfanget, og det skal vera løn åt heren hans.',
        20: 'Til løn åt honom for strævet gjev eg honom Egyptarland; for dei hev arbeidt for meg, segjer Herren, Herren.',
        21: 'Den same dagen vil eg lata eit horn veksa upp åt Israels-lyden; og du skal få lata upp din munn midt ibland deim, og dei skal sanna at eg er Herren.',
    },
    30: {
        1: 'Og Herrens ord kom til meg, han sagde:',
        2: 'Menneskjeson! Spå og seg: So segjer Herren, Herren: Barma dykk: «Å! for ein dag!»',
        3: 'For nær er ein dag, ein dag for Herren; ein myrkskya dag, ei uppgjerdstid for folkeslagi skal det vera.',
        4: 'Og sverd skal koma mot Egyptarland, og Ætiopia skal få skjelve-rider når ihelstungne fell i Egyptarland. Og dei skal taka landsens rikdom, og grunnvollarne skal verta nedrivne.',
        5: 'Ætiopar og folk frå Put og Lud og alt blandingsfolket og Kub og sønerne åt sambandslandet skal falla for sverd i lag med deim.',
        6: 'So segjer Herren: Dei som styd Egyptarland, skal falla, og ovmodet og magti skal kverva; frå Migdol til Syene skal folket falla for sverd, segjer Herren, Herren.',
        7: 'Og i øyde skal dei liggja millom øydeland, og byarne skal vera millom øydestader.',
        8: 'Og dei skal sanna at eg er Herren, når eg kveikjer eld på Egyptarland, og alle deira hjelparar vert krasa.',
        9: 'Den dagen skal det fara sendemenner frå mi åsyn på skip til å setja støkk i det ottelause Ætiopia, og det skal få skjelve-rider som på Egyptarlands dag. For sjå, det kjem.',
        10: 'So segjer Herren, Herren: Eg vil hava Nebukadressar, Babel-kongen, til å gjera ende på den ståkande mengdi i Egyptarland.',
        11: 'Han og lyden hans med honom, valdsmennerne millom folki, skal verta henta til å herja landet. Og dei skal draga sine sverd mot Egyptarland og fylla landet med drepne menner.',
        12: 'Eg vil lata elvarne torna og selja landet i henderne på illmenne. Og eg vil hava framande til å øyda landet og alt som i det er; eg, Herren, hev tala.',
        13: 'So segjer Herren, Herren: Eg vil tyna dei ufysne gudarne og rydja ut avgudarne or Nof, og aldri meir skal der vera ein fyrste or Egyptarland, og eg vil leggja rædsla på Egyptarland.',
        14: 'Og eg vil leggja Patros i øyde og setja eld på Soan, og halda dom yver No.',
        15: 'Eg vil renna ut min harm yver Sin, den sterke verni åt Egyptarland, og rydja ut den ståkande mengdi i No.',
        16: 'Og eg vil setja eld på Egyptarland, Sin skal bivrande skjelva, og i No bryt dei seg inn, og inn i Nof kjem fiendar ljose dagen.',
        17: 'Dei unge menner i Aven og Pibeset skal falla for sverd, og sjølve skal dei fara i utlægd.',
        18: 'I Tehafnehes skal dagen myrkna når eg der bryt sund egyptaroket, og ovmodet og magti skal endast. Sjølv vert det sveipt i skyer, og døtterne lyt fara i utlægd.',
        19: 'Og eg vil halda dom yver Egyptarland, og dei skal sanna at eg er Herren.',
        20: 'So hende det i det ellevte året, den sjuande dagen i fyrste månaden, at Herrens ord kom til meg; han sagde:',
        21: 'Menneskjeson! Armen åt Farao, egyptarkongen, hev eg brote forderva. Og sjå, han er ikkje vorten umbunden til helsebot, og linda til å bera i fatle, so han kunde sterkna til å gripa sverdet.',
        22: 'Difor, so segjer Herren, Herren: Sjå, eg skal finna Farao, Egyptarlands-kongen, og eg skal brjota armarne hans sund, både den heile og den sundbrotne, og lata sverdet falla or handi hans.',
        23: 'Eg vil spreida egyptarane ibland folki og strå deim ut i landi.',
        24: 'Og Babel-kongens armar skal eg styrkja og gjeva honom sverdet mitt i hand. Men Faraos armar vil eg brjota, og han skal stynja for hans åsyn som ein stungen mann.',
        25: 'Ja, Babel-kongens armar vil eg styrkja, men Faraos armar skal siga ned. Og dei skal sanna at eg er Herren, når eg gjev Babel-kongen sverdet mitt i hand, og han retter det ut mot Egyptarland.',
        26: 'Og eg vil spreida egyptarane ibland folki og strå deim ut i landi, og dei skal sanna at eg er Herren.',
    },
    31: {
        1: 'So hende det i det ellevte året, den fyrste dagen i den tridje månaden, at Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Seg med Farao, egyptarkongen, og hans ståkande mengd: Kven likjest du på i di storvyrda?',
        3: 'Sjå, Assur var eit cedertre på Libanon med fagre greiner, ein skuggerik skog og høg på vokster, millom skyerne var hans kruna.',
        4: 'Vatnet gjorde honom stor, vatsdjupet gjorde honom høg. Med åerne sine gjekk det kringum hans plantehage og sende vatsveiterne sine burtåt alle trei på marki.',
        5: 'Difor vart han høgre på vokster enn alle trei på marki. Og mange var hans greiner og lange hans kvister, av all den vatningi, når han rette deim ut i veret.',
        6: 'På kvistarne hans laga dei seg reir, alle himmelens fuglar, under greinerne hans fødde alle dyr på marki sine ungar, og hans skugge gav livd åt alle dei mange folkeslagi som budde der.',
        7: 'Og han var fager i sin vyrdelege storleik med sine lange greiner, for innmed roti hans var det nøgdi av vatn.',
        8: 'Inkje var cedertre i Guds hage hans jamlike; cypressor kunde ikkje liknast med hans kvister, og løntre var ikkje som hans greiner; det beid ikkje tre i Guds hage jamfagert med honom.',
        9: 'Eg hadde prydt honom med greiner i mengd, og dei ovunda honom alle Eden-trei som var i Guds hage.',
        10: 'Difor, so segjer Herren, Herren: Sidan han er vorten so høg på vokster og hev tøygt kruna si upp imillom skyerne, og hjarta hans ovmodar seg av denne store høgdi,',
        11: 'so gjev eg honom i henderne på ein hovding yver folki; med honom fær han å gjera; det er for gudløysa hans eg hev drive honom ut.',
        12: 'Og framande, valdsmennerne millom folki, hev hogge honom ned og late honom liggja. På fjelli og i kvar ein dal fall hans kvister, og greinerne hans ligg sundbrotne nedi kvart eit gil i landet. Og alle folk på jord er stigne ned utor skuggen hans som gav deim livd, og hev late honom liggja.',
        13: 'På den falne stomnen hans held alle himmelens fuglar til, og yver greinerne hans fer kvart dyr i skog',
        14: '- for at ikkje noko velvatna tre skal ovmoda seg av sin vokster og tøygja kruna si upp imillom skyerne, og dei velduge av deim, dei som syg vatn i mengd, ikkje skal standa der høgreiste. For alle er dei gjevne dauden i vald, so dei lyt fara ned til nedheimen, midt imillom mannsborni, til deim som er stigne ned i gravi.',
        15: 'So segjer Herren, Herren: Den dagen han for ned til helheimen, let eg syrgja på honom; vatsdjupet breidde eg yver for hans skuld, og åerne derifrå stemde eg, og dei store vatn laut stana. Og eg klædde Libanon i svart for hans skuld, og kvart tre på marki ormegtast for hans skuld.',
        16: 'Med dunen av hans fall fekk eg folkeslag til å skjelva, då eg støypte honom ned i helheimen med deim som fer ned i gravi. Då huggast dei i nedheimen, alle Eden-trei, dei likaste og beste på Libanon, alle som drikk vatn.',
        17: 'Dei og for ned i helheimen til deim som var slegne i hel med sverd. For dei hadde vore hans arm medan dei sat i livd i hans skugge midt imillom folki.',
        18: 'Kven likjest du soleis på i herlegdom og storvyrda ibland Eden-trei? - So skal du då verta støypt med Eden-trei ned i nedheimen; midt imillom u-umskorne skal du liggja med deim som er slegne i hel med sverd. Dette er Farao og heile hans ståkande mengd, segjer Herren, Herren.',
    },
    32: {
        1: 'So hende i det tolvte året, den fyrste dagen i tolvte månaden, at Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Set i med ein syrgjesong yver Farao, egyptarkongen, og seg til honom: Ei ungløva millom folki vilde du vera lik, og so var du som draken i havet, og du for fram i elvarne dine, og grugga upp vatnet med føterne dine og rota upp straumarne.',
        3: 'So segjer Herren, Herren: Eg vil då breida ut garnet mitt yver deg i ei samling av mange folkeslag, og dei skal draga deg upp med noti mi.',
        4: 'Eg vil kasta deg upp på land og burt på marki vil eg slengja deg, og eg vil gjeva alle himmelens fuglar tilhelde på deg og lata dyri på heile jordi metta seg med deg.',
        5: 'Eg vil kasta kjøtet ditt upp på fjelli og fylla dalarne med den store skrotten din.',
        6: 'Og eg vil vatna landet som du sym i med blodet ditt, heilt upp til fjelli, og bekkjefari skal verta fulle av deg.',
        7: 'Og når let deg slokna, vil eg breida yver himmelen og klæda hans stjernor i svart, yver soli vil eg breida skyer, og månen skal ikkje skina med sitt skin.',
        8: 'Alle skinande himmelljos vil eg klæda i svart for di skuld, og eg vil leggja myrker på landet ditt, segjer Herren, Herren.',
        9: 'Og eg vil lata mange folkeslag gremmast i hjarta, når eg gjer tjonet på deg kunnigt millom folki i land som du ikkje kjenner.',
        10: 'Eg vil gjera mange folkeslag forfærde yver deg, og deira kongar skal rysja i holdet yver deg, når eg svingar mitt sverd framfor augo deira, og dei skal bivra kvar augneblink, kvar og ein for sitt liv, den dagen du fell.',
        11: 'For so segjer Herren, Herren: Sverdet åt Babel-kongen skal koma yver deg.',
        12: 'Di ståkande hop vil eg lata falla for sverdi at kjempor, valdsmenner millom folki alle saman. Og dei skal tyna Egyptarlands ovmod, og all den ståkande hopen skal verta øydd.',
        13: 'Og eg vil rydja ut alt feet frå dei mange vatni, og ingen manns fot skal heretter grugga deim, og ingi ku-klauv skal grugga deim.',
        14: 'Då vil eg lata vatni deira minka og løkjerne deira renna som olje, segjer Herren, Herren,',
        15: 'når eg legg Egyptarlandet i øyde og audn - eit tomt land, av di eg slær ned alle som i det bur. Og dei skal sanna at eg er Herren.',
        16: 'Ein syrgjesong er dette, og syngja honom skal dei, folke-døtterne skal syngja honom; um Egyptarland med si ståkande mengd skal dei kveda det, segjer Herren, Herren.',
        17: 'So hende det i det tolvte året, den femtande dagen i månaden, at Herrens ord kom til meg; han sagde:',
        18: 'Menneskjeson! Barma deg yver Egyptarlands ståkande mengd og send henne ned, henne og døtterne åt herlege folkeslag, til nedheimen med deim som fer i gravi.',
        19: 'Kven gjeng du no framum i vænleik? Far ned og få deg læger millom u-umskorne.',
        20: 'Ibland sverdslegne menner skal dei falla. Sverdet er gjeve; drag henne burt og heile hennar ståkande mengd!',
        21: 'Velduge millom kjempor skal tala um honom og hans hjelpesmenner midt utor helheimen: «Ned er dei farne, der ligg dei, dei u-umskorne, slegne i hel med sverd.»',
        22: 'Der er Assur og heile hans lyd, rundt kringum honom er hans graver; alle er dei slegne i hel, falne for sverd.',
        23: 'Han fekk sine graver inst inni hola, og hans lyd er rundt kringum hans graver; alle er dei slegne i hel, falne for sverd, dei som breidde ut skræmsla i landet åt dei livande.',
        24: 'Der er Elam og heile hans ståkande mengd, rundt kringum hans graver; alle er dei slegne i hel, falne for sverd, dei som u-umskorne for ned til nedheimen, dei som breidde ut skræmsla i landet åt dei livande, og bar si skam med deim som fer ned i gravi.',
        25: 'Midt imillom drepne menner gav dei honom læger med heile hans ståkande mengd, rundt ikringum honom er hans graver. Alle er dei u-umskorne, slegne i hel med sverd, di at dei breidde ut skræmsla i landet åt dei livande, og dei bar si skam med deim som for ned i gravi; midt imillom drepne menner vart han lagd.',
        26: 'Der er Mesek-Tubal og heile hans ståkande mengd, rundt kringum honom er hans graver. Alle er dei u-umskorne, slegne i hel med sverd, di at dei breidde ut skræmsla i landet åt dei livande.',
        27: 'Skulde dei då ikkje liggja hjå kjempor, hjå dei falne av dei u-umskorne, som for ned i helheimen med sin stridsbunad og fekk sverdi sine lagde under sine hovud, og misgjerningarne sine yver sine bein, for dei hadde vore ei skræmsla for kjempor i landet åt dei livande?',
        28: 'Og du, midt ibland u-umskorne skal du verta krasa, og du skal liggja hjå deim som er slegne i hel med sverd.',
        29: 'Der er Edom med sine kongar og alle sine fyrstar, som, med alt sitt velde, er lagde hjå deim som er slegne i hel med sverd. Dei skal liggja hjå dei u-umskorne, og hjå deim som fer ned i gravi.',
        30: 'Der er fyrstarne frå Norderland alle saman, og alle Sidon-buarne som for ned med drepne menner og vart til skammar, endå dei i sitt velde hadde vore til skræmsla, og u-umskorne fekk dei læger hjå dei som var slegne i hel med sverd. Og dei bar si skam med deim som fer ned i gravi.',
        31: 'Deim skal Farao sjå, og huggast yver all si ståkande mengd. Slegne i hel med sverd er Farao og heile hans her, segjer Herren, Herren.',
        32: 'For eg breidde ut rædsla for honom i landet åt dei livande. Og han skal verta lagd hjå dei u-umskorne, med deim som er slegne i hel med sverd, Farao og all hans ståkande mengd, segjer Herren, Herren.',
    },
    33: {
        1: 'Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Tala til landslyden din og seg med deim: Når eg let sverd koma yver eit land, og dei tek utav folket i landet og set honom til vaktmann åt seg,',
        3: 'og han ser sverdet koma yver landet og blæs i luren og varar folket,',
        4: 'og einkvan høyrer ljomen av luren, men ikkje let seg vara, og sverdet kjem og tek honom burt, då skal blodet hans vera på hans eige hovud;',
        5: 'ljomen av luren høyrde han, men let seg ikkje vara, blodet hans skal kome yver honom sjølv; for hadde han late seg vara, so hadde han berga livet.',
        6: 'Men um vaktmannen ser sverdet koma og ikkje blæs i luren, og folket ikkje vert vara, og sverdet kjem og tek burt einkvan av deim, då er han burtteken for si misgjerning, men blodet hans vil eg krevja av handi åt vaktmannen.',
        7: 'Og, du menneskjeson! Til vaktmann hev eg sett deg åt Israels-lyden. Når du då høyrer eit ord frå min munn, so skal du vara deim åt frå meg.',
        8: 'Um eg då segjer med den ugudlege: «Du ugudlege, du skal døy,» og du ikkje talar og varar den ugudlege for hans åtferd, då skal han, den ugudlege, døy for si misgjerning, men blodet hans vil eg krevja av di hand.',
        9: 'Men um du hev vara den ugudlege for hans åtferd, at han måtte venda um frå henne, men han vender ikkje um frå si åtferd, då skal han døy for si misgjerning, men du hev berga di sjæl.',
        10: 'Og du, menneskjeson! Seg til Israels-lyden: So segjer det: «Våre brot og våre synder tyngjer på oss, og for deim talmast me reint burt; kor kann me då liva?»',
        11: 'Seg med deim: So sant som eg liver, segjer Herren, Herren, eg hev ikkje hugnad i det at den ugudlege døyr, men i det at den ugudlege vender um frå si åtferd og liver. Vend um, vend um frå dei vonde vegarne dykkar! For kvi vil de døy, du Israels-lyd?',
        12: 'Og du, menneskjeson! Seg med ditt folks born: Rettferdig manns rettferd skal ikkje frelsa honom på hans misgjerds-dag, og ugudleg manns gudløysa skal ikkje fella honom den dagen han vender um frå si gudløysa, og ein rettferdig skal ikkje kunna liva ved si rettferd den dagen han syndar.',
        13: 'Når eg segjer med den rettferdige at han skal liva, men han lit på si rettferd og gjer urett, då skal alle hans rettferdige verk verta gløymde, og for sin urett som han gjorde, skal han døy.',
        14: 'Og når eg segjer til den ugudlege: «Du skal døy,» og han vender um frå si synd og gjer rett og rettferd,',
        15: 'so han, den gudlause, gjev pant attende, kjem att med rana gods, ferdast i livsens bod, so han ikkje gjer urett, då skal han liva, han skal ikkje døy.',
        16: 'Alle synderne som han hev gjort, skal vera gløymde. Rett og rettferd hev han gjort, liva skal han.',
        17: 'Mitt folks born segjer: «Herrens åtferd er ikkje rett,» endå at det er deira eigi åtferd som ikkje er rett.',
        18: 'Når ein rettferdig vender um frå si rettferd og gjer urett, so skal han døy for det.',
        19: 'Og når den gudlause vender um frå si gudløyse og gjer rett og rettferd, so skal han få liva for det.',
        20: 'Endå segjer de: «Herrens åtferd er ikkje rett.» Eg vil døma dykk kvar etter si åtferd, du Israels-lyd.',
        21: 'So hende det i det tolvte året etter me var burtførde, den femte dagen i den tiande månaden, at dei undanslopne frå Jerusalem kom til meg og sagde: «Byen er teken.»',
        22: 'Men Herrens hand var komi yver meg um kvelden, fyrr dei undanslopne kom; og han let upp munnen min innan dei kom til meg um morgonen. So var då munnen min upplaten, og eg var ikkje mållaus meir.',
        23: 'Og Herrens ord kom til meg; han sagde:',
        24: 'Menneskjeson! Dei som bur millom desse røysarne i Israelslandet, dei segjer: «Abraham var berre ein, og han fekk landet til eiga, men me er mange, oss er landet gjeve til eiga.»',
        25: 'Seg difor med deim: So segjer Herren, Herren: De et kjøtet med blodet i og retter augo dykkar etter dei ufysne avgudarne dykkar, og renner ut blod - og de skulde eiga landet!',
        26: 'De lit på dykkar sverd, de fer med skjemdarverk, og skjemmer konorne åt kvarandre - og de skulde eiga landet?',
        27: 'So skal du segja med deim: So segjer Herren, Herren: So sant som eg liver, skal dei som bur millom røysarne falla for sverd, og den som er på marki, gjev eg til mat åt udyri, og dei som held på knausar og i hellerar, skal døy av sott.',
        28: 'Og eg vil leggja landet i audn og øyde, og det skal vera ute med ovmodet og magti hjå det, og Israels heidar skal liggja i øyda, so ingen ferdast der.',
        29: 'Og dei skal sanna at eg er Herren, når eg legg landet i audn og øyde for alle deira skjemdarverk, som dei hev gjort.',
        30: 'Og du, menneskjeson! Ditt folks born talar seg imillom um deg frammed veggjerne og i husdørerne, og segjer med kvarandre, den eine med den andre: «Kom, lat oss høyra kva for eit ord det er som no gjeng ut frå Herren!»',
        31: 'Og dei kjem åt deg, nett som eit heilt folk kjem, og set seg framfor di åsyn og læst vera mitt folk og lyder på ordi dine; men dei gjer ikkje etter deim. For det munnen deira likar, det gjer dei, og etter vinning fer deira hjarte.',
        32: 'Og sjå, du er som eit elskhugskvæde åt deim, som ein songar med vænt mål og ljuvlegt spel. Og dei lyder på ordi dine, men gjer ikkje etter deim.',
        33: 'Men når det kjem - og koma skal det - då skal dei sanna at ein profet hev vore millom deim.',
    },
    34: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Spå mot Israels hyrdingar! Spå og seg med deim, med hyrdingarne: So segjer Herren, Herren: Usæle Israels hyrdingar som røktar seg sjølve! Er det ikkje hjordi hyrdingen skal røkta?',
        3: 'Feita et de, og med ulli klæder de dykk, og det gjødde slagtar de; hjordi gjæter de ikkje.',
        4: 'Det veike hev de ikkje styrkt, og det sjuke hev de ikkje lækt, det beinbrotne hev de ikkje bunde um, og det burtdrivne hev de ikkje sanka, og det burtkomne hev de ikkje leita upp, men de hev fare hardt fram mot deim og med vald.',
        5: 'Og dei vart spreidde, av di dei var hyrdinglause, og dei vart til føda åt kvart villdyr på marki, og spreidde vart dei.',
        6: 'Forvilla fer sauerne mine på alle fjell og på alle høge hamrar, og utyver alt landet er sauerne mine spreidde, og ingen spør etter deim, og ingen leitar.',
        7: 'Difor, de hyrdingar, høyr Herrens ord!',
        8: 'So sant som eg liver, segjer Herren, sanneleg, etter di sauerne mine er vorte til eit ran, ja, sauerne mine er vortne til føda for åt kvart villdyr på marki, og hyrdingarne mine ikkje spurde etter sauerne mine, men hyrdingarne røkta seg sjølve og ikkje røkta sauerne mine -',
        9: 'difor, de hyrdingar, høyr Herrens ord!',
        10: 'So segjer Herren, Herren: Sjå, eg vil finna hyrdingarne og krevja sauerne mine av deira hand og taka frå deim gjætsla, so hyrdingarne ikkje lenger skal røkta seg sjølve. Og eg vil berga sauerne mine frå deira munn, so dei ikkje skal verta til føda åt deim.',
        11: 'For so segjer Herren, Herren: Sjå, her er eg sjølv, og eg vil spyrja etter sauerne mine og sjå til deim.',
        12: 'Likeins som ein hyrding ser til si hjord den dagen han er millom dei spreidde sauerne sine, soleis vil eg sjå til sauerne mine. Og eg vil berga deim frå alle stader der dei er spreidde på ein dag med skyer og myrkeskodda.',
        13: 'Og eg vil føra deim ut ifrå folkeslagi og sanka deim ut or landi, og føra deim til deira eige land; og eg vil gjæta deim i Israelsfjelli, i dalarne og på alle bustader i landet.',
        14: 'I ei god gjætslemark vil eg gjæta deim, og i Israels høge fjell skal deira hamning vera. Der skal dei roa seg i ei god hamning og ganga i feit beitemark i Israelsfjelli.',
        15: 'Eg sjølv vil gjæta sauerne mine, og eg vil få deim til å roa seg, segjer Herren, Herren.',
        16: 'Det burtkomne vil eg leita upp, og det burtdrivne vil eg sanka, og det beinbrotne vil eg binda um, og det sjuke vil eg styrkja. Men det feite og det sterke vil eg tyna; rett vil eg røkta deim.',
        17: 'Og de, sauerne mine - so segjer Herren, Herren -: Sjå, eg dømer millom sauer og sauer, millom verar og bukkar.',
        18: 'Er det ikkje nok åt dykk å ganga i det beste beite, sidan de trakkar ned med føterne det som stend att på beitet dykkar? Er det ikkje nok at de drikk det klåraste vatnet, sidan de rotar upp med føterne det som er att?',
        19: 'Og sauerne mine, dei lyt eta det som de hev trakka med føterne, og drikka det de hev rota upp med føterne.',
        20: 'Difor, so segjer Herren, Herren med deim: Sjå, her er eg sjølv, og eg vil døma millom dei feite sauerne og dei magre sauerne.',
        21: 'Etter di de trengjer alle dei veike undan med sida og bog og stangar deim med horni dykkar, til de fær spreidt deim og jaga deim av,',
        22: 'so vil eg berga sauerne mine, og dei skal ikkje lenger vera til ran, og eg vil døma millom sauer og sauer.',
        23: 'Og eg vil reisa upp ein einaste hyrding yver deim, og han skal gjæta deim, min tenar David. Han skal gjæta deim, og han skal vera deira hyrding.',
        24: 'Eg, Herren, skal vera deira Gud, og min tenar David skal vera fyrste millom deim. Eg, Herren, hev tala.',
        25: 'Og eg vil gjera ei fredspakt med deim og rydja ut udyr or landet, so dei trygt kann bu i øydemarki og sova i skogarne.',
        26: 'Og til ei velsigning vil eg gjera deim og landet rundt ikring min haug, eg vil lata det regna i rett tid, eit regn til velsigning skal det vera.',
        27: 'Og trei på marki skal gjeva si frukt, og jordi skal gjeva si grøda, og dei skal hava det trygt i landet sitt. Og dei skal sanna at eg er Herren, når eg bryt sund stengerne i oket deira, og frelsar deim frå deira hender som trælka deim.',
        28: 'Og dei skal ikkje lenger vera eit ran for folki, og villdyri i landet skal ikkje eta deim upp. Men trygt skal dei bu, og ingen skal skræma deim.',
        29: 'Og eg vil laga til ein namngjeten plantehage åt deim, og dei skal aldri meir verta burtrykte av hunger i landet, og aldri meir skal dei tola hæding frå heidningfolki.',
        30: 'Og dei skal sanna at eg, Herren, deira Gud, er med deim, og at dei, Israels-lyden, er mitt folk, segjer Herren, Herren.',
        31: 'Og de, sauerne mine, sauerne som eg beiter, menneskje er de. Eg er dykkar Gud segjer, Herren, Herren.',
    },
    35: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Vend di åsyn mot Se’irfjellet og spå imot det.',
        3: 'Og du skal segja med det: So segjer Herren, Herren: Sjå, eg vil finna deg, Se’irfjell, og eg vil retta ut mi hand imot deg og leggja deg i audn og øyde.',
        4: 'Byarne dine vil eg gjera til steinrøysar, og du sjølv skal verta ei audn. Og du skal sanna at eg er Herren.',
        5: 'Etter di du ber på ein æveleg fiendskap og let Israels-borni koma under sverds-egg i deira usæletid, den tidi då misgjerningi laut enda,',
        6: 'difor, so sant eg liver, segjer Herren, Herren, til blod vil eg gjera deg, og blod skal søkja på deg. Sidan du ikkje hev hata blod, so skal blod søkja på deg.',
        7: 'So vil eg då leggja Se’irfjellet i audn og øyde, og eg vil rydja ut or det både komande og farande.',
        8: 'Og eg vil fylla fjelli med slegne menner. På dine haugar og i dine dalar og i alle dine gil skal menner falla, slegne med sverd.',
        9: 'Til ævelege audner vil eg gjera deg, og byarne dine skal ikkje atter verta bustader, og de skal sanna at eg er Herren.',
        10: 'For di du sagde: «Båe folki og båe landi skal verta mine, og eg vil taka deim til eiga,» endå Herren hev vore der,',
        11: 'difor, so sant eg liver, segjer Herren, Herren, vil eg gjera med deg etter den vreiden og ovundi som du hev synt i ditt hat imot deim, og eg skal verta kjend hjå deim når eg dømer deg.',
        12: 'Og du skal sanna at eg Herren. Eg hev høyrt alle hæde-ordi dine, som du hev tala mot Israelsfjelli, då du sagde: «Dei er i øyde lagde! dei er gjevne åt oss til mat.»',
        13: 'Og de hev bruka munnen mot meg i ovmod og var ordrame mot meg; eg hev nok høyrt det.',
        14: 'So segjer Herren, Herren: Medan all jordi fagnar seg, vil eg leggja deg i øyde.',
        15: 'Likeins som du fagna deg yver arvluten åt Israels-lyden, at han vart avøyd, so vil eg gjera med deg; til audn skal du verta, du Se’irfjell, og alt Edom - alt i hop, og dei skal sanna at eg er Herren.',
    },
    36: {
        1: 'Og du menneskjeson! Spå um Israelsfjelli! Og du skal segja: Det Israelsfjell, høyr Herrens ord!',
        2: 'So segjer Herren, Herren: For di fienden sagde: «Hå, hå!» yver dykk, og: «Dei ævelege haugar hev vorte vår eiga,»',
        3: 'difor spå og seg: So segjer Herren, Herren: Etter di, ja, etter di dei avøyder dykk og glefser etter dykk frå alle leider, so hine folki kann eigna dykk til seg, og etter di de er komne på folketunga og hev fenge eit låkt ord på dykk ibland folk,',
        4: 'difor, de Israelsfjell, høyr Herrens, Herrens ord! So segjer Herren, Herren, med fjelli og med haugarne, med gili og dalarne og med røysarne på dei aude tufterne og med øydebyarne som hev vorte til ran og spott for hine folki som er der ikring,',
        5: 'difor, so segjer Herren, Herren: Sanneleg, i min brennande harm hev eg tala mot hine folki og mot Edom, som hev etla seg landet mitt til eiga - med heile si hjartans gleda, med vanvyrdnad i si sjæl - so dei kunde driva ut deim som budde der og so rana det.',
        6: 'Difor, spå um Israels land og seg med fjelli og med haugarne, med gili og med dalarne: So segjer Herren, Herren: Sjå, i mitt åbry og i min harm hev eg tala, etter di de hev lote tolt skjemsla frå folki.',
        7: 'Difor, so segjer Herren, Herren: Eg rette handi mi i veret på det: Sanneleg, folki som bur kringum dykk, skal sjølv ljota bera si skjemsla!',
        8: 'Men de, Israelsfjell, skal skjota dykkar greiner og bera dykkar frukt åt mitt folk Israel; for snart skal dei koma heim att.',
        9: 'For sjå, eg vil finna dykk, eg vil snu meg åt dykk, og de skal verta dyrka og sådde.',
        10: 'Og eg vil føra ei mengd med menneskje upp på dykk, all Israels-lyden, og byarne skal atter få folk, og øydestaderne verta bygde å nyo.',
        11: 'Og eg vil gjera dykk rike på folk og fe, og dei skal aukast og verta rike på avkjøme. Og eg vil gjeva dykk folkerike bygder som fyrr i tidi, og eg vil gjera dykk endå meir godt enn i dykkar fyrste tider, og de skal sanna at eg er Herren.',
        12: 'Og eg vil lata menneskje, mitt folk Israel, ferdast på dykk, dei skal taka deg til eiga, og du skal vera deira odel. Og du skal aldri meir gjera deim barnlause.',
        13: 'So segjer Herren, Herren: Etter di dei segjer um deg: «Ein mann-etar er du, og barnlaus hev du gjort dine folk,»',
        14: 'difor skal du aldri meir eta menneskje og aldri meir gjera folki dine barnlause, segjer Herren, Herren.',
        15: 'Og aldri meir let eg deg høyra skjemsla frå folki, og vanvyrdnad frå folkeslagi skal du aldri meir turva tola, og folki dine skal du aldri meir få til å snåva, segjer Herren, Herren.',
        16: 'Og Herrens ord kom til meg; han sagde:',
        17: 'Menneskjeson! Israels-lyden budde i landet sitt, og dei sulka det med si åtferd og sine verk; som ureinskapen hjå kvinna når ho hev sine tider, so var deira åtferd for mi åsyn.',
        18: 'Då rende eg ut min harm yver deim for det blod som dei hadde rent ut yver landet, og for di dei hadde sulka det med dei ufysne avgudarne sine.',
        19: 'Og eg spreidde deim millom folki, og dei vart strådde i landi; etter deira åtferd og verk dømde eg dei.',
        20: 'Då dei kom til dei folki som dei for til, då vanhelga dei mitt heilage namn, med di det vart sagt um deim: «Dette er Herrens folk, men ut or landet hans laut dei fara.»',
        21: 'Då gjorde det meg ilt for mitt heilage namn som Israels-lyden hadde vanhelga millom dei folki som dei var komne til.',
        22: 'Seg difor med Israels-lyden: so segjer Herren, Herren: Ikkje for dykkar skuld, du Israels-lyd, gjer eg det, men for mitt heilage namn skuld, som de hev vanhelga millom dei folki som de er komne til.',
        23: 'Og eg vil helga mitt store namn som vart vanhelga millom folki med di de vanhelga det ibland deim. Og folki skal sanna at eg er Herren, segjer Herren, Herren, når eg helgar meg på dykk for augo deira.',
        24: 'Og eg vil henta dykk frå folki og sanka dykk ut or alle landi og flytja dykk til dykkar eige land.',
        25: 'Og eg vil skvetta reint vatn på dykk, so de vert reine; frå all dykkar ureinska og frå alle dykkar ufysne avgudar vil eg reinsa dykk.',
        26: 'Og eg vil gjeva dykk eit nytt hjarta, og ei ny ånd vil eg gjeva inni dykk, og eg vil taka burt steinhjarta or dykkar kjøt og gjeva dykk eit kjøthjarta.',
        27: 'Og min ande vil eg gjeva inni dykk, og eg vil få dykk til å ferdast i mine bod og til å halda loverne mine og gjera etter deim.',
        28: 'Og de skal bu i det landet som eg gav federne dykkar. Og de skal vera mitt folk, og eg skal vera dykkar Gud.',
        29: 'Og eg vil fria dykk frå all dykkar ureinska. Og eg vil kalla på kornet og gjera det follrikt og ikkje senda svolt på dykk.',
        30: 'Og eg vil mangfalda frukti på trei og grøda på marki, so de ikkje lenger skal taka mot skjemsla frå folki for svolt.',
        31: 'Då skal de minnast dykkar vonde åtferd og dykkar verk, som ikkje var gode. Og de skal styggjast ved dykk sjølve for dykkar misgjerningar og styggjor.',
        32: 'Ikkje for dykkar skuld gjer eg det, segjer Herren, Herren, det vere dykk kunnigt! De må blygjast og skjemmast av åtferdi dykkar, du Israels-lyd.',
        33: 'So segjer Herren, Herren: Den dagen eg reinsar dykk frå alle dykkar misgjerningar, vil eg gjeva byarne folk, og husi som ligg i røysar, skal verta uppatt-bygde.',
        34: 'Og øydeland skal verta dyrka, i staden for at det var ei audn for augo på kvar mann som gjekk framum.',
        35: 'Då skal dei segja: «Dette land som var i øyde lagt, er vorte som Eden-hagen, og byarne som låg i røyser og var øydelagde og nedrivne, er no kringmura og hev sine ibuarar.»',
        36: 'Og dei skal sanna, dei folki som vert att rundt ikring dykk, at eg, Herren, hev bygt upp att det nedrivne, hev planta i det aude landet. Eg, Herren, hev tala, og eg set det i verk.',
        37: 'So segjer Herren, Herren: I dette og vil eg lata Israels born finna meg, so eg gjer det for deim: Eg let menneskje aukast som ein saueflokk.',
        38: 'Som ein heilag saueflokk, som Jerusalems-sauer i høgtiderne, soleis skal dei aude byarne verta: fulle med manneflokkar. Og dei skal sanna at eg er Herren.',
    },
    37: {
        1: 'Herrens hand kom yver meg, og han førde meg i Herrens ande og sette meg ned midt i dalen, som no var full av bein.',
        2: 'Og han let meg ganga framum deim rundt ikring, og sjå, det var ei ovmengd av deim utyver dalen, og sjå, dei var ovleg turre.',
        3: 'Og han sagde med meg: «Menneskjeson! Skal tru dei vil livna upp att, desse beini?» Og eg sagde: «Herre, Herre, du veit det.»',
        4: 'Og han sagde med meg: «Spå yver desse beini! Og seg med deim: De turre bein, høyr Herrens ord!',
        5: 'So segjer Herren, Herren, med desse beini: Sjå, eg let ånd koma i dykk, og de skal livna upp att.',
        6: 'Og eg vil setja senar på dykk og lata det koma kjøt på dykk og draga hud yver utanpå dykk og gjeva ånd i dykk, og de skal livna upp att. Og de skal sanna at eg er Herren.»',
        7: 'Og eg spådde so som eg var fyresagd. Då vart det ei skråving medan eg spådde, og sjå, det tok til å braka, og beini drog seg imot kvarandre, bein til bein.',
        8: 'Og eg såg, og sjå, det kom senar og kjøt på deim, og det drog seg hud utanpå deim. Men ånd var det ikkje i deim.',
        9: 'Og han sagde med meg: «Spå til anden! Spå, menneskjeson, og seg med anden: So segjer Herren, Herren: Kom, du ande, frå dei fire vindar og anda på desse drepne menner, so dei kann livna upp att!»',
        10: 'Og eg spådde so som han sette meg til. Og anden kom i deim, og dei livna, og dei stod på føterne sine, ein ovleg, ovleg stor her.',
        11: 'Og han sagde med meg: «Menneskjeson! Desse beini, dei er heile Israels-lyden. Sjå, dei segjer: «Turre er våre bein; vår von vart um inkje, det er ute med oss.»',
        12: 'Spå difor og seg med deim: So segjer Herren, Herren: Sjå, eg opnar graverne dykkar og let dykk, lyden min, risa upp or graverne dykkar, og eg vil føra dykk til Israels land.',
        13: 'Og de skal sanna at eg er Herren når eg opnar graverne dykkar og let dykk, folket mitt, risa upp or graverne dykkar.',
        14: 'Og eg vil senda min ande i dykk, og de skal livna upp att, og eg vil lata dykk få bu i landet dykkar. Og de skal sanna at eg er Herren; eg hev tala og vil setja det i verk, segjer Herren.»',
        15: 'Herrens ord kom til meg; han sagde:',
        16: 'Og du, Menneskjeson! Tak deg ein trestav og skriv på honom: «For Juda og dei Israels-born som er med honom.» Og tak deg ein annan stav og skriv på honom: «For Josef, ein stav for Efraim og all Israels-lyden som er med honom!»',
        17: 'Legg deim so i hop, ein attåt hin, so du fær deim til ein stav, og dei vert til eitt i handi di.',
        18: 'Og når landsmennerne dine segjer til deg: «Vil du ikkje lata oss få vita kva du meiner med dette?»',
        19: 'tala då til deim: «So segjer Herren, Herren: Sjå, eg tek Josefs stav, som er i Efraims hand, og Israels ætter som er med honom, og eg legg deim attåt Judas stav og gjer deim til ein stav, so dei vert til eitt i handi mi.»',
        20: 'Og stavarne som du skriv på, skal du halda i handi di framfor augo på deim.',
        21: 'Og du skal tala til deim: «So segjer Herren, Herren: Sjå, eg tek Israels-borni burt frå dei folki som dei for til, og eg vil samla deim frå alle stader og føra deim inn i landet sitt.',
        22: 'Og eg vil gjera deim til eitt folk i landet, på Israelsfjelli, og ein konge skal vera konge yver deim alle, og dei skal aldri meir vera tvo folk, og aldri meir vera sundbytte i tvo rike.',
        23: 'Og dei skal aldri meir sulka seg med dei ufysne avgudarne sine og med styggjorne sine eller med nokor av alle misgjerningarne sine. Og eg vil fri deim ut frå alle sine bustader, der dei hev synda, og eg vil reinsa deim, og dei skal vera mitt folk, og eg vil vera deira Gud.',
        24: 'Og min tenar David skal vera konge yver deim, og ein hyrding skal vera åt deim alle. Og i mine lover skal dei ferdast, og mine bod skal dei halda og gjera etter deim.',
        25: 'Og dei skal bu i det landet som eg gav min tenar Jakob, der som federne dykkar budde. Dei skal bu i det, dei sjølve og borni deira og barneborni deira, æveleg, og David, min tenar, skal vera deira fyrste, æveleg.',
        26: 'Og eg vil gjera ei fredspakt med deim, ei ævepakt med deim skal det vera. Og eg vil busetja deim og lata deim aukast og setja min heilagdom midt ibland deim æveleg.',
        27: 'Og min bustad skal vera yver deim, og eg skal vera deira Gud, og dei skal vera mitt folk.',
        28: 'Og folki skal sanna at eg er Herren som helgar Israel, når min heilagdom vert verande millom deim æveleg.»',
    },
    38: {
        1: 'Og Herrens ord kom til meg; han sagde:',
        2: 'Menneskjeson! Vend di åsyn mot Gog i Magoglandet, fyrste yver Ros, Mesek og Tubal, og spå mot honom!',
        3: 'Og du skal segja: So segjer Herren, Herren: Sjå, eg vil finna deg, Gog, fyrste yver Ros, Mesek og Tubal.',
        4: 'Og eg vil snu deg um og krøkja krokar i munnvikarne dine og føra deg ut med all din her, hestar og ridarar, i full herbunad alle saman, ein heil mannfjølde med store skjoldar og små, med sverd i hand alle saman.',
        5: 'Persar og ætiopar og putæar er med deim, alle saman med skjold og hjelm,',
        6: 'Gomer og alle hans herskarar, Togarma-lyden, lengst or Norderland og alle hans herskarar; mange folkeslag hev du med deg.',
        7: 'Herbu deg og gjer deg reidug, du og alle herflokkarne dine, som hev samla seg til deg, og du må varda deim vel.',
        8: 'Etter mange dagar kjem turen til deg, når åri renn ut, skal du koma til eit land som er berga undan for sverd, sanka frå mange folkeslag, uppå Israelsfjelli, som stødt låg i øyde. Men no er det ført ut frå folkeslagi, og trygt bur dei alle saman.',
        9: 'Og du skal draga dit upp; som ei stormflaga skal du koma, som ei sky skal du vera til å skyla landet, du og alle herskararne dine og mange folkeslag med deg.',
        10: 'So segjer Herren, Herren: Og det skal henda den dagen, at ord skal koma upp i ditt hjarta, og du skal tenkja ein illrådig tanke',
        11: 'og segja: «Eg vil fara upp mot eit land utan verjevollar, eg vil koma på desse som er i ro, som bur trygt: alle saman bur dei utan verjemur, og bommar og portar vantar dei.»',
        12: 'Til å rana ran og gjera herfang er du komen, og til å leggja di hand på uppatt-bygde øydestader, mot eit folk som er sanka frå folkeslag, og som el seg til bufe og gods, som er busett på jord-navlen.',
        13: 'Sjeba og Dedan og kjøpmenner frå Tarsis og alle deira ungløvor skal segja med deg: «Kjem du hit og vil rana ran? Hev du drege i hop dine herskarar til å gjera herfang, til å føra burt sylv og gull, til å taka bufe og gods, til å rana ran i det store?»',
        14: 'Difor, spå, menneskjeson, og seg med Gog: So segjer Herren, Herren: Den dagen då mitt folk Israel bur trygt, skal du då ikkje få vita det?',
        15: 'Og du skal koma frå din stad langt nord i heimen, du og mange folkeslag med deg, ridande på hestar alle saman, ein stor skare og veldug her.',
        16: 'Og du skal fara upp mot mitt folk Israel og skyla landet med ei sky. I dei siste dagarne skal det henda, då let eg deg koma yver landet mitt, so folkeslagi skal læra å kjenna meg, når eg syner min heilagdom på deg, Gog, framfor augo på deim.',
        17: 'So segjer Herren, Herren: Er det du som eg tala um i forne dagar gjenom mine tenarar, profetarne i Israel, som spådde i dei dagarne, år for år, at eg vilde lata deg koma yver deim?',
        18: 'Og det skal henda den same dagen, den dagen Gog kjem yver Israelslandet, segjer Herren, Herren, då skal harmen min koma upp i mi nos.',
        19: 'Og i min brennhug, i min logande vreide talar eg: Sanneleg, den dagen skal det vera ein stor jordskjelv yver Israelslandet.',
        20: 'Og skjelva for mi åsyn skal fiskarne i havet og fuglarne under himmelen og dyri på marki og alt kreket som krek på jordi og kvart eit menneskje som er på jord-yta. Og rivna skal fjelli, og rynja skal hamrarne, og kvar ein mur skal falla til jordi.',
        21: 'Og eg vil kalla sverd imot honom på alle mine fjell, segjer Herren, Herren; sverd skal dei svinga mot kvarandre.',
        22: 'Og eg vil halda dom yver honom med sott og med blod. Og hyljande regn og haglande steinar, eld og svåvel vil eg lata regna yver honom og yver hans herskarar og yver dei mange folkeslag som er med honom.',
        23: 'Og eg vil syna meg stor og heilag og gjera meg kjend for augo på mange folkeslag. Og dei skal sanna at eg er Herren.',
    },
    39: {
        1: 'Og du, menneskjeson! Spå mot Gog og seg: So segjer Herren, Herren: Sjå, eg vil finna deg, Gog, fyrste yver Ros, Mesek og Tubal.',
        2: 'Og eg vil snu deg um og jaga deg fram og få deg til å koma upp, lengst or Norderland, og lata deg koma upp på Israelsfjelli.',
        3: 'Og eg vil slå bogen din utor vinstre handi og lata pilerne dine detta utor høgre handi.',
        4: 'På Israelsfjelli skal du falle, du og all herskararne dine og folkeslagi som er med deg. Til rovfuglar av alle slag og til villdyri på marki gjev eg deg til mat.',
        5: 'Utyver marki skal du falla; for eg hev tala, segjer Herren, Herren.',
        6: 'Og eg vil senda eld på Magog og på dei som bur trygt i øylandi. Og dei skal sanna at eg er Herren.',
        7: 'Og mitt heilage namn vil eg gjera kunnigt midt ibland mitt folk Israel, og aldri meir vil eg lata mitt heilage namn verta vanhelga, og folkeslagi skal sanna at eg er Herren, heilag i Israel.',
        8: 'Sjå, det kjem, og det hender, segjer Herren, Herren; det er dagen som eg hev tala um.',
        9: 'Då skal dei som bur i Israels-byarne ganga ut og gjera upp eld og kveikja upp med herbunader; både med store skjoldar og med små, med bogar og med piler og med stavar og mot spjot. Og med dette til brennefang skal dei elda i sju år.',
        10: 'Dei skal ikkje henta ved or marki og ikkje hogga i skogarne, for dei skal elda med herbunaderne. Og dei skal rana sine ransmenner og herja sine herjarar, segjer Herren, Herren.',
        11: 'Og det skal henda same dagen, at eg vil gjeva Gog ein gravstad i Israel, Ferdamannsdalen austum havet, og han skal stengja vegen for ferdafolket. Der skal dei gravleggja Gog og heile mannemugen hans, og dei skal kalla det Gogs-muge-dalen.',
        12: 'I sju månader skal Israels-lyden jorda deim, det skal vera til å reinsa landet.',
        13: 'All landslyden skal jorda deim, og det skal gjera deim namnfræge den dagen eg syner meg herleg, segjer Herren, Herren.',
        14: 'Og dei skal velja ut menner som stødt skal fara um i landet og jorda deim som der hadde fare fram, deim som hadde vorte liggjande etter utyver jordi; det skal vera til å reinsa det. Når sju månader er lidne, skal dei taka til med leitingi.',
        15: 'Når då yverfararane fer um i landet og fær sjå eit mannebein, skal dei setja upp et merke attmed det til gravarane fær grave det ned i Gogs-muge-dalen.',
        16: 'Ogso eit bynamn skal vera Hamona. Soleis skal dei reinsa landet.',
        17: 'Og du, menneskjeson! So segjer Herren, Herren: Seg med kvar fljugande fuglen og kvart eit udyr på marki: Samla dykk saman og kom! Sanka dykk frå alle stader til slagtofferet mitt, som eg hev slagta åt dykk, eit stort slagtoffer på Israelsfjelli. Og de skal eta kjøt og drikka blod.',
        18: 'Kjøt av kjempor skal de få eta, og blod frå fyrstar på jord skal de få drikka; verar, lamb og bukkar og uksar, gjødde i Basan alle i hop.',
        19: 'De skal få eta feitt til de vert mette, og drikka blod til det vert drukne, av slagtofferet mitt som eg slagtar åt dykk.',
        20: 'Og de skal verta mette ved mitt bord med ridehestar og vognhestar, med kjempor og hermenner av alle slag, segjer Herren, Herren.',
        21: 'Og eg vil syna mitt storvelde millom folki, og alle folki skal sjå min dom, som eg hev halde, og mi hand, som eg hev lagt på deim.',
        22: 'Og Israels-lyden skal sanna at eg er Herren, deira Gud, frå den dagen og framleides.',
        23: 'Og folkeslagi skal skyna at det var for sine misgjerningar Israels-lyden vart burtførd, for di dei for med svik imot meg, so eg laut løyna mi åsyn for deim og gjeva deim i fiendehand, so dei fall for sverd alle saman.',
        24: 'Etter deira ureinskap og misgjerningar for eg fram imot deim og løynde mi åsyn for deim.',
        25: 'Difor, so segjer Herren, Herren: No vil eg enda Jakobs fangetid og miskunna all Israels-lyden, og eg vil vera ihuga for mitt heilage namn.',
        26: 'Og dei skal bera si skjemsla og all si utrue framferd mot meg, når dei bur trygt i landet sitt, og ingen skræmer deim.',
        27: 'Når eg fører deim tilbake frå folkeslagi og sankar deim or fiendelandi og helgar meg på deim for augo på dei mange folk,',
        28: 'då skal dei sanna at eg er Herren, deira Gud, med di at eg førde deim burt til folkeslagi, men samlar deim no inn i deira eige land og ikkje leiver ein einaste av deim etter meg der.',
        29: 'So vil eg aldri meir løyna mi åsyn for deim, for eg hev rent ut min ande yver Israels-lyden, segjer Herren, Herren.',
    },
    40: {
        1: 'I det fem og tjugande året etter me vart burtførde, ved nyårsleite, den tiande dagen i månaden, i det fjortande året etter byen vart teken - nett den dagen kom Herrens hand yver meg, og han førde meg dit burt.',
        2: 'I syner frå Gud førde han meg til Israelsland. Og han sette meg ned på eit ovhøgt fjell, og uppå det var det liksom ein uppbygd by i sud.',
        3: 'Og han førde meg dit burt. Og sjå, der var det ein mann, og han var sjåande til mest som kopar, og han heldt eit linsnøre i handi og ei mælestong. Og han stod i porten.',
        4: 'Og mannen tala til meg: «Menneskjeson! Sjå med augo dine og lyd etter med øyro dine og hugfest alt det eg syner deg! For du er førd hit so eg kann få syna deg det. Kunngjer for Israels-lyden alt det du ser!»',
        5: 'Og sjå, det var ein mur utanum huset rundt ikring. Og mannen heldt mælestongi i handi, ho var seks alner lang, kvar aln ei handbreidd lenger enn ei vanleg aln. Og han mælte breiddi på muren: ei stong, og høgdi: ei stong.',
        6: 'So kom han åt ein port som snudde i aust, og han steig uppetter troppestigi. Og han mælte ein dørstokk i porten: ei stong breid, og so ein dørstokk til: ei stong breid.',
        7: 'Og kvart vaktrom var ei stong langt og ei stong breidt. Og millom vaktromi var det fem alner. Og dørstokken i porten innmed forhalli i porten innvendes var ei stong.',
        8: 'Han mælte forhalli i porten innvendes; ei stong.',
        9: 'Og han mælte forhalli i porten: åtte alner, og stolparne hans: tvo alner. Og forhalli i porten låg på innsida.',
        10: 'Og vaktromi i porten mot aust var tri på kvar sida, alle tri like store. Og stolparne på båe sidorne var like store.',
        11: 'So mælte han dørviddi på porten: ti alner, og lengdi på porten: trettan alner.',
        12: 'Og det var ei sval på ein aln framfor vaktromi, og ei sval på ei aln på hi sida. Og kvart vaktrom var seks alner på den eine sida og seks alner på hi.',
        13: 'So mælte han porten frå taket på det eine vaktromet til taket på hitt. Breiddi var fem og tjuge alner. Dør var mot dør.',
        14: 'Og han gjorde stolparne seksti alner. Og burtåt stolparne rakk fyregarden, med porten rundt ikring.',
        15: 'Og frå framsida på inngangsporten til framsida på forhalli i den indre porten var det femti alner.',
        16: 'Og det var vindaugo med fast grind fyre på vaktromi og på stolparne deira innantil imot porten rundt ikring, og likeins på hallerne. Og soleis var det vindaugo rundt ikring innantil, og på stolparne var det palmor.',
        17: 'So let han meg koma til den ytre fyregarden, og sjå, der var kovar og eit steinlagt golv i fyregarden rundt ikring. Det var tretti kovar på steingolvet.',
        18: 'Og steingolvet var frammed sideveggjerne på portarne, jamlangt med portlengderne; det var det lægre steingolvet.',
        19: 'Han mælte breiddi frå framsida åt den nedre porten til den ytre framsida åt den indre fyregarden: eit hundrad alner austetter og nordetter.',
        20: 'So mælte han lengdi og breiddi på den porten som snudde i nord, på den ytre fyregarden.',
        21: 'Den og hadde tri vaktrom på kvar sida, og likeins stolpar og haller like store som i den fyrste porten; femti alner lang og fem og tjuge alner breid.',
        22: 'Og vindaugo og hallerne og palmorne her var like stor som i den porten som vende i aust. Og dei steig upp i porten på sju troppestig, og hallerne låg framanfor deim.',
        23: 'Og ein port til den indre fyregarden var der midt imot porten i nord og i aust, og han mælte eit hundrad alner frå ein port til hin.',
        24: 'So let han meg ganga sudetter, og sjå, der var ein port som snudde i sud. Og han mælte stolparne og hallerne der og; dei heldt same mål som hine.',
        25: 'Det var vindaugo på honom og på hallerne rundt ikring, likeins som dei andre vindaugo. Han var femti alner lang og fem og tjuge alner breid.',
        26: 'Og troppi der hadde sju stig, og hallerne var framanfor deim, og på stolparne var det palmor, ein på kvar sida.',
        27: 'Og det var ein port til den indre fyregarden på sudsida. Og han mælte frå denne porten til sudporten: eit hundrad alner.',
        28: 'So let han meg koma til den indre fyregarden gjenom sudporten. Og han mælte sudporten: han heldt same mål som hine.',
        29: 'Og vaktromi og stolparne og hallerne der heldt same mål som hine. Og det var vindaugo på honom og på hallerne rundt ikring. Han var femti alner lang og fem og tjuge alner breid.',
        30: 'Og det var haller rundt ikring: fem og tjuge alner lange og fem alner breide.',
        31: 'Og hallerne der låg utåt den ytre fyregarden. Og på stolparne var det palmor. Og troppi hadde åtte stig.',
        32: 'So let han meg koma til din indre fyregarden på austsida. Og han mælte porten: han heldt same mål som hine.',
        33: 'Vaktromi og stolparne og hallerne der heldt same mål som hine. Og det var vindaugo på honom og på hallerne rundt ikring. Han var femti alner lang og fem og tjuge alner breid.',
        34: 'Og hallerne der låg ut åt den ytre fyregarden. Og det var palmor på stolparne på båe sidor. Og troppi hadde åtte stig.',
        35: 'So let han meg koma til nordporten. Og han mælte honom: han heldt same mål som hine.',
        36: 'Likeins vaktromi, stolparne og hallerne der. Og det var vindaugo rundt ikring. Han var femti alner lang og fem og tjuge alner breid.',
        37: 'Og stolparne der stod innmed den ytre fyregarden, og det var palmor på stolparne på båe sidor. Og troppi hadde åtte stig.',
        38: 'Og det var ein kove med dørgap i portstolparne. Der skulde dei skylja brennofferet.',
        39: 'Og i forhalli åt porten var det tvo bord på kvar sida til å slagta brennofferet og syndofferet og skuldofferet på.',
        40: 'Og innmed den ytre sideveggen som snudde i nord, når ein steig upp i port-inngangen, var det tvo bord, og innmed hin sideveggen på forhalli åt porten stod det og tvo bord.',
        41: 'Det vart då fire bord innmed kvar sidevegg på porten, soleis åtte i alt. På deim skulde dei slagta.',
        42: 'Og til brennofferet var det fire bord av tilhoggen stein, ei og ei halv aln lange, og ei og ei halv aln breide og ei aln høge. På deim skulde dei leggja ambodi til å slagta brennofferet og slagtofferet med.',
        43: 'Og tvigreina nabbar, ei tver hand breide, var feste på huset rundt ikring, men på bordi skulde offerkjøtet leggjast.',
        44: 'Og utanfor indreporten var det kovar åt songarane i den indre fyregarden, innmed sideveggen på nordporten, og framsida deira snudde i sud. Ei koverad låg innmed sideveggen på austporten, med framsida mot nord.',
        45: 'Og han sagde med meg: Denne koveradi som snur i sud med framsida si, er åt dei prestarne som hev umsut med det som skal gjerast i huset.',
        46: 'Men den koveradi som snur i nord med framsida si, er åt dei prestarne som hev umsut med altartenesta; dei er Sadoks-søner, dei av Levi-sønerne som kjem nær til Herren og tener honom.',
        47: 'So mælte han fyregarden: eit hundrad alner lang og eit hundrad alner breid i firkant. Og altaret var framfyre huset.',
        48: 'So let han meg koma til forhalli i huset. Og han mælte stolparne i forhalli: fem alner på den eine sida og fem alner på hi, og breiddi på porten: tri alner på den eine sida og tri alner på hi.',
        49: 'Forhalli var tjuge alner lang og elleve alner breid, og ho hadde troppestig som dei steig upp til henne på. Og det var sulor innmed stolparne, ei på kvar sida.',
    },
    41: {
        1: 'So let han meg koma til tempelsalen. Og han mælte stolparne: seks alner breide på den eine sida og seks alner på hi; det er breiddi på tjeldbudi.',
        2: 'Og dørgapet var ti alner breidt, og sideveggjerne innmed døri var fem alner på kvar sida. So mælte han lengdi på det: fyrti alner, og breiddi: tjuge alner.',
        3: 'Sidan gjekk han inn i det inste romet. Og han mælte dørstolparne: tvo alner kvar, og døri: seks alner, og breiddi på døri: sju alner.',
        4: 'Og han mælte lengdi på det: tjuge alner, og breiddi: tjuge alner, beint innåt templet! So sagde han med meg: «Dette er det høgheilage.»',
        5: 'So mælte han husveggen: seks alner, og breiddi på sidekovarne: fire alner, rundt ikring heile huset.',
        6: 'Og sidekovarne låg, kove attmed kove, i tri høgder, tretti i rad, og dei rakk inni den muren som huset hadde mot sidekovarne rundt ikring, so dei hadde studnad. Men dei studde seg ikkje i sjølve husveggen.',
        7: 'Og viddi rundt ikring auka på for sidekovarne uppetter og uppetter; for hussvali gjekk uppetter og uppetter rundt kringum huset. Difor vidkast huset uppetter, og soleis steig ein upp frå nedste høgdi gjenom den millomste til den høgste.',
        8: 'Og eg såg at huset låg på ein pall som nådde rundt ikring, og grunnvollarne åt sidekovarne var ei full stong, seks alner til kanten.',
        9: 'Tjukkleiken på utveggen åt sidekovarne var fem alner. Og romet millom sidekovarne på huset',
        10: 'og hine kovarne hadde ei vidd på tjuge alner kringum huset, rundt ikring.',
        11: 'Og inngangarne til sidekovarne låg ut åt dette romet, ein inngang i nord og ein i sud. Og breiddi på romet som var att, var fem alner breidt rundt ikring.',
        12: 'Og den bygnaden som låg innmed det fråskilde tunet på vestsida, var sytti alner breid, og veggen på bygnaden var fem alner tjukk, rundt ikring, og nitti alner lang.',
        13: 'Og han mælte huset: hundrad alner langt, og det fråskilde tunet og bygnaden med vegg: hundrad alner lange.',
        14: 'Og framsida på huset og det fråskilde tunet mot aust var hundrad alner på breidd.',
        15: 'So mælte han lengdi på den bygnaden som låg på baksida innmed det fråskilde tunet, og svalerne på båe sidor åt bygnaden: hundrad alner. Likeins det indre templet og hallerne i fyregarden,',
        16: 'dørstokkarne og vindaugo med dei faste grindar og svalerne rundt ikring i deira tri høgder, romi innmed dørstokken, som var klædde med tre, rundt ikring, likeins høgdi frå jordi upp åt vindaugo. Og attfyre vindaugo var det lemmar.',
        17: 'Uppyver døri, både inn imot det indre romet og utetter, og elles utyver heile veggen, innan og utan, var det utmælte bolkar.',
        18: 'Og der var det gjort kerubar og palmor, so at det var ei palma millom tvo kerubar, kvar kerub hadde tvo andlit;',
        19: 'eit mannsandlit mot palma på den eine sida og eit ungløve-andlit mot palma på hi. So var gjort på heile huset rundt ikring.',
        20: 'Frå jordi til uppyver døri var kerubar og palmor gjorde, slik var tempelveggen.',
        21: 'Templet hadde firkanta dørskier, og framsida på heilagdomen såg like eins ut.',
        22: 'Og altaret var av tre, tri alner høgt og tvo alner langt, og det hadde hyrno sine, og langsida og veggjerne var av tre. Og han tala til meg: «Dette er bordet som stend framfor Herrens åsyn.»',
        23: 'Og templet og heilagdomen hadde tvo dører.',
        24: 'Og dørerne var tvihurda, kvar hurd med gangjarn; tvihurda var den eine og tvihurda var den andre.',
        25: 'Og på deim, på tempeldørerne, var det gjort kerubar og palmor likeins som på veggjerne. Og det var eit vartak av tre på framsida åt forhalli utantil.',
        26: 'Og det var vindaugo med fast grind og palmor på sideveggjerne åt forhalli, på båe sidor, likeins på sidekovarne i huset og på vartaki.',
    },
    42: {
        1: 'So let han meg ganga ut i den ytre fyregarden den vegen som gjekk nordetter. Og han let meg koma til den kovebygnaden som låg midt framfor det fråskilde tunet og beint imot bygnaden i nord,',
        2: 'til langsida som var på hundrad alner, med inngang i nord, men breiddi var femti alner.',
        3: 'Beint imot eit stykke på tjuge alner av den indre fyregarden og midt framfor steingolvet i den ytre fyregarden, var det sval mot sval i tri høgder.',
        4: 'Og framanfor kovarne var det ein ti alner breid gang innetter, ein veg på ei aln; og dørerne deira snudde i nord.',
        5: 'Og dei øvste kovarne var dei minste, for svalerne tok burt meir rom frå deim enn frå dei nedste og dei millomste i bygnaden.',
        6: 'For dei låg i tri høgder, men hadde ikkje stolpar so som dei i fyregarden; difor smalkast det meir for dei øvste kovarne enn for dei nedste og millomste, frå jordi og uppetter.',
        7: 'Og ein mur som var utanfor, frammed kovarne, imot den ytre fyregarden, gjekk framanfor kovarne. Han var femti alner lang.',
        8: 'For lengdi på dei kovarne som låg imot den ytre fyregarden, var femti alner, men sjå, mot templet: hundrad alner.',
        9: 'Og nedunder desse kovarne var inngangen mot aust, når ein gjekk inn i deim frå den ytre fyregarden.',
        10: 'Der fyregardsmuren imot aust var på det tjukkaste, framanfor det fråskilde tunet og framanfor bygnaden, var det kovar.',
        11: 'Og ein veg gjekk framanfor deim. Dei såg ut som dei kovarne som låg mot nord, like lange og like breide; likeins alle utgangar og tilskipnader elles og dørgap.',
        12: 'Og likeins dørerne på dei kovarne som låg mot sud; det var ei dør der som vegen tok til, vegen frammed den muren som høyrde til, vegen austetter når ein gjekk inn i deim.',
        13: 'So sagde han med meg: «Kovarne mot nord og kovarne mot sud, som ligg innmed det fråskilde tunet, dei er heilage kovar, der prestarne som er nær Herren skal eta det høgheilage. Der skal dei leggja det høgheilage, både grjonofferet og syndofferet og skuldofferet, for staden er heilag.',
        14: 'Når prestarne gjeng inn, so skal dei ikkje ganga ut att or heilagdomen og ut i den ytre fyregarden, men der skal dei leggja av seg klædi som dei hev gjort tenesta i, for dei er heilage. Dei skal taka på seg andre klæde og so ganga dit der folket må vera.»',
        15: 'Og då han hadde gjort mælingi frå seg i det indre huset, fylgde han meg ut gjenom den porten som hadde framsida mot aust, og der mælte han rundt ikring.',
        16: 'Han mælte austsida med mælestongi: fem hundrad stenger etter mælestongi rundt ikring.',
        17: 'Han mælte nordsida: fem hundrad stenger etter mælestongi rundt ikring.',
        18: 'Sudsida mælte han: fem hundrad stenger etter mælestong.',
        19: 'Han snudde og gjekk mot vestsida; han mælte fem hundrad stenger etter mælestong.',
        20: 'På dei fire sidorne mælte han det. Det hadde ein mur rundt ikring: fem hundrad stenger lang og fem hundrad breid, til å skilja det heilage frå det som var uhelga.',
    },
    43: {
        1: 'So let han meg ganga til porten, den porten som snudde i aust.',
        2: 'Og sjå, herlegdomen åt Israels Gud kom austan-ifrå, og ljomen av honom var som ljomen av store vatn, og jordi skein av herlegdomen hans.',
        3: 'Og den syni som eg såg, var likeins som den syni eg hadde set då eg kom og skulde leggja byen i øyde, og som den syni eg hadde set burtmed Kebarelvi, soleis var synerne. Og eg fall å gruve på mitt andlit.',
        4: 'Og Herrens herlegdom for inn i huset gjenom den porten som snudde i aust.',
        5: 'Og anden lyfte meg upp og førde meg inn i den indre fyregarden. Og sjå, Herrens herlegdom fyllte huset.',
        6: 'Og eg høyrde einkvan tala til meg utor huset, og ein mann stod attmed meg.',
        7: 'Og han sagde med meg: «Menneskjeson! Dette er den staden der kongsstolen min og fotskammelen min skal standa, og der eg vil bu hjå Israels-borni æveleg. Og Israels-borni skal aldri meir vanhelga mitt heilage namn, korkje dei eller kongarne deira, med hordomen sin og med liki av kongarne sine og med offerhaugarne sine -',
        8: 'dei som sette dørstokken sin attmed dørstokk min og dørskierne sine attmed dørskierne mine, so det berre var veggen millom meg og deim. Og på den måten gjorde dei mitt heilage namn ureint med styggedomen sin som dei for med, so eg laut tyna deim i min vreide.',
        9: 'No skal dei hava sin hordom og liki av kongarne sine langt burt ifrå meg, so eg vil bu hjå deim æveleg.',
        10: 'Du menneskjeson! Kunngjer for Israels-lyden um dette huset, so dei må blygjast for misgjerningarne sine, og mæla den vel tilmåta bygnaden.',
        11: 'Og når dei blygjest for alt det dei hev gjort, so skal du kunngjera for deim skapnaden på huset og skipnaden i det: utgangar og inngangar og skapnader på alt og alle fyresegnerne um alt, ja, all skapnaden og alle loverne um det; og rit det av framfor deira augo, so dei kann koma i hug heile skapnaden på huset og fyresegnerne um det, og gjera etter deim.',
        12: 'Dette er lovi um huset: På toppen av fjellet skal heile umkverven kringum det vera høgheilag. Sjå, dette er lovi um huset.',
        13: 'Og dette er måli på altaret i alnetal, kvar aln ei handbreidd lengre enn ei vanleg aln: det skal vera eit fotstykke, ei aln høgt og ei aln breidt, og kantlisti på kanten av det ei spann breid rundt ikring. Dette er underlaget åt altaret.',
        14: 'Og frå fotstykket på jordi uppåt den nedste skori skal det vera tvo alner, og breiddi skal vera ei aln, og frå den litle skori uppåt den store skori skal det vera fire alner, og breiddi skal vera ei aln.',
        15: 'Og «Guds-fjellet» skal vera fire alner, og frå «Guds-åren» skal dei fire horni stinga upp.',
        16: 'Og Guds-åren skal vera tolv alner lang og tolv alner breid, firkanta med fire jamlange sidor.',
        17: 'Og skori skal vera fjortan alner lang og fjortan alner breid, med fire jamlange sidor, og kantlisti kringum henne ei halv aln tjukk, og fotstykket ei aln rundt ikring, og tropperne skal snu i aust.»',
        18: 'Og han sagde med meg: «Menneskjeson! So segjer Herren, Herren: Dette er fyresegnerne um altaret den dagen det vert gjort, so ein kann ofra brennoffer og skvetta blod på det.',
        19: 'Du skal gjeva dei levitiske prestarne, dei som er av Sadoks-ætti, og som stig nær meg og tener meg, segjer Herren, Herren, ein ungukse til syndoffer.',
        20: 'Og du skal taka noko av blodet hans og strjuka på dei fire altarhorni og på dei fire skorhyrno og på kantlisti rundt ikring; soleis skal du reinsa det frå synd og gjera soning for det.',
        21: 'Og du skal taka syndofferuksen, og honom skal dei brenna på mynstringsplassen åt huset, utanfor heilagdomen.',
        22: 'Og andre dagen skal du ofra ein lytelaus bukk til syndoffer, og dei skal reinsa altaret frå synd likeins som dei reinsa det med uksen.',
        23: 'Når du då hev gjort frå deg reinsingi, skal du leida fram ein lytelaus ungukse og ein lytelaus ver or saueflokken.',
        24: 'Du skal leida deim fram for Herrens åsyn, og prestarne skal strå salt på deim og ofra deim til brennoffer åt Herren.',
        25: 'I sju dagar skal du ofra ein bukk til syndoffer kvar dag; og ein ungukse og ein ver or saueflokken, båe lytelause, skal du ofra.',
        26: 'I sju dagar skal dei gjera soning for altaret og reinsa det og vigja det.',
        27: 'Og når dei hev fullenda dei dagarne, skal prestarne åttande dagen og fremetter ofra brennofferet dykkar og takkofferi dykkar på altaret, og eg vil hava hugnad i dykk, segjer Herren, Herren.»',
    },
    44: {
        1: 'So let han meg koma tilbake til den ytre porten åt heilagdomen, den som snudde i aust, og han var attlaten.',
        2: 'Og Herren sagde med meg: «Denne porten skal vera attlaten og ikkje verta opna, og ingen skal ganga inn igjenom honom; for Herren, Israels Gud, hev gjenge inn igjenom honom, difor skal han vera attlaten.',
        3: 'Men fyrsten, han er fyrste, han kann sitja der og eta brød framfor Herrens åsyn. Han skal ganga inn vegen til forhalli i porten, og same vegen skal han ganga ut att.»',
        4: 'So let han meg koma gjenom nordporten og fram for huset. Og eg såg, og sjå, Herrens herlegdom fyllte Herrens hus. Og eg fall å gruve på mitt andlit.',
        5: 'Då sagde Herren med meg: «Menneskjeson! Legg deg på hjarta og sjå med augo dine og lyd etter med øyro dine alt det som eg segjer med deg um alle fyresegnerne og loverne um Herrens hus. Og du må hugfesta inngangen til huset og alle utgangarne frå heilagdomen.',
        6: 'Og du skal segja med dei tråssuge, med Israels-lyden: So segjer Herren, Herren: No lyt det vera nok med all styggedomen dykkar, du Israels-lyd,',
        7: 'at de let framande, u-umskore på hjarta og u-umskore på kjøt koma inn i heilagdomen min, og vera der til å vanhelga huset mitt, når de ofra brødet mitt, feita og blod. Soleis braut dei pakti mi, attåt alle hine styggjorne dykkar.',
        8: 'Og de hev ikkje sjølve greidt med tenesta i heilagdomarne mine, men de sette andre i staden for dykk til å gjera tenesta i heilagdomen min.',
        9: 'So segjer Herren, Herren: Ingen framand med u-umskore hjarta og u-umskore kjøt skal koma inn i min heilagdom, ingen av alle dei framande som bur millom Israels-borni.',
        10: 'Men dei levitarne som gjekk burt ifrå meg, då Israel for vilt, og villa seg burt ifrå meg etter dei ufysne avgudarne sine, skal bera si misgjerning,',
        11: 'og i heilagdomen min skal dei gjera vakttenesta ved portarne og likeins tenesta i huset; dei skal slagta brennofferet og slagtofferet åt folket, og dei skal standa framfor deira åsyn og tena deim.',
        12: 'Etter di dei tente deim framfor dei ufysne avgudarne deira og var støytestein til misgjerning for Israels-lyden, difor hev eg lyft mi hand imot deim, segjer Herren, Herren, og dei skal bera si misgjerning.',
        13: 'Og dei skal ikkje koma meg nær til å gjera prestetenesta framfyre meg og ikkje koma nær noko av alle mine heilage ting, dei høgheilage tingi; men dei skal bera skammi si og skjemdarverki som dei hev gjort.',
        14: 'Og eg vil setja deim til å greida med tenesta i huset, med alt tenar-arbeidet i det og alt som der er å gjera.',
        15: 'Men dei levitiske prestarne, Sadoks-sønerne, som greidde med tenesta i heilagdomen min då Israels-borni villa seg burt ifrå meg, dei skal koma nær til meg og tena meg, og dei skal standa framfor mi åsyn og ofra åt meg feita og blod, segjer Herren, Herren.',
        16: 'Dei skal ganga inn i min heilagdom, og dei skal koma inn åt mitt bord og tena meg, og dei skal greida med mi tenesta.',
        17: 'Når dei då kjem inn i portarne åt den indre fyregarden, skal dei klæda seg i linklæde, det må ikkje koma ullan på deim når dei tener i portarne åt den indre fyregarden og inni huset.',
        18: 'Linhuvor skal dei hava på hovudet og linbrøker um mjødmarne sine; dei skal vera umgyrde med noko som veld sveite.',
        19: 'Og når dei gjeng ut i den ytre fyregarden, til folket i den ytre fyregarden, skal dei hava av seg dei klædi som dei hev gjort tenesta i, og leggja deim i dei heilage kovarne, og dei skal taka på seg andre klæde, so dei ikkje skal helga folket med klædi sine.',
        20: 'Og dei skal ikkje raka hovudet, men ikkje heller lata håret veksa som det vil; dei skal klyppa håret sitt.',
        21: 'Og vin skal ingen av prestarne drikka, når dei gjeng inn i den indre fyregarden.',
        22: 'Enkja eller fråskild kvinna skal dei ikkje taka til kona, men møyar, ætta frå Israels-lyden. Men ei enkja som er enkja etter prest, kann det taka.',
        23: 'Og dei skal læra folket mitt å skilja millom heilagt og vanheilagt, og kunngjera deim skilnaden på ureint og reint.',
        24: 'Og i rettssaker skal dei standa fram og døma; etter mine fyresegner skal dei døma i deim. Og mine lover og fyresegner skal dei halda på alle mine høgtider, og kviledagarne mine skal dei halda heilage.',
        25: 'Og til eit lik skal ingen av deim ganga inn, so han vert urein; einast for far og for mor og for son og for dotter, for bror, og for syster som ikkje hev havt mann, kann dei gjera seg ureine soleis.',
        26: 'Og etter reinsingi hans, skal dei telja sju dagar for honom.',
        27: 'Og den dagen han gjeng inn i heilagdomen, i den indre fyregarden, og tener i heilagdomen, skal han ofra syndofferet sitt, segjer Herren, Herren.',
        28: 'Og det skal vera arvluten deira: Eg vil vera arvluten deira. Og nokor eiga skal de ikkje gjeva deim i Israel; eg er deira eiga.',
        29: 'Grjonofferet og syndofferet og skuldofferet, deim skal dei eta, og alt som er bannlyst i Israel, skal høyra deim til.',
        30: 'Det aller fyrste av allslags grøda og alle offergåvor av alle slag skal vera åt prestarne. Og det fyrste gropet de mel, skal de gjeva presten, so velsigning må koma yver huset ditt.',
        31: 'Noko sjølvdaudt eller ihelrive av fugl eller fe må ikkje prestarne eta.',
    },
    45: {
        1: 'Og når de lutar ut landet til odel, so skal de gjeva ei gåva åt Herren, ein heilag-lut av landet, fem og tjuge tusund på lengdi og ti tusund på breiddi. Det skal vera heilagt i all si vidd rundt ikring.',
        2: 'Av dette skal det vera åt heilagdomen fem hundrad på lengd og fem hundrad på breidd, i ein firkant rundt ikring. Og til utmark rundt kringum det femti alner.',
        3: 'Soleis skal du etter dette målet mæla fem og tjuge tusund på lengdi og ti tusund på breiddi, og i det skal heilagdomen, det høgheilage, vera.',
        4: 'Det er ein heilag-lut av landet. Han skal vera åt prestarne som gjer tenesta i heilagdomen, dei som fær koma nær til Herren og tena honom. Det skal vera til hustufter åt deim og til heilag-tufter åt heilagdomen.',
        5: 'Og fem og tjuge tusund på lengdi og ti tusund på breiddi skal vera åt levitarne, tenarane i huset. Til eiga skal dei hava tjuge gardar.',
        6: 'Og til eiga åt byen skal de gjeva fem tusund på breiddi og fem og tjuge tusund på lengdi, jamsides med luten åt heilagdomen; det skal vera åt Israels-lyden.',
        7: 'Og fyrsten skal hava sin lut på båe sidorne åt heilagdoms-luten og by-eigedomen, frammed heilagdoms-luten og by-eigedomen, på vestsida vestetter, og på austsida, austetter, og han skal vera jamlang med ein arvlut åt ei ætt, frå grensa åt havet til austgrensa.',
        8: 'Dette skal han hava til land, til eiga i Israel. Og fyrstarne mine skal aldri meir tyngja folket mitt, men lata Israels-lyden hava landet som det vert etla åt ætterne.',
        9: 'So segjer Herren, Herren: No lyt det vera nok, de fyrstar i Israel! Få burt vald og trælking, og gjer rett og rettferd! Haldt upp med å driva folket mitt frå gard og grunn! segjer Herren, Herren.',
        10: 'Rett vegt og rett efa og rett bat skal de hava.',
        11: 'Ein efa og ein bat skal vera like store, so ein bat er tiandeparten av ein homer og ein efa tiandeparten av ein homer; etter homeren skal deira mål vera.',
        12: 'Ein sekel skal vera tjuge gera. Tjuge seklar, fem og tjuge seklar, femtan seklar, det skal vera ei mina hjå dykk.',
        13: 'Dette er den reida de skal gjeva: setteparten av ein efa av kvar homer kveite, og likeins skal de gjeva setteparten av ein efa av kvar homer bygg.',
        14: 'Og den visse reida av olje, rekna i bat: tiandeparten av ein bat av kvar kor - som er ti bat eller ein homer, for ein homer er ti bat -',
        15: 'og av småfeet eitt lamb av tvo hundrad frå det vatsrike beitelandet i Israel til grjonoffer og til brennoffer og takkoffer, til å gjera soning for deim, segjer Herren, Herren.',
        16: 'All landslyden skal vera skuldig til denne reida åt fyrsten i Israel.',
        17: 'Men fyrsten skal hava den skyldnaden: å leggja til brennofferi og grjonofferet og drykkofferet i helgarne og på nymånedagarne og på kviledagarne, på alle høgtiderne hjå Israels-lyden. Han skal greida med syndofferet og grjonofferet og takkofferi til å gjera soning for Israels-lyden.',
        18: 'So segjer Herren, Herren: Den fyrste dagen i fyrste månaden skal du taka ein lytelaus ungukse og reinsa heilagdomen frå synd.',
        19: 'Og presten skal taka noko av syndofferblodet og strjuka på dørskierne i huset og på dei fire hyrno på altarskori og på dørskierne i porten åt den indre fyregarden.',
        20: 'Og likeins skal du gjera den sjuande dagen i månaden for den som hev synda uviljande eller av fåkunna. Og de skal gjera soning for huset.',
        21: 'Den fjortande dagen i fyrste månaden skal de halda påskehelg. I høgtidi, i sju dagar, skal de eta usyrt brød.',
        22: 'Den same dagen skal fyrsten ofra ein ukse til syndoffer for seg og for all landslyden.',
        23: 'Og dei sju høgtidsdagarne skal han ofra åt Herren eit brennoffer: sju lytelause uksar og sju lytelause verar kvar dag i dei sju dagarne, og til syndoffer ein bukk kvar dag.',
        24: 'Og til grjonoffer skal han ofra ein efa med kvar ukse og ein efa med kvar ver og ein åttung olje med kvar efa.',
        25: 'Den femtande dagen i sjuande månaden, på høgtidi, skal han gjera likeins både syndofferet og med brennofferet og med grjonofferet og oljen i sju dagar.',
    },
    46: {
        1: 'So segjer Herren, Herren: Porten åt den indre fyregarden, den som snur i aust, skal vera attlaten dei seks vyrkedagarne, men kviledagen skal han vera open, og nymånedagen skal han vera open.',
        2: 'Og fyrsten skal ganga inn vegen til port-forhalli utanfrå og stana attmed port-dørskii. Og prestarne skal ofra brennofferet hans og takkofferi hans, og han skal tilbeda på portdørstokken og sidan ganga ut att. Men porten skal ikkje stengjast fyrr det kveldar.',
        3: 'Og um kviledagarne og nymånarne skal landslyden tilbeda attmed inngangen til den same porten for Herrens åsyn.',
        4: 'Og brennofferet som fyrsten skal føra fram for Herren på kviledagen, skal vera seks lytelause lamb og ein lytelaus ver,',
        5: 'og til grjonoffer ein efa med veren, men med lambi slikt grjonoffer som han sjølv vil gjeva, og ein åttung olje med kvar efa.',
        6: 'Og um nymånedagen ein lytelaus ungukse og seks lamb og ein ver; lytelause skal dei vera.',
        7: 'Og til grjonoffer skal han ofra ein efa med uksen og ein efa med veren, men med lambi so mykje som han hev råd til, og ein åttung olje med kvar efa.',
        8: 'Og når fyrsten gjeng inn, skal han ganga inn vegen til port-forhalli, og same vegen skal han ganga ut att.',
        9: 'Og når landslyden gjeng inn for Herrens åsyn på høgtiderne, då skal den som gjeng inn gjenom nordporten og skal tilbeda, ganga ut att gjenom sudporten, og den som gjeng inn gjenom sudporten, skal ganga ut gjenom nordporten; ingen skal snu og ganga ut att gjenom den porten han kom inn, men dei skal ganga ut beint fram.',
        10: 'Og fyrsten skal ganga inn midt ibland deim når dei gjeng inn, og når dei gjeng ut, skal dei ganga ut saman.',
        11: 'Og i helgarne og høgtiderne skal grjonofferet vera ein efa med kvar ukse og ein efa med kvar ver, men med lambi slikt som kvar sjølv vil gjeva, og ein åttung olje med kvar efa.',
        12: 'Og når fyrsten vil ofra eit friviljugt offer, anten brennoffer eller takkoffer til friviljugt offer åt Herren, då skal dei lata upp åt honom den porten som snur i aust, og han skal ofra brennofferet sitt og takkofferi sine like eins som han gjer på kviledagen. So skal han ganga ut att, og ein skal lata att porten etter han er utgjengen.',
        13: 'Og eit årsgamalt lytelaust lamb skal du dagstødt ofra til brennoffer åt Herren; kvar morgon skal du ofra det.',
        14: 'Og til grjonoffer skal du kvar morgon ofra setteparten av ein efa og tvo pottar olje til å lata uppi mjølet. Det er eit grjonoffer åt Herren - ævelege fyresegner, stødt og stendig.',
        15: 'Og dei skal ofra lambet og grjonofferet og oljen kvar morgon til eit stendigt brennoffer.',
        16: 'So segjer Herren, Israels Gud: Um fyrsten gjev einkvan av sønerne sine noko av odelen sin til gåva, so vert det hans odelen; åt sønerne hans skal det vera, dei fær det til odel og eiga.',
        17: 'Men gjev han einkvan av tenarane sine noko av odelen sin til gåva, då skal det vera hans til fridomsåret, men då skal fyrsten få det att. Odelen hans er det, åt sønerne hans skal det vera.',
        18: 'Og fyrsten må ikkje taka odelsjord frå folket og på den måten trengja deim burt frå deira eiga - av si eigi eiga skal han lata sønerne sine erva - so ikkje folket mitt vert spreidt, kvar burt frå si eiga.',
        19: 'So let han meg koma gjenom den inngangen som var attmed porten, til dei heilage kovarne som var etla prestarne, og som snudde i nord. Og sjå, der var det eit rom lengst burte mot vest.',
        20: 'Og han sagde med meg: «Dette er den staden der prestarne skal koka skuldofferet og syndofferet, og der dei skal baka grjonofferet, so dei ikkje skal turva bera det ut i den ytre fyregarden og på den måten helga lyden.»',
        21: 'So let han meg stiga ut i den ytre fyregarden og let meg ganga kringum dei fire hyrno på fyregarden. Og sjå, i kvart hyrna på fyregarden var det eit tun.',
        22: 'I dei fire hyrno på fyregarden var dei inngjerde, desse tuni; fyrti alner lange og tretti alner breide, desse fire tuni i hyrno hadde same målet.',
        23: 'Og det gjekk ein murgard rundt ikring inni deim, rundt ikring i alle fire. So var det gjort gruvor til å koka i nedantil med murgarden rundt ikring.',
        24: 'Og han sagde med meg: «Dette er kokehusi der tenarane i huset skal koka slagtofferi åt folket.»',
    },
    47: {
        1: 'So let han meg tilbake til inngangen åt huset. Og sjå, det kom vatn ut under dørstokken på huset mot aust, for framsida på huset snudde i aust. Og vatnet rann ned frå høgre sida på huset sunnanfor altaret.',
        2: 'Sidan let han meg ganga ut gjenom nordporten og fylgde meg ikring utanfor til ytreporten, den porten som snur austetter. Og sjå, det kom vatn vellande fram undan høgresida.',
        3: 'Mannen gjekk no austetter med mælesnor i handi og mælte tusund alner. Og han hadde meg til å vada yver vatnet, vatn til okleleden.',
        4: 'So mælte han endå tusund alner til og hadde meg til å vada yver vatnet, vatn til knes. So mælte han endå tusund alner og hadde meg til å vada yver vatnet; det gjekk då upp til lenderne.',
        5: 'So mælte han endå tusund alner, og no var det ei å som eg ikkje kunde vada. For vatnet hadde vakse, vatn til å symja i, ei å som ikkje let seg vada.',
        6: 'Og han sagde med meg: «Hev du set det, menneskjeson?» Og han let meg ganga tilbake uppå å-breiddi.',
        7: 'Då eg kom dit att, stod det på å-breiddi ei mengd med tre på den sida og hi sida.',
        8: 'Og han sagde med meg: «Dette vatnet renn ut til austbygderne og fløymar ned i øydemarki. So fell det ut i havet. Når det er flødt ut i havet, vert vatnet der friskt.',
        9: 'Og det skal henda at alt kvikjende som liver og yr alle stader der den tviflaumande åi renn, skal livna, og det skal verta ei ovmengd med fisk. For når dette vatnet kjem dit, so vert det helsebot og liv alle stader der åi renn.',
        10: 'Og det skal henda at fiskarar skal standa frammed vatnet frå En-Gedi til En-Eglajim; fiskestøde for garnbruk skal det og vera. Fisken der skal vera i ovende mengd, kvar etter sitt slag, som i Storhavet.',
        11: 'Men myrarne og deplarne der skal ikkje verta friske; dei er etla åt saltet.',
        12: 'Og frammed åi, på båe å-breidderne, skal det veksa upp frukttre av alle slag. Lauvet på deim skal ikkje visna og frukti ikkje trjota. Kvar månad skal dei bera ny frukt, for vatnet åt deim renn ut frå heilagdomen. Og frukti på deim skal vera til mat, og lauvet til lækjedom.»',
        13: 'So segjer Herren, Herren: Dette er landskilet, og innan det skal de taka dykk landet til odel etter Israels tolv ætter. Åt Josef skal det vera tvo luter.',
        14: 'Og de skal taka det til odel, den eine som den andre, for di eg hev rett upp handi mi på at eg vilde gjeva federne dykkar det; so skal då dette landet verta utskift til odel og eiga.',
        15: 'Dette er då landskilet: På nordsida: frå Storhavet langs med Hetlonvegen til ein kjem til Sedad,',
        16: 'Hamat, Berota, Sibrajim, som ligg millom Damaskus-skilet og Hamat-skilet, det millomste Haser, som ligg innmed Havran-skilet.',
        17: 'Soleis er då landskilet frå havet til Hasar-Enon attmed Damaskus-skilet og framleides endå lenger nordetter upp til Hamat-skilet. Dette er nordsida.',
        18: 'Austsida - millom Havran og Damaskus og millom Gilead og Israelsland - er Jordan: frå nordskilet til Austhavet skal de mæla. Dette er austsida.',
        19: 'På sudsida, mot sud; frå Tamar til Meribotvatnet attmed Kades, til bekken, alt til Storhavet. Dette er sudsida, mot sud.',
        20: 'På vestsida er Storhavet frå dette skilet til dit der ein gjeng til Hamat. Dette er vestsida.',
        21: 'Og de skal byta landet millom dykk etter Israels ætter.',
        22: 'Og soleis skal det vera: De skal skifta det ut til odel åt dykk sjølve og dei framande som bur hjå dykk og hev fenge born ibland dykk. Og dei skal vera for dykk som dei som er fødde og borne i sjølve Israel; odelsjord skal dei hava med dykk ibland ætterne i Israel.',
        23: 'Og so skal det vera: I den ætti der den framande bur, der skal de gjeva honom odelsjordi si, segjer Herren, Herren.',
    },
    48: {
        1: 'Og dette er namni på ætterne: Frå nordenden - vest ved Storhavet - langs med Hetlonvegen til dit som ein gjeng til Hamat, Hasar-Enan attmed Damaskus-skilet, der skal dei eiga frå austsida til havet: Dan, ein lut.',
        2: 'Frammed Dan-skilet, frå austsida til vestsida: Asser, ein lut.',
        3: 'Frammed Asser-skilet, frå austsida til vestsida: Naftali, ein lut.',
        4: 'Frammed Naftali-skilet, frå austsida til vestsida: Manasse, ein lut.',
        5: 'Frammed Manasse-skilet, frå austsida til vestsida: Efraim, ein lut.',
        6: 'Frammed Efraim-skilet, frå austsida til vestsida: Ruben, ein lut.',
        7: 'Frammed Ruben-skilet, frå austsida til vestsida: Juda, ein lut.',
        8: 'Frammed Juda-skilet, frå austsida til vestsida, skal vera den gåva som de skal gjeva, fem og tjuge tusund breid og so langt som ein av luterne åt ætterne frå austsida til vestsida, og midt der inni skal heilagdomen vera.',
        9: 'Den gåva som de skal gjeva Herren, skal vera fem og tjuge tusund lang og ti tusund breid.',
        10: 'Og åt desse skal den heilage gåva vera: Åt prestarne: i nord fem og tjuge tusund og i vest ti tusund på breiddi, og i aust ti tusund på breiddi, og i sud fem og tjuge tusund på lengdi. Og midt der inni skal Herrens heilagdom vera.',
        11: 'Åt prestarne som er helga utav Sadoks-sønerne, dei som tok vare på tenesta mi og ikkje for vilt då Israels-borni villa seg burt, soleis som levitarne villa seg burt,',
        12: 'åt deim skal gåva vera utav jordgåva, eit høgheilagt stykke frammed skilet mot levitarne.',
        13: 'Og levitarne skal hava, frammed skilet mot prestarne, fem og tjuge tusund på lengdi og ti tusund på breiddi; all lengdi skal vera fem og tjuge tusund og breiddi ti tusund.',
        14: 'Og dei skal ikkje selja noko av det, og ikkje skal noko bytast burt, og landsens fyrstegrøda må ikkje ganga yver i annan manns eiga, for ho er vigd Herren.',
        15: 'Og dei fem tusund som er att av breiddi, frammed dei fem og tjuge tusund, skal vera uvigd, åt byen, til bustader og til utmark, og byen skal liggja der i midten.',
        16: 'Dette er då målet på honom, nordsida fire tusund og fem hundrad og sudsida fire tusund og fem hundrad, austsida fire tusund og fem hundrad, og vestsida fire tusund og fem hundrad.',
        17: 'Og det skal vera utmark åt byen: nordetter tvo hundrad og femti, og sudetter tvo hundrad og femti, og austetter tvo hundrad og femti, og vestetter tvo hundrad og femti.',
        18: 'Og det som vert att på lengdi frammed den heilage gåva: ti tusund austetter og ti tusund vestetter - for det skal vera frammed den heilage gåva - grøda av det skal vera til brød åt arbeidsfolket i byen.',
        19: 'Og arbeidsfolket i byen, av alle ætterne i Israel, dei skal bruka det.',
        20: 'Heile gåva skal vera fem og tjuge tusund på lengdi og fem og tjuge tusund på breiddi; som ein firkant skal de gjeva den heilage gåva med by-eiga.',
        21: 'Og det som vert att, skal vera åt fyrsten, på båe sidorne av den heilage gåva og by-eiga, frammed luten på fem og tjuge tusund, alt burtåt austskilet og vestetter frammed dei fem og tjuge tusund, alt burtåt vestskilet jamsides med luterne åt ætterne; det skal vera åt fyrsten. Og den heilage gåva og husens heilagdom skal liggja midt imillom.',
        22: 'Det som då ligg millom Juda-skilet og Benjamin-skilet - med levit-eiga og by-eiga i midten - det skal vera åt fyrsten.',
        23: 'So kjem hine ætterne: Frå austsida til vestsida: Benjamin, ein lut.',
        24: 'Og frammed Benjamin-skilet, frå austsida til vestsida: Simeon, ein lut.',
        25: 'Og frammed Simeon-skilet, frå austsida til vestsida: Issakar, ein lut.',
        26: 'Frammed Issakar-skilet, frå austsida til vestsida: Sebulon, ein lut.',
        27: 'Frammed Sebulon-skilet, frå austsida til vestsida: Gad, ein lut.',
        28: 'Frammed Gad-skilet, på sudsida, i sud: der skal skilet ganga frå Tamar, yver Meribavatni attmed Kades, til bekken, alt burtåt Storhavet.',
        29: 'Dette er det landet som de skal skifta ut av odelen åt ætterne i Israel, og dette er luterne deira, segjer Herren, Herren.»',
        30: 'Og dette er utgrensa åt byen: På nordsida fire tusund og fem hundrad på mål.',
        31: 'Og byportarne, uppkalla etter ætterne i Israel: Tri portar i nord: Ruben-porten, ein; Juda-porten, ein; Levi-porten, ein.',
        32: 'Og på austsida: fire tusund og fem hundrad, og tri portar: Josef-porten, ein; Benjamin-porten, ein; Dan-porten, ein.',
        33: 'Og sudsida: fire tusund og fem hundrad på mål, og tri portar: Simeon-porten, ein; Issakar-porten ein; Sebulon-porten, ein.',
        34: 'Vestsida: fire tusund og fem hundrad; dei tri portarne der: Gad-porten, ein; Asser-porten, ein; Naftali-porten, ein.',
        35: 'Rundt ikring: attan tusund. Og namnet på byen skal vera frå den dagen: «Herren er der».',
    },
}
